INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('dc12246e-c329-5b23-a79c-dd14308c3a11', '919c09cf-725c-5b33-ae47-325eb397ba20', '53bb2125-3fb7-5aa1-a7b7-577ccdfee086', 1, 8, 'በዚያን ጊዜ ከለዳውያን ቀርበው አይሁድን በንጉሡ በናቡከደነፆር ዘንድ ከሰሱ።'),
  ('4c127b69-79c4-5906-a9ff-db1eb0fd9e3d', '919c09cf-725c-5b33-ae47-325eb397ba20', '53bb2125-3fb7-5aa1-a7b7-577ccdfee086', 2, 9, 'እንዲህም አሉት፦“ንጉሥ ሆይ፥ ለዘለዓለም ኑር!'),
  ('7eb2c00d-177a-5250-a528-9f7175f29789', '919c09cf-725c-5b33-ae47-325eb397ba20', '53bb2125-3fb7-5aa1-a7b7-577ccdfee086', 3, 10, 'ንጉሥ ሆይ! የመለከትንና የእንቢልታን፥ የመሰንቆንና የክራርን፥ የበገናንና የዋሽንትን፥ የዘፈንንም ሁሉ ድምፅ የሚሰማ ሰው ሁሉ ወድቆ ለወርቁ ምስል ይስገድ፥'),
  ('2ed5dbac-dc8c-51d8-a5a7-223844053944', '919c09cf-725c-5b33-ae47-325eb397ba20', '53bb2125-3fb7-5aa1-a7b7-577ccdfee086', 4, 11, 'ወድቆም የማይሰግድ በሚነድድ እሳት እቶን ውስጥ ይጣላል ብለህ በቃልህ አዘህ ነበር።'),
  ('675b24de-9042-5acb-ae7e-f4573086e300', '919c09cf-725c-5b33-ae47-325eb397ba20', '53bb2125-3fb7-5aa1-a7b7-577ccdfee086', 5, 12, 'አሁንም ንጉሥ በባቢሎን ሀገሮች ለሚሠራ ሥራ የሾምኻቸው፥ ከአይሁድ ወገን የሚሆኑ ትእዛዝህን እምቢ ያሉ፥ አምላክህን ያላመለኩ፥ ለሠራኸውም ለወርቁ ምስል ያልሰገዱ ሚሳቅና ሲድራቅ፥ አብደናጎም የሚባሉ ሦስት ሰዎች አሉ።”'),
  ('27469ffb-293e-5a9f-abe4-aee3d14d1d20', '919c09cf-725c-5b33-ae47-325eb397ba20', '53bb2125-3fb7-5aa1-a7b7-577ccdfee086', 6, 13, 'ያንጊዜም ናቡከደነፆር ተቈጣ፤ በቍጣም ሲድራቅንና ሚሳቅን፥ አብደናጎንም ያመጡ ዘንድ አዘዘ፤ እነዚህንም ሰዎች ወደ ንጉሡ ፊት አመጡአቸው።'),
  ('086adb92-f5ac-5aaa-ab76-bf0f78e3be7a', '919c09cf-725c-5b33-ae47-325eb397ba20', '53bb2125-3fb7-5aa1-a7b7-577ccdfee086', 7, 14, 'ናቡከደነፆርም፥ “ሲድራቅና ሚሳቅ አብደናጎም ሆይ፥ አምላኬን አለማምለካችሁ፥ ላቆምሁትም ለወርቁ ምስል አለመስገዳችሁ እውነት ነውን?'),
  ('3560bbdb-1c0d-5949-ab27-1002c405634a', '919c09cf-725c-5b33-ae47-325eb397ba20', '53bb2125-3fb7-5aa1-a7b7-577ccdfee086', 8, 15, 'አሁንም የመለከቱንና የእንቢልታውን፥ የመሰንቆውንና የክራሩን፥ የበገናውንና የዋሽንቱን የዘፈኑንም ሁሉ ድምፅ በሰማችሁ ጊዜ ወድቃችሁ ላሠራሁት ምስል ብትሰግዱ መልካም ነው፤ ባትሰግዱ ግን በዚያ ጊዜ በሚነድድ እሳት እቶን ውስጥ ትጣላላችሁ፤ ከእጄስ የሚያድናችሁ አምላክ ማን ነው?” ብሎ ተናገራቸው።'),
  ('3c877715-0d38-526b-a6b1-b910afa444c5', '919c09cf-725c-5b33-ae47-325eb397ba20', '53bb2125-3fb7-5aa1-a7b7-577ccdfee086', 9, 16, 'ሲድራቅና ሚሳቅ፥ አብደናጎም መለሱ፤ ንጉሡንም፥ “ናቡከደነፆር ሆይ! በዚህ ነገር እንመልስልህ ዘንድ አንፈልግም።'),
  ('fe31c22f-bda5-55bd-aab2-b1f7693442b2', '919c09cf-725c-5b33-ae47-325eb397ba20', '53bb2125-3fb7-5aa1-a7b7-577ccdfee086', 10, 17, 'ንጉሥ ሆይ! እኛ የምናመልከው አምላክ በሰማይ አለ፥ ከሚነድደው ከእሳቱ እቶን ያድነን ዘንድ ይችላል፤ ከእጅህም ያድነናል፤'),
  ('fb4d6d0c-1b5c-509e-aa8f-cbcbe9ae685d', '919c09cf-725c-5b33-ae47-325eb397ba20', '53bb2125-3fb7-5aa1-a7b7-577ccdfee086', 11, 18, 'ንጉሥ ሆይ! ይህም ባይሆን፥ አማልክትህን እንዳናመልክ፥ ላቆምኸውም ለወርቁ ምስል እንዳንሰግድለት ዕወቅ” አሉት።'),
  ('f764e638-ee54-5536-a1ab-9b321264d570', '919c09cf-725c-5b33-ae47-325eb397ba20', '53bb2125-3fb7-5aa1-a7b7-577ccdfee086', 12, 19, 'የዚያን ጊዜም ናቡከደነፆር በሲድራቅና በሚሳቅ፥ በአብደናጎም ላይ ቍጣ ሞላበት፤ የፊቱም መልክ ተለወጠባቸው፤ እርሱም ተናገረ፤ የእቶንም እሳት ይነድድ ከነበረው ይልቅ ሰባት እጥፍ አድርገው እንዲያነድዱት አዘዘ።'),
  ('035ca572-7b78-5922-ac80-198bb074bbd5', '919c09cf-725c-5b33-ae47-325eb397ba20', '53bb2125-3fb7-5aa1-a7b7-577ccdfee086', 13, 20, 'ሲድራቅንና ሚሳቅን፥ አብደናጎንም አስረው፥ ወደሚነድድ ወደ እቶን እሳት ይጥሉአቸው ዘንድ ኃያላን ሰዎችን አዘዘ።'),
  ('d7ca0651-e768-58ca-ae27-2e091f65d88a', '919c09cf-725c-5b33-ae47-325eb397ba20', '53bb2125-3fb7-5aa1-a7b7-577ccdfee086', 14, 21, 'የዚያን ጊዜም እነዚያ ሰዎች ከሰናፊላቸውና ከጫማቸው፥ ከቀሚሳቸውና ከመጎናጸፊያቸውም፥ ከቀረውም ልብሳቸው ጋር አስረው በሚነድድ በእቶን እሳት ውስጥ ጣሉአቸው።'),
  ('705e6300-e4a4-5808-a89b-7903f6979967', '919c09cf-725c-5b33-ae47-325eb397ba20', '53bb2125-3fb7-5aa1-a7b7-577ccdfee086', 15, 22, 'የንጉሡም ትእዛዝ እጅግ ስለ በረታ፥ የእቶኑም እሳት እጅግ ስለሚነድድ፥ ሲድራቅንና ሚሳቅን፥ አብደናጎንም የጣሉአቸውን ሰዎች የእሳቱ ወላፈን ገደላቸው።'),
  ('442207dd-194e-58dc-a2b1-39352e6bdaa5', '919c09cf-725c-5b33-ae47-325eb397ba20', '53bb2125-3fb7-5aa1-a7b7-577ccdfee086', 16, 23, 'እነዚህም ሦስቱ ሰዎች ሲድራቅና ሚሳቅ፥ አብደናጎም ታስረው በሚነድደው በእቶኑ እሳት መካከል ወደቁ።'),
  ('171985f7-15ac-52e7-a7ad-c69b3c293182', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 1, 24, 'በእሳት መካከልም ተመላለሱ እግዚአብሔርንም ፈጽመው አመሰገኑት።'),
  ('2a83679c-385d-5dc2-a7ce-b6f6fd5ff9e6', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 2, 25, 'አዛርያም ቁሞ እንዲህ ብሎ ጸለየ፥ በእሳቱም መካከል ምስጋናን ጀመረ፦'),
  ('23e8e668-2dc9-5ba3-a1ce-570478fcca79', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 3, 26, '“የአባቶቻችን አምላክ እግዚአብሔር ይክበር፤'),
  ('b6fd341d-e5ad-5fd4-a041-b0edf20047cd', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 4, 27, 'ባመጣህብን ነገር ሁሉ አንተ ጻድቅ ነህና፤ ሥራህ ሁሉ የታመነ ነው፤ ሥርዐትህም ሁሉ የቀና ነው፤'),
  ('9a88b1ea-044c-5182-a00d-58958ea1da6d', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 5, 28, 'ባደረግህብን ነገር ሁሉ ፍትሕ ርትዕ አደረግህ፤'),
  ('54ff97ce-2510-5f9e-aa34-329e779462dd', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 6, 29, 'የተውንህ እኛ በድለናል፤ ስተናልና'),
  ('cbb434ea-c53a-5ffc-a8f7-b8bbe1510055', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 7, 30, 'መልካም ይሆንልን ዘንድ፥'),
  ('b738d583-750f-5d06-a004-55246e22834c', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 8, 31, 'ያመጣህብንንና ያደረግህብንን ሁሉ በእውነተኛ ፍርድህ አደረግህብን።'),
  ('32c01578-8bfa-51c3-a194-db4552d69e7a', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 9, 32, 'ከአንተ ፈጽመው በራቁ ኀጢአተኞችና ወንጀለኞች በሚሆኑ በጠላቶቻችን እጅ ጣልኸን፤'),
  ('19fff91f-8d33-5ab0-ac7f-5cb5c5ba8489', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 10, 33, 'አሁንም አፋችንን እንከፍት ዘንድ አገባባችን አይደለም'),
  ('485e4a5d-b174-5b18-a133-e0d945c67547', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 11, 34, 'ስለ ስምህ ብለህ ፈጽመህ አሳልፈህ አትስጠን።'),
  ('6ec61173-797c-5113-a624-88086a85d056', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 12, 35, 'ይቅርታህንም አታርቅብን።'),
  ('4f02391a-bd5e-5f88-a68b-4dc1e4969e8c', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 13, 36, 'ዘራቸውን እንደ ሰማይ ኮከብ፥'),
  ('a17c0eef-8c52-5f45-a69e-12c2b60a55af', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 14, 37, 'ስለ ኀጢአታችን በሀገሩ ሁሉ ዛሬ የተዋረድን ሆን።'),
  ('47e16fba-207a-522c-ac15-076f2afc42f2', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 15, 38, 'በዚህ ወራት አለቃ የለም፤ ነቢይም የለም፤ ንጉሥም የለም፤'),
  ('98eb5ba7-bb86-5830-a088-8b4e7f9e4630', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 16, 39, 'በየዋህ ልቡና በቀና መንፈስ ተቀበልልን እንጂ፤'),
  ('4059fe3c-73d9-5f5e-a234-e631119a66d1', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 17, 40, 'እንደ ጊደሮችና ላሞች፥'),
  ('cedcab02-f2d3-57d6-aee4-84e1132d0caa', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 18, 41, 'አሁንም በፍጹም ልቡናችን እንከተልሃለን፤ እንፈራሃለንም፤'),
