  ('7ae6bf49-b039-5dc0-a736-e76f83100cfb', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 61, 84, 'እስራኤል እግዚአብሔርን ያመሰግኑታል፤'),
  ('7ac843b4-e4a4-5b18-abbb-47adcb2b410d', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 62, 85, 'የጌታ ካህናት እግዚአብሔርን ያመሰግኑታል፤'),
  ('d6e0706d-c3b1-530c-a37e-65a6800ab572', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 63, 86, 'የጌታ ባሪያዎች እግዚአብሔርን ያመሰግኑታል፤'),
  ('668879e3-7476-5e76-a439-58d2eb2446a2', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 64, 87, 'መንፈስና የጻድቃን ነፍሳት እግዚአብሔርን ያመሰግኑታል፤'),
  ('bd2dbdc9-7ce9-5194-a03a-d97801073b9a', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 65, 88, 'አናንያና አዛርያ፥ ሚሳኤልም እግዚአብሔርን ያመሰግኑታል፤'),
  ('c7c2a9eb-14b3-540a-aea8-962e3aabc32e', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 66, 89, 'እግዚአብሔር ከሞትና ከሲኦል እጅ አድኖናልና፥ ከሚነድድም ከምድጃው እሳት አስጥሎናልና፥ ከነበልባሉም መካከል አውጥቶናልና፤ ለእግዚአብሔር ተገዙ፤ ስሙንም አመስግኑት፤ ቸር ነውና ምሕረቱም ለዘለዓለም ነውና።'),
  ('9eeb0ac3-9faf-5c42-afbe-c1f817f894e0', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 67, 90, 'የአማልክትን አምላክ እግዚአብሔርን የምትፈሩ ሁላችሁ እግዚአብሔርን አመስግኑት፤ ተገዙለት፤ አመስግኑትም፤ ቸርነቱ ለዘለዓለም ነውና።'),
  ('f1322b9b-58ac-51bf-ad5b-4b51b413a7b8', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 68, 91, 'ንጉሡ ናቡከደነፆርም ሲያመሰግኑ ሰምቶ ተደነቀ፤ ፈጥኖም ተነሣ፤ አማካሪዎቹንም፥ “ሦስት ሰዎች አስረን በእሳት ውስጥ ጥለን አልነበረምን?” ብሎ ተናገራቸው። እነርሱም፥ “ንጉሥ ሆይ! እውነት ነው” አሉት።'),
  ('76ea7c8a-d86e-5fe2-a8f4-d817882a5558', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 69, 92, 'ንጉሡም፥ “እኔ የተፈቱ በእሳቱም መካከል የሚመላለሱ አራት ሰዎችን በዚያ አያለሁ፤ ምንም የነካቸው የለም፤ የአራተኛውም መልክ የእግዚአብሔርን ልጅ ይመስላል” አለ።'),
  ('bfc07bc9-b13e-544a-aeea-c22934aa7f05', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 70, 93, 'የዚያን ጊዜም ናቡከደነፆር ወደሚነድደው ወደ እሳቱ እቶን በር ቀርቦ፥ “እናንተ የልዑል አምላክ ባሪያዎች፥ ሲድራቅና ሚሳቅ፥ አብደናጎም፥ ኑ ውጡ” ብሎ ተናገራቸው። ሲድራቅና ሚሳቅ፥ አብደናጎም ከእሳቱ መካከል ወጡ።'),
  ('c7d6a3f9-a2a9-5558-a033-93ce30451caa', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 71, 94, 'አለቆች፥ መሳፍንቱና ሹሞቹም፥ አዛዦቹና የንጉሡ ኃያላን ተሰብስበው እሳቱ ሰውነታቸውን እንዳልበላው፥ የራሳቸውም ጠጕር እንዳልተነካ፥ ሰናፊላቸውም እንዳልተለወጠ፥ የእሳቱም ሽታ በላያቸው እንዳልነበረ አዩ።'),
  ('be913d91-b857-5d87-abe1-449b9bb32e66', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 72, 95, 'ንጉሡም በፊታቸው ለእግዚአብሔር ሰገደ፥ ናቡከደነፆርም መልሶ እንዲህ አለ፦ መልአኩን የላከ፥ ከአምላካቸውም በቀር ማንንም አምላክ እንዳያመልኩ፥ ለእርሱም እንዳይሰግዱ ሰውነታቸውን አሳልፈው የሰጡትን፥ የንጉሡንም ቃል የተላለፉትን፥ በእርሱ የታመኑትን ባሪያዎቹን ያዳነ፥ የሲድራቅና የሚሳቅ፥ የአብደናጎም አምላክ ይመስገን።'),
  ('632368d8-0ead-5343-a3f8-c23aa2944bcd', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 73, 96, 'እኔም እንደዚህ የሚያድን ሌላ አምላክ የለምና በሲድራቅና በሚሳቅ፥ በአብደናጎም አምላክ ላይ የስድብን ነገር የሚናገር ወገንና ሕዝብ በልዩ ልዩ ቋንቋም የሚናገሩ ይቈረጣሉ፤ ቤታቸውም ይዘረፋል ብየ አዝዣለሁ አለ።'),
  ('2e138c38-58e1-5b84-a658-bac19c9e97d7', '919c09cf-725c-5b33-ae47-325eb397ba20', '6f792aaf-cf0c-5400-a829-d4f47ba37403', 74, 97, 'የዚያን ጊዜም ንጉሡ፥ ሲድራቅን ሚሳቅንና አብደናጎንም በባቢሎን አውራጃ ውስጥ ሾማቸው፤ ከፍ ከፍም አደረጋቸው፤ በግዛቱ ያሉ አይሁድንም ሁሉ አስገዛላቸው።'),
  ('170dd86e-5dff-5aa4-ab17-8aa69295476d', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 1, 1, 'ከንጉሡ ከናቡከደነፆር፤ በምድር ሁሉ ወደሚቀመጡ ወገኖችና አሕዛብ፥ በልዩ ልዩ ቋንቋም ወደሚናገሩ ሁሉ፥ “ሰላም ይብዛላችሁ።'),
  ('6a5440d5-e028-57e9-ae38-5c228fa8880c', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 2, 2, 'ልዑል አምላክ በፊቴ ያደረገውን ተአምራቱንና ድንቁን እነግራችሁ ዘንድ ወደድሁ።'),
  ('a987b300-7bc0-599e-af6d-d72515bf0cf4', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 3, 3, 'ተአምራቱ እንዴት ታላቅ ነው! ድንቁም እንዴት ጽኑ ነው! መንግሥቱም የዘለዓለም መንግሥት ነው፤ ግዛቱም ለልጅ ልጅ ነው።'),
  ('8cd4f706-6232-5b9a-a62b-54aa040621a2', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 4, 4, '“እኔ ናቡከደነፆር በቤቴ ደስ ብሎኝ በአዳራሼም ተመችቶኝ ነበር።'),
  ('39d859e5-4698-5c32-a79b-c70a9868fd1d', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 5, 5, 'ሕልም አለምሁ፤ እርስዋም አስፈራችኝ፤ በአልጋዬም ላይ ታወክሁ፤ የራሴም ራእይ አስጨነቀኝ።'),
  ('571b942b-6529-52f1-a80a-e746e195c250', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 6, 6, 'ስለዚህ የሕልሜን ፍቺ እንዲያስታውቁኝ የባቢሎን ጠቢባን ሁሉ ወደ እኔ ይገቡ ዘንድ አዘዝሁ።'),
  ('a8d9faf8-bd16-5e61-a87f-cfb8c7145ff4', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 7, 7, 'የዚያን ጊዜም የሕልም ተርጓሚዎቹና አስማተኞቹ፥ ከለዳውያኑና ቃላተኞቹ ገቡ፤ ሕልሜንም በፊታቸው ተናገርሁ፤ ፍቺውን ግን አላስታወቁኝም።'),
  ('2f38e8fa-09e4-5ab1-ac56-7bc49d251413', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 8, 8, 'በመጨረሻም የእግዚአብሔር ቅዱስ መንፈስ ያለበት እንደ አምላኬ ስም ብልጣሶር የሚባለው ዳንኤል በፊቴ ገባ፤ እኔም እንዲህ አልሁት፦'),
  ('4ed57aed-2b42-5fc7-ab46-77e5cf213d66', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 9, 9, 'የጠቢባን አለቃ ብልጣሶር ሆይ! የእግዚአብሔር ቅዱስ መንፈስ በአንተ ውስጥ እንደ አለ፥ ከምሥጢርም ሁሉ የሚያስቸግርህ እንደሌለ ዐውቄአለሁና ያየሁትን የሕልሜን ራእይ፥ ፍቺውንም ንገረኝ።'),
  ('ef5cc5e8-b784-5145-af1c-bbdb1ba0587d', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 10, 10, 'በአልጋዬ ላይ ራእይ አየሁ፤ እነሆ በምድር መካከል ዛፍ ነበረ፤ ቁመቱም እጅግ ረዥም ነበረ።'),
  ('3be5215f-0a14-5765-a9ff-858a2aad07df', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 11, 11, 'ዛፉም ትልቅ ሆነ፤ በረታም፤ ቁመቱም እስከ ሰማይ ደረሰ፤ ቅርንጫፉም እስከ ምድር ሁሉ ዳርቻ ደረሰ።'),
  ('69bfa049-1eb8-56ee-a9b9-2a5e7e990c42', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 12, 12, 'ቅጠሎቹም የተዋቡ ነበሩ፤ ፍሬውም ብዙ ነበረ፤ ሁሉም ከእርሱ ይመገብ ነበረ፤ ከጥላውም በታች የዱር አራዊት ያርፉበት ነበር፥ በቅርንጫፎቹም ውስጥ የሰማይ ወፎች ይቀመጡ ነበር፤ ሥጋ ለባሹም ሁሉ ከእርሱ ይበላ ነበር።'),
  ('77952221-d73b-5af5-a710-03202888c3b5', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 13, 13, '“በአልጋዬም ላይ በሌሊት ራእይ አየሁ፤ እነሆም አንድ ቅዱስ ጠባቂ ከሰማይ ወረደ።'),
  ('a329cf76-c12e-5842-af93-661848e137ad', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 14, 14, 'በታላቅ ድምፅም እየጮኸ እንዲህ አለ፦ ዛፉን ቍረጡ፤ ቅርንጫፎቹንም ጨፍጭፉ፤ ቅጠሎቹንም አራግፉ፤ ፍሬውንም በትኑ፤ አራዊቱም ከበታቹ፥ ወፎቹም ከቅርንጫፉ ይታወኩ።'),
  ('763f60c9-ec25-5f5e-aebd-c840abbdd5e5', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 15, 15, 'ነገር ግን ሥሩንና ጉቶውን በምድር ውስጥ ተዉት፤ በመስክም ውስጥ በብረትና በናስ ማሰሪያ ታስሮ ይቈይ፤ በሰማይም ጠል ይረስርስ፤ እድል ፋንታውም በምድር ሣር ውስጥ ከአራዊት ጋር ይሁን።'),
  ('20e2f746-d962-52c2-a46e-4a45b101a580', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 16, 16, 'ልቡም ከሰው ልብ ይለወጥ፤ የአውሬም ልብ ይሰጠው፤ ሰባት ዘመናትም ይለፉበት።'),
  ('3839836f-ffbe-527c-a902-409917af73e8', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 17, 17, 'ልዑል እግዚአብሔር የሰዎችን መንግሥት እንዲገዛ፥ ለወደደውም እንዲሰጠው፥ ሕያዋን ያውቁ ዘንድ ይህ ነገር የጠባቂዎች ትእዛዝ፥ ይህም ፍርድ የቅዱሳን ቃል ነው፤ ሰውንም ትዕቢቱ ያዋርደዋል።'),
  ('0294d2f7-af83-52b8-a48f-3138928552c3', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '72c53cd3-3a8d-5596-afa1-86c40bf4f82b', 18, 18, 'እኔ ንጉሡ ናቡከደነፆር ያለምሁት ሕልም ይህ ነው፤ አንተም ብልጣሶር! ፍቺውን ንገረኝ፤ የመንግሥቴ ጠቢባን ሁሉ ፍቺውን ይነግሩኝ ዘንድ አልቻሉምና፤ ነገር ግን የእግዚአብሔር ቅዱስ መንፈስ በአንተ ውስጥ አለና አንተ ትችላለህ።”'),
  ('bb241063-bef1-546c-addf-dc51637c12c7', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '869518bc-715b-5607-a17c-9335ca153cb0', 1, 19, 'ያን ጊዜም ብልጣሶር የተባለው ዳንኤል አንድ ሰዓት ያህል ዐሰበ፤ ልቡም ታወከ። ንጉሡም መልሶ፥ “ብልጣሶር ሆይ! ሕልሙና ፍቺው አያስቸግርህ” አለው። ብልጣሶርም መልሶ አለ፥ “ጌታዬ ሆይ! ሕልሙ ለሚጠሉህ፥ ፍቺውም ለጠላቶችህ ይሁን።'),
  ('cf780607-c341-502e-af0d-4ef76042c60c', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '869518bc-715b-5607-a17c-9335ca153cb0', 2, 20, 'ትልቅ የነበረው፥ የበረታውም፥ ቁመቱም እስከ ሰማይ የደረሰው፥ ቅርንጫፉም እስከ ምድር ሁሉ ድረስ የታየው፥'),
  ('e16c43ec-42d0-5226-aee3-418ea67560b9', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '869518bc-715b-5607-a17c-9335ca153cb0', 3, 21, 'ቅጠሉም አምሮ የነበረው፤ ፍሬውም የበዛው፥ ለሁሉም መብል የነበረበት፥ በበታቹም የምድር አራዊት የተቀመጡ፥ በቅርንጫፎቹም የሰማይ ወፎች ያደሩበት፥ ያየኸው ዛፍ፥'),
  ('74dccb1b-165a-5a19-a847-b82294a449b0', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '869518bc-715b-5607-a17c-9335ca153cb0', 4, 22, 'ንጉሥ ሆይ! እርሱ ታላቅና ብርቱ የሆንህ አንተ ነህ፤ ታላቅነትህ በዝቶአል፤ እስከ ሰማይም ደርሶአል፤ ግዛትህም እስከ ምድር ዳርቻ ድረስ ነው።'),
  ('8271d076-d7f3-50d3-a800-f4a4ec7e6247', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '869518bc-715b-5607-a17c-9335ca153cb0', 5, 23, 'ንጉሡም ከሰማይ የወረደውንና፦ ዛፉን ቍረጡ፥ አጥፉትም፤ ነገር ግን ጉቶውን በምድር ውስጥ ተዉት፤ በብረትና በናስ ማሰሪያ ታስሮ በመስክ ውስጥ ይቈይ፤ በሰማይም ጠል ይረስርስ፥ ሰባት ዘመናትም እስኪያልፉበት ድረስ እድል ፋንታው ከምድር አራዊት ጋር ይሁን ያለውን ቅዱስ ጠባቂ ማየቱ፥'),
  ('30ec9c38-ebf3-5ff8-a34a-07ea8cc35e54', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '869518bc-715b-5607-a17c-9335ca153cb0', 6, 24, 'ንጉሥ ሆይ! ፍቺው ይህ ነው፤ በጌታዬ በንጉሥ ላይ የወረደው የልዑሉ ትእዛዝ ነው፤'),
  ('980bc0a7-988e-59bc-a766-09f5f613ba6d', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '869518bc-715b-5607-a17c-9335ca153cb0', 7, 25, 'ልዑሉም የሰዎችን መንግሥት እንዲገዛ፥ ለሚወድደውም እንዲሰጠው እስክታውቅ ድረስ ከሰዎች ተለይተህ ትሰደዳለህ፤ መኖሪያህም ከምድር አራዊት ጋር ይሆናል፤ እንደ በሬም ሣር ትበላለህ፤ በሰማይም ጠል ትረሰርሳለህ፤ ሰባት ዘመናትም ያልፉብሃል።'),
  ('6f487cb7-6bc4-501b-a77d-78dd5de4edac', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '869518bc-715b-5607-a17c-9335ca153cb0', 8, 26, 'የዛፉንም ጉቶ ተዉት ማለቱ፥ ሥልጣን ከሰማያት እንደ ሆነ እስክታውቅ ድረስ መንግሥትህ ይቈይልሃል።'),
  ('06a16d35-a3cf-57d3-a380-ff81e3fc6597', '20f764fc-4b00-54c3-aa1a-fefedf78316e', '869518bc-715b-5607-a17c-9335ca153cb0', 9, 27, 'ንጉሥ ሆይ! ስለዚህ ምናልባት የደኅንነትህ ዘመን ይረዝም እንደ ሆነ ምክሬ ደስ ያሰኝህ፤ በጽድቅና በምጽዋት ትድናለህ፤ በደልህንና ኀጢአትህንም ለድሆች በመራራት እግዚአብሔር ይቅር ይልሃል።”'),
  ('ba42d6fa-a8ba-5d0f-a3db-1f2a700444e1', '20f764fc-4b00-54c3-aa1a-fefedf78316e', 'bb1e62ae-01d2-5c28-a116-9b2a4c4bc96d', 1, 28, 'ይህ ሁሉ በንጉሡ በናቡከደነፆር ላይ ደረሰ።'),
  ('a2b6c34c-1aa5-5063-a275-9cac8f237064', '20f764fc-4b00-54c3-aa1a-fefedf78316e', 'bb1e62ae-01d2-5c28-a116-9b2a4c4bc96d', 2, 29, 'ከዐሥራ ሁለት ወር በኋላም በባቢሎን ቤተ መንግሥት ሰገነት ላይ ሲመላለስ፤'),
  ('ab45da1e-0630-5251-ac77-0f3c544c2b41', '20f764fc-4b00-54c3-aa1a-fefedf78316e', 'bb1e62ae-01d2-5c28-a116-9b2a4c4bc96d', 3, 30, 'ንጉሡ፥ “ይህች እኔ በጕልበቴ ብርታት ለግርማዬ ክብር የመንግሥት መኖሪያ እንድትሆን ያሠራኋት ታላቂቱ ባቢሎን አይደለችምን?” ብሎ ተናገረ።'),
  ('8ce7a731-b14d-5ac7-af10-0782d3c36324', '20f764fc-4b00-54c3-aa1a-fefedf78316e', 'bb1e62ae-01d2-5c28-a116-9b2a4c4bc96d', 4, 31, 'ቃሉም ገና በንጉሡ አፍ ሳለ ድምፅ ከሰማይ መጣና፥ “ንጉሥ ናቡከደነፆር ሆይ! መንግሥት ከአንተ ዘንድ ዐለፈች ተብሎ ለአንተ ተነግሮአል፤'),
  ('fd237775-d87f-59c2-ab9b-96b85f5fffff', '20f764fc-4b00-54c3-aa1a-fefedf78316e', 'bb1e62ae-01d2-5c28-a116-9b2a4c4bc96d', 5, 32, 'ልዑሉም የሰዎችን መንግሥት እንዲገዛ፥ ለሚወድደውም እንዲሰጠው እስክታውቅ ድረስ ከሰዎች ተለይተህ ትሰደዳለህ፤ መኖሪያህም ከምድር አራዊት ጋር ይሆናል፤ እንደ በሬም ሣር ትበላለህ፤ ሰባት ዘመናትም ያልፉብሃል” አለው።'),
  ('b9445b72-48a3-5629-a7f1-068878a7112f', '20f764fc-4b00-54c3-aa1a-fefedf78316e', 'bb1e62ae-01d2-5c28-a116-9b2a4c4bc96d', 6, 33, 'በዚያም ሰዓት ነገሩ በናቡከደነፆር ላይ ደረሰ፤ ጠጕሩም እንደ አንበሳ፥ ጥፍሩም እንደ ንስር እስኪረዝም ድረስ ከሰዎች ተለይቶ ተሰደደ፤ እንደ በሬም ሣር በላ፤ አካሉም በሰማይ ጠል ረሰረሰ።'),
  ('03e3a8d7-d4ab-597e-a138-c9c1aa75e7a1', '20f764fc-4b00-54c3-aa1a-fefedf78316e', 'bb1e62ae-01d2-5c28-a116-9b2a4c4bc96d', 7, 34, 'ከእነዚያም ዘመናት በኋላ እኔ ናቡከደነፆር ዐይኔን ወደ ሰማይ አነሣሁ፤ አእምሮዬም ተመለሰልኝ፤ ልዑሉንም ባረክሁ፤ ለዘለዓለም የሚኖረውንም አመሰገንሁ፤ አከበርሁትም፤ ግዛቱ የዘለዓለም ግዛት ነውና፥ መንግሥቱም ለልጅ ልጅ ነውና።'),
  ('6825973d-ffce-5ea1-a06b-d38eac2c5941', '20f764fc-4b00-54c3-aa1a-fefedf78316e', 'bb1e62ae-01d2-5c28-a116-9b2a4c4bc96d', 8, 35, 'በምድርም የሚኖሩ ሁሉ እንደ ኢምንት ይቈጠራሉ፤ በሰማይም ሠራዊት በምድርም ላይ በሚኖሩ መካከል እንደ ፈቃዱ ያደርጋል፤ እጁንም የሚቃወማት ወይም፥ “ምን ታደርጋለህ?” የሚለው የለም።'),
  ('de874685-0f0c-5651-aea3-e3ea0b180930', '20f764fc-4b00-54c3-aa1a-fefedf78316e', 'bb1e62ae-01d2-5c28-a116-9b2a4c4bc96d', 9, 36, 'በዚያን ጊዜም አእምሮዬ ተመለሰልኝ፤ ወደ መንግሥቴም ክብር መጣሁ፤ ግርማዬና ውበቴም ወደ እኔ ተመለሰ፤ አማካሪዎችና መኳንንቶችም ፈለጉኝ፤ በመንግሥቴም ውስጥ ጸናሁ፤ ብዙም ክብር ተጨመረልኝ።'),
  ('b66ba0da-03bb-50d7-a00c-7abfcdf98d67', '20f764fc-4b00-54c3-aa1a-fefedf78316e', 'bb1e62ae-01d2-5c28-a116-9b2a4c4bc96d', 10, 37, 'አሁንም እኔ ናቡከደነፆር የሰማይን ንጉሥ አመሰግነዋለሁ፤ ከፍ ከፍም አደርገዋለሁ፥ አከብረውማለሁ። ሥራው ሁሉ እውነት፥ መንገዱም ቀና ነውና፤ በትዕቢትም የሚሄዱትን ያዋርድ ዘንድ ይችላልና።'),
  ('2597f158-7335-5103-a617-d853b1ac02ae', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 1, 1, 'ንጉሡ ብልጣሶር ለሺህ መኳንንቱ ትልቅ ግብዣ አደረገ፤ ለሺሁም የወይን ጠጅ ያጠጣ ነበር።'),
  ('decb9c6e-3f85-5b5a-a350-d5f64a8d2643', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 2, 2, 'ብልጣሶርም የወይን ጠጅ በጠጣ ጊዜ ንጉሡና መኳንንቱ፥ ሚስቶቹና ቁባቶቹ ይጠጡባቸው ዘንድ፥ “አባቴ ናቡከደነፆር በኢየሩሳሌም ከነበረው ቤተ መቅደስ ያመጣቸውን የወርቁንና የብሩን ዕቃዎች አምጡ” ብሎ አዘዘ።'),
  ('8c058f70-0f1f-5a1c-aad8-0dd82fa7acb3', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 3, 3, 'ያን ጊዜም በኢየሩሳሌም ከነበረው ከእግዚአብሔር ቤተ መቅደስ የመጡትን የወርቁንና የብሩን ዕቃዎች አመጡ፤ ንጉሡና መኳንንቱም፥ ሚስቶቹና ቁባቶቹም ጠጡባቸው።'),
  ('4d9e818d-1831-5d66-a924-1f55ff8f749f', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 4, 4, 'የወይን ጠጅም እየጠጡ ከወርቅና ከብር፥ ከናስና ከብረት፥ ከእንጨትና ከድንጋይ የተሠሩትን አማልክት አመሰገኑ።'),
  ('a154bc71-cf38-5d11-a0be-aded930f3c84', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 5, 5, 'በዚያም ሰዓት የሰው እጅ ጣት ወጥታ በንጉሡ ቤት በተለሰነው ግንብ ላይ በመቅረዙ አንጻር ጻፈች፤ ንጉሡም የሰው ጣት ስትጽፍ አየ።'),
  ('b6be431c-b25f-51df-aa2a-1282615e75ef', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 6, 6, 'ያን ጊዜም የንጉሡ ፊት ተለወጠ፤ ልቡም ታወከ፤ የወገቡም ጅማቶች ተፈቱ፤ ጕልበቶቹም ተብረከረኩ።'),
  ('0714494e-9767-5799-aa9e-3a4cdf61f080', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 7, 7, 'ንጉሡም አስማተኞቹንና ከለዳውያኑን፥ ቃላተኞቹንም ያገቡ ዘንድ በታላቅ ድምፅ ጮኸ፤ ንጉሡም የባቢሎንን ጠቢባን፥ “ይህን ጽሕፈት ያነበበ፥ ፍቺውንም የነገረኝ ሐምራዊ ግምጃ ይለብሳል፤ የወርቅም ማርዳ በአንገቱ አስርለታለሁ፤ በመንግሥቴም ላይ ሦስተኛ ገዥ አድርጌ እሾመዋለሁ” ብሎ ተናገረ።'),
  ('ffbf6282-f164-5eec-a897-a184d4f044b4', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 8, 8, 'የዚያን ጊዜም የንጉሡ ጠቢባን ሁሉ ገቡ፤ ነገር ግን ጽሕፈቱን ያነብቡ ዘንድ፥ ፍቺውንም ለንጉሡ ይነግሩ ዘንድ አልቻሉም።'),
  ('fd516bd2-3e53-523d-a221-fbd6f563e1da', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 9, 9, 'ንጉሡም ብልጣሶር እጅግ ደነገጠ፤ ፊቱም ተለወጠበት፤ መኳንንቱም ተደናገጡ።'),
  ('9fb5d3eb-6e3c-58a6-aa18-cb78c03f79ee', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 10, 10, 'ንግሥቲቱም የንጉሡንና የመኳንንቱን ቃል ሰምታ ወደ ግብዣ ቤት ገባች፤ እንዲህም አለች፥ “ንጉሥ ሆይ! ለዘለዓለም ኑር፤ አሳብህ አያስቸግርህ፤ ፊትህም አይለወጥ።'),
  ('01c6e2b1-0fa8-5c3d-aa7f-6dd5844f1c61', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 11, 11, 'የእግዚአብሔር ቅዱስ መንፈስ ያለበት ሰው በመንግሥትህ ውስጥ አለ፤ በአባትህም ዘመን እንደ አማልክት ጥበብ ያለ ጥበብና ማስተዋል፥ ዕውቀትም ተገኘበት፤ አባትህ ንጉሡ ናቡከደነፆር የሕልም ተርጓሚዎችና የአስማተኞች፥ የከለዳውያንና የቃላተኞች አለቃ አድርጎ ሾመው።'),
  ('89daddd8-813b-5e23-abb4-66d3c62d10e2', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 12, 12, 'መልካም መንፈስ፥ ዕውቀትም፥ ማስተዋልም፥ ሕልምንም መተርጐም፥ እንቆቅልሽንም መግለጥ፥ የታተመውንም መፍታት በእርሱ ተገኝቶአልና፤ እርሱም ንጉሡ ስሙን ብልጣሶር ብሎ የሰየመው ዳንኤል ነው። አሁንም እርሱ ይጠራ፤ እርሱም ፍቺውን ይነግርሃል።”'),
  ('5af2cff8-4d69-58d9-a260-4bf6b8f4bfe2', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 13, 13, 'የዚያን ጊዜም ዳንኤል ወደ ንጉሡ ፊት ገባ፤ ንጉሡም ተናገረው፤ ዳንኤልንም እንዲህ አለው፥ “ንጉሡ አባቴ ከይሁዳ ከማረካቸው ከይሁዳ ምርኮኞች ልጆች የሆንህ ዳንኤል አንተ ነህን?'),
  ('eb7ae25c-1033-545c-aa59-6453f76415b1', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 14, 14, 'የእግዚአብሔር ቅዱስ መንፈስ እንደ አለብህ፥ ዕውቀትና ማስተዋልም፥ ሕልምንም መተርጐም እንደ ተገኘብህ ስለ አንተ ሰምቻለሁ።'),
  ('0100d120-00e5-5fd4-a53d-493864a17260', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 15, 15, 'አሁንም ይህን ጽሕፈት ያነብቡ ዘንድ፥ ፍቺውንም ይነግሩኝ ዘንድ ጠንቋዮችና ፈላስፎች፥ ጠቢባንና ሟርተኞችም ወደ እኔ ገብተው ነበር፤ ነገር ግን የነገሩን ፍቺ ይነግሩኝ ዘንድ አልቻሉም።'),
  ('470d3739-c539-5180-a525-bb43cb47217f', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 16, 16, 'አንተ ግን ፍቺን ትሰጥ ዘንድ፥ የታተመውንም ትፈታ ዘንድ እንድትችል ሰምቻለሁ፤ አሁንም ጽሕፈቱን ታነብብ ዘንድ፥ ፍቺውንም ትነግረኝ ዘንድ ብትችል፥ ሐምራዊ ግምጃ ትለብሳለህ፤ የወርቅም ማርዳ በአንገትህ ዙሪያ አስርልሃለሁ፤ አንተም በመንግሥቴ ላይ ሦስተኛ ገዥ ትሆናለህ።”'),
  ('ca4f1eb7-6c8e-5f87-ab4b-c465af93b734', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 17, 17, 'የዚያን ጊዜም ዳንኤል መለሰ፤ በንጉሡም ፊት እንዲህ አለ፥ “ስጦታህ ለአንተ ይሁን፤ የመንግሥትህንም ሢሶ ለሌላ ስጥ፤ ነገር ግን ጽሕፈቱን ለንጉሡ አነብባለሁ፤ ፍቺውንም እነግርሃለሁ።'),
  ('20019cf4-ea6d-5839-a9ec-ae60d8d8e892', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 18, 18, 'ንጉሥ ሆይ! ልዑል አምላክ ለአባትህ ለናቡከደነፆር መንግሥትንና ታላቅነትን፥ ክብርንና ግርማን ሰጠው።'),
  ('9b396b7c-b54d-5254-a7b7-1e618b56d503', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 19, 19, 'ስለ ሰጠው ታላቅነት ወገኖችና አሕዛብ፥ በልዩ ልዩም ቋንቋ የሚናገሩ ሁሉ በፊቱ ይንቀጠቀጡና ይፈሩ ነበር፤ የፈቀደውን ይገድል፥ የፈቀደውንም በሕይወት ያኖር ነበር፤ የፈቀደውንም ያነሣ፥ የፈቀደውንም ያዋርድ ነበር።'),
  ('e4957692-66b1-5f7e-a305-ac979dc5847e', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 20, 20, 'ልቡ ግን በታበየ ጊዜ፥ በኵራትም ያደርግ ዘንድ መንፈሱ በጠነከረ ጊዜ፥ ከመንግሥቱ ዙፋን ተዋረደ፤ ክብሩም ተለየው።'),
  ('a5e2d1ad-7fc7-5f2f-a1ac-1d2789c4b5bb', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 21, 21, 'ልዑል አምላክም የሰዎችን መንግሥት እንዲገዛ፥ ለሚወድደውም እንዲሰጠው እስኪያውቅ ደረስ ከሰው ልጆች ተለይቶ ተሰደደ፥ ልቡም እንደ አውሬ ልብ ሆነ፤ መኖሪያውም ከምድረ በዳ አህዮች ጋር ነበረ፤ እንደ በሬም ሣር በላ፤ አካሉም በሰማይ ጠል ረሰረሰ።'),
  ('1cf71555-2639-538f-a35f-cbdf50b69588', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 22, 22, 'ብልጣሶር ሆይ! አንተ ልጁ ስትሆን በእግዚአብሔር ፊት ልብህን አላዋረድህም፤ ይህንም ሁሉ አላወቅህም።'),
  ('a1ffb70a-2ffc-5082-a72c-eb2c9c461ed7', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 23, 23, 'በሰማይ አምላክ በእግዚአብሔር ላይ ኰራህ፤ የመቅደሱንም ዕቃዎች በፊትህ አመጡ፤ አንተም መኳንንትህም፥ ሚስቶችህም፥ ቁባቶችህም የወይን ጠጅ ጠጣችሁባቸው፤ ከብርና ከወርቅም፥ ከናስና ከብረትም፥ ከእንጨትና ከድንጋይም የተሠሩትን፥ የማያዩትንና የማይሰሙትንም፥ የማያውቁትንም አማልክት አመሰገንህ፤ ትንፋሽህንና መንገድህን ሁሉ በእጁ የያዘውን አምላክ ግን አላመሰገንኸውም።'),
  ('01ad6d4c-a6db-55e6-a4f7-58fd5be9afe3', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 24, 24, 'ስለዚህም ይህ የሰው እጅ ጣት ከእርሱ ዘንድ ተልኳል፤ ይህም ጽሕፈት ተጽፎአል።'),
  ('86ccdb1e-bee0-5805-a185-200872747ac4', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 25, 25, '“የተጻፈውም ጽሕፈት፦ ማኔ፥ ቴቄል፥ ፋሬስ ይላል።'),
  ('ed1fb0ac-5933-5ac9-ae08-3741eefc52fa', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 26, 26, 'የነገሩም ፍቺ ይህ ነው፤ ማኔ ማለት፥ እግዚአብሔር መንግሥትህን ቈጠራት፤ ፈጸማትም ማለት ነው።'),
  ('a132190d-d11d-514e-a375-5c4bf53dea30', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 27, 27, 'ቴቄል ማለት፥ በሚዛን ተመዘነች፤ ቀልላም ተገኘች ማለት ነው።'),
  ('1df6c4cf-e510-5440-a0fb-d5f6fac06e10', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 28, 28, 'ፋሬስ ማለት፥ መንግሥትህ ተከፈለች፤ ለሜዶንና ለፋርስ ሰዎችም ተሰጠች” ማለት ነው።'),
  ('45c2434d-d4c3-5115-a0b2-2e03c11c26c2', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 29, 29, 'የዚያን ጊዜም ብልጣሶር ለዳንኤል ሐምራዊ ግምጃ እንዲያለብሱት፥ የወርቅ ማርዳም በአንገቱ ዙሪያ እንዲያደርጉለት አዘዘ፤ በመንግሥትም ላይ ሦስተኛ ገዥ እንዲሆን ዐዋጅ አስነገረ።'),
  ('284a84c6-b127-5edd-af7a-8222f7064a54', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 30, 30, 'በዚያም ሌሊት የከለዳውያን ንጉሥ ብልጣሶር ተገደለ።'),
  ('1ce38a6f-7203-5ff6-a759-0e5671815844', '0880509f-40ff-5717-a9ca-31f2ebcd790f', '556e80e0-cebe-50d3-a374-ebc0a720a7d3', 31, 31, 'ሜዶናዊውም ዳርዮስ በእርሱ ፋንታ ነገሠ። ዕድሜውም ስድሳ ሁለት ዓመት ነበረ።'),
  ('7d9d7ee7-8d9b-5cb4-a30a-9d0595b9624a', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'c72f1bf3-27fb-5cb7-a17b-fd825779559e', 1, 1, 'ዳርዮስም በመንግሥቱ ሁሉ ዘንድ እንዲሆኑ መቶ ሃያ መሳፍንትን በመንግሥቱ ላይ ይሾም ዘንድ ወደደ።'),
  ('5f52c65f-314b-57f3-ae04-21e0a4144853', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'c72f1bf3-27fb-5cb7-a17b-fd825779559e', 2, 2, 'መሳፍንቱም ግብሩን ያመጡላቸው ዘንድ፥ ንጉሡም በማንኛውም እንዳይቸገር ሦስት አለቆች በላያቸው አደረገ፤ ከእነርሱም አንደኛው ዳንኤል ነበረ።'),
  ('71560ad9-2d97-5de1-afc6-989ff3eb6b90', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'c72f1bf3-27fb-5cb7-a17b-fd825779559e', 3, 3, 'ዳንኤልም መልካም መንፈስ ስለ አለው ከአለቆችና ከመሳፍንት በለጠ፤ ንጉሡም በመንግሥቱ ሁሉ ላይ ሾመው።'),
  ('0211b181-042f-5a68-ab36-5416bb937e97', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'c72f1bf3-27fb-5cb7-a17b-fd825779559e', 4, 4, 'ያን ጊዜም አለቆችና መሳፍንቱ ስለ መንግሥቱ በዳንኤል ላይ ምክንያት ይፈልጉ ነበር፤ ነገር ግን የታመነ ነበረና፥ ምንም በደል አልተገኘበትምና በእርሱ ላይ ሰበብና በደል ያገኙበት ዘንድ አልቻሉም።'),
  ('fcb2a3d6-c91d-54f0-a7f0-9af20c6ca698', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'c72f1bf3-27fb-5cb7-a17b-fd825779559e', 5, 5, 'እነዚያም ሰዎች፥ “ከአምላኩ ሕግ በቀር በዚህ በዳንኤል ላይ ሌላ ምክንያት አናገኝበትም” አሉ።'),
  ('6d63a671-ac5a-5581-ad55-e291549493a6', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'c72f1bf3-27fb-5cb7-a17b-fd825779559e', 6, 6, 'ያን ጊዜም ሹሞቹና መኳንንቱ ወደ ንጉሡ ተሰብስበው እንዲህ አሉት፥ “ንጉሥ ዳርዮስ ሆይ! ለዘለዓለም ኑር።'),
  ('82230808-003e-51d3-ac34-448919682557', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'c72f1bf3-27fb-5cb7-a17b-fd825779559e', 7, 7, 'የመንግሥቱ አለቆች ሁሉ ሹሞችና መሳፍንት፥ አማካሪዎችና አዛዦች፦ ንጉሥ ሆይ! ከአንተ በቀር ማንም እስከ ሠላሳ ቀን ድረስ ልመና ከአምላክ ወይም ከሰው ቢለምን፥ በአንበሶች ጕድጓድ ውስጥ ይጣል የሚል የንጉሥ ሕግና ብርቱ ትእዛዝ ይወጣ ዘንድ ተማከሩ።'),
  ('9356175c-b4a0-564e-ae48-710b0382ee2b', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'c72f1bf3-27fb-5cb7-a17b-fd825779559e', 8, 8, 'አሁንም ንጉሥ ሆይ! እንደማይለወጠው እንደ ሜዶንና እንደ ፋርስ ሕግ እንዳይለወጥ ትእዛዙን አጽና፤ ጽሕፈቱንም ጻፍ።”'),
  ('477d7c3e-e2e0-5a0a-a229-7723eee731bf', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'c72f1bf3-27fb-5cb7-a17b-fd825779559e', 9, 9, 'ያን ጊዜም ንጉሡ ዳርዮስ ይህን ሥርዐት ይጽፉ ዘንድ አዘዘ።'),
  ('52b0b765-7689-5516-acf9-2425a9b215b5', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', '962d485d-b565-58d5-ad50-5ac4396f584a', 1, 10, 'ዳንኤልም ይህ ሥርዐት እንደ ታዘዘ በዐወቀ ጊዜ ወደ ቤቱ ገባ፤ የእልፍኙም መስኮቶች ወደ ኢየሩሳሌም አንጻር ተከፍተው ነበር፤ ቀድሞም ያደርግ እንደ ነበረ ከቀኑ በሦስት ሰዓት በጕልበቱ ተንበርክኮ በአምላኩ ፊት ጸለየ አመሰገነም።'),
  ('73614a04-cfa3-57d3-ad10-5823baee020e', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', '962d485d-b565-58d5-ad50-5ac4396f584a', 2, 11, 'እነዚያም ሰዎች በማንኛውም ነገር ዘወትር ይመለከቱት ነበርና ዳንኤል በአምላኩ ፊት ሲጸልይና ሲለምን አገኙት።'),
  ('993a6c59-697c-5c26-abbe-ba8969bd31bb', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', '962d485d-b565-58d5-ad50-5ac4396f584a', 3, 12, 'ወደ ንጉሡም ቀርበው ስለ ንጉሡ ትእዛዝ፥ “ንጉሥ ሆይ! ከአንተ በቀር እስከ ሠላሳ ቀን ድረስ ከአምላክ ወይም ከሰው የሚለምን ሰው ሁሉ በአንበሶች ጕድጓድ ውስጥ እንዲጣል ትእዛዝ አልጻፍህምን?” አሉት። ንጉሡም መልሶ፥ “ነገሩ እንደማይለወጠው እንደ ሜዶንና እንደ ፋርስ ሕግ እውነት ነው” አላቸው።'),
  ('b30c29c5-9260-576c-a9f4-d4a50971ac28', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', '962d485d-b565-58d5-ad50-5ac4396f584a', 4, 13, 'የዚያን ጊዜም በንጉሡ ፊት መልሰው፥ “ንጉሥ ሆይ! ከይሁዳ የምርኮ ልጆች የሆነው ዳንኤል ከቀኑ በሦስት ሰዓት ልመናውን ይለምናል እንጂ አንተንና የጻፍኸውን ትእዛዝ አይቀበልም” አሉት።'),
  ('399614a8-1935-581e-a56a-dd1b485b50bd', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', '962d485d-b565-58d5-ad50-5ac4396f584a', 5, 14, 'ንጉሡም ይህን ቃል በሰማ ጊዜ በጣም አዘነ፤ ያድነውም ዘንድ ልቡን ወደ ዳንኤል አደረገ፤ ሊያድነውም ፀሐይ እስኪገባ ድረስ ደከመ።'),
  ('50ce5901-1981-5320-a48b-b57f8a9945c7', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', '962d485d-b565-58d5-ad50-5ac4396f584a', 6, 15, 'ያን ጊዜም እነዚያ ሰዎች ወደ ንጉሡ ተሰብስበው ንጉሡን፥ “ንጉሥ ሆይ! ንጉሡ ያጸናው ትእዛዝ ወይም ሥርዐት ይለወጥ ዘንድ እንዳይገባ የሜዶንና የፋርስ ሕግ እንደ ሆነ ዕወቅ” አሉት።'),
  ('35b9b948-e252-5432-a3e3-a106cca5f5fe', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', '962d485d-b565-58d5-ad50-5ac4396f584a', 7, 16, 'ያን ጊዜም ዳንኤልን አምጥተው በአንበሶች ጕድጓድ ይጥሉት ዘንድ ንጉሡ አዘዘ፤ ንጉሡም ዳንኤልን፥ “ሁልጊዜ የምታመልከው አምላክህ እርሱ ያድንህ” አለው።'),
  ('29a497bc-02d0-5d1d-a90f-210f1300cd4d', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', '962d485d-b565-58d5-ad50-5ac4396f584a', 8, 17, 'ድንጋይም አምጥተው በጕድጓዱ አፍ ላይ ገጠሙበት፤ ንጉሡም በዳንኤል ላይ የሚተነኳኰል ሰው እንዳይኖር በቀለበቱና በመኳንንቱ ቀለበት አተመው።'),
  ('dad8897f-1ddd-5b46-a076-f42f880de801', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', '962d485d-b565-58d5-ad50-5ac4396f584a', 9, 18, 'ንጉሡም ወደ ቤቱ ሄደ፤ ሳይበላም ተኛ፤ የሚበላውም አላመጡለትም፤ እንቅልፉም ከእርሱ ራቀ። እግዚአብሔርም የአንበሶቹን አፍ ዘጋ፤ ዳንኤልንም አልቧጨሩትም።'),
  ('92722f78-e584-545e-a3f3-51d5ee07ba2f', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'f70a6c48-905f-5461-ad37-56421be89587', 1, 19, 'በነጋውም ንጉሡ ማልዶ ተነሣ፤ ፈጥኖም ወደ አንበሶች ጕድጓድ ሄደ።'),
  ('c7f99076-6e08-552e-af0a-5b3649300d22', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'f70a6c48-905f-5461-ad37-56421be89587', 2, 20, 'ወደ ጕድጓዱም በቀረበ ጊዜ በታላቅ ቃል ጮኸ፤ ንጉሡም ዳንኤልን፥ “የሕያው አምላክ ባሪያ ዳንኤል ሆይ! ሁልጊዜ የምታመልከው አምላክህ ከአንበሶች አፍ ያድንህ ዘንድ ችሎአልን?” አለው።'),
  ('0e84b934-47e2-55c3-a9c0-70ae158a0874', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'f70a6c48-905f-5461-ad37-56421be89587', 3, 21, 'ዳንኤልም ንጉሡን፥ “ንጉሥ ሆይ! ለዘለዓለም ኑር።'),
  ('cf4b5c99-ddfa-516c-a3b2-2d3dedd7b508', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'f70a6c48-905f-5461-ad37-56421be89587', 4, 22, 'በፊቱ ቅንነት ተገኝቶብኛልና፥ በአንተም ፊት ደግሞ፤ ንጉሥ ሆይ! አልበደልሁምና አምላኬ መልአኩን ልኮ የአንበሶችን አፍ ዘጋ፤ እነርሱም አልቧጨሩኝም” አለው።'),
  ('c902d06f-5501-5849-a528-519583971676', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'f70a6c48-905f-5461-ad37-56421be89587', 5, 23, 'ያን ጊዜም ንጉሡ እጅግ ደስ አለው፤ ዳንኤልንም ከጕድጓዱ ያወጡት ዘንድ አዘዘ፤ ዳንኤልም ከጕድጓዱ ወጣ፤ በአምላኩም ታምኖ ነበርና አንዳች ጕዳት አልተገኘበትም።'),
  ('5fc1c42e-93bf-54a5-af62-a9bf8432b478', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'f70a6c48-905f-5461-ad37-56421be89587', 6, 24, 'ንጉሡም ዳንኤልን የከሰሱ እነዚያን ሰዎች ያመጡአቸው ዘንድ አዘዘ፤ እነርሱንና ልጆቻቸውንም፥ ሚስቶቻቸውንም በአንበሶች ጕድጓድ ጣሉአቸው፤ ወደ ጕድጓዱም መጨረሻ ሳይደርሱ አንበሶች ያዙአቸው፤ አጥንታቸውንም ሁሉ ሰባበሩ።'),
  ('c44b52c6-e8a6-545a-ab70-9ff0a9f0a6b2', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'f70a6c48-905f-5461-ad37-56421be89587', 7, 25, 'ያን ጊዜም ንጉሥ ዳርዮስ በምድር ሁሉ ላይ ወደሚኖሩ ወገኖችና አሕዛብ፥ በልዩ ልዩም ቋንቋ ወደሚናገሩ ሁሉ ጻፈ፤ እንዲህም አለ፥ “ሰላም ይብዛላችሁ።'),
  ('52ef91b2-a214-5ce4-aa53-16273465f38c', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'f70a6c48-905f-5461-ad37-56421be89587', 8, 26, 'በመንግሥቴ ግዛት ሁሉ ያሉ ሰዎች በዳንኤል አምላክ ፊት እንዲፈሩና እንዲንቀጠቀጡ አዝዣለሁ፤ እርሱ ሕያው አምላክ ለዘለዓለም የሚኖር ነውና፤ መንግሥቱም የማይጠፋ ነው፥ ግዛቱም ለዘለዓለም ይኖራል።'),
  ('1800380c-3fb8-5ea3-a7bf-1c083b2e5d30', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'f70a6c48-905f-5461-ad37-56421be89587', 9, 27, 'ያድናል፤ ይታደግማል፤ በሰማይና በምድርም ተአምራትንና ድንቅን ይሠራል፤ ዳንኤልንም ከአንበሶች አፍ አድኖታል።”'),
  ('53885221-6ebb-52ce-a1f7-b6380865353c', '7054f1c0-fe5e-5db5-af5d-4f9f5f80efab', 'f70a6c48-905f-5461-ad37-56421be89587', 10, 28, 'ይህም ዳንኤል በዳርዮስ መንግሥትና በፋርሳዊው በቂሮስ መንግሥት ከፍ ከፍ አለ።'),
  ('8c6ba751-2eed-5f98-ae1b-0953683f5019', '421f1369-69bd-5cb7-ae23-85d43c738612', 'b057aa64-33e9-56b5-a924-421c1214c5f2', 1, 1, 'በባቢሎን ንጉሥ በብልጣሶር በመጀመሪያው ዓመተ መንግሥት ዳንኤል በአልጋው ላይ ሕልምንና የራሱን ራእይ አየ፤ ከዚያም በኋላ ሕልሙን ጻፈ፥'),
  ('9e96f63a-5cdc-59b3-a8c9-0731763f69c6', '421f1369-69bd-5cb7-ae23-85d43c738612', 'b057aa64-33e9-56b5-a924-421c1214c5f2', 2, 2, 'እንዲህም አለ፥ “እኔ ዳንኤል ራእይ አየሁ፤ እነሆም አራቱ የሰማይ ነፋሳት በታላቁ ባሕር ላይ ይነፍሱ ነበር።'),
  ('ec78cd6a-4fd9-50eb-a7a6-9a6f1eea02ab', '421f1369-69bd-5cb7-ae23-85d43c738612', 'b057aa64-33e9-56b5-a924-421c1214c5f2', 3, 3, 'አራትም ታላላቅ አራዊት ከባሕር ወጡ፥ እያንዳንዲቱም ከሌላይቱ ልዩ ነበረች።'),
  ('96a92978-9f77-545c-a380-ad71aa26b351', '421f1369-69bd-5cb7-ae23-85d43c738612', 'b057aa64-33e9-56b5-a924-421c1214c5f2', 4, 4, 'መጀመሪያይቱ እንደ ሴት አንበሳ ነበረች፤ እንደ ንስርም ክንፍ ነበራት፤ ክንፎችዋም ከእርስዋ እስኪነቀሉ ድረስ አይ ነበር፤ ከምድርም ከፍ ከፍ አለች፤ እንደ ሰውም በእግር ቆመች፤ የሰውም ልብ ተሰጣት።'),
  ('aff24c63-621e-5c2e-aec9-463c7d267a2b', '421f1369-69bd-5cb7-ae23-85d43c738612', 'b057aa64-33e9-56b5-a924-421c1214c5f2', 5, 5, 'እነሆም ሁለተኛይቱ ድብ የምትመስል ሌላ አውሬ ነበረች፤ በአንድ ወገንም ቆመች፤ ሦስትም የጎድን አጥንቶች በአፍዋ ውስጥ በጥርሶችዋ መካከል ነበሩ፤ እንደዚህም፦ ተነሥተሽ እጅግ ሥጋ ብዪ አሏት።'),
  ('6df80788-33e4-5a5b-a80b-7e13e11d06a2', '421f1369-69bd-5cb7-ae23-85d43c738612', 'b057aa64-33e9-56b5-a924-421c1214c5f2', 6, 6, 'ከዚህም በኋላ፥ እነሆ ነብር የምትመስል፥ በጀርባዋም ላይ አራት የወፍ ክንፎች የነበሩአት፤ ሌላ አውሬ አየሁ፤ ለአውሬይቱም አራት ራሶች ነበሩአት፤ ሥልጣንም ተሰጣት።'),
  ('8ee45e11-280b-51bf-a328-454965b522d9', '421f1369-69bd-5cb7-ae23-85d43c738612', 'b057aa64-33e9-56b5-a924-421c1214c5f2', 7, 7, 'ከዚህም በኋላ በሌሊት ራእይ አየሁ፤ እነሆም የምታስፈራና የምታስደነግጥ፥ እጅግም የበረታች፥ ታላላቅም የብረት ጥርሶች የነበሩአት አራተኛ አውሬ ነበረች፤ ትበላና ታደቅቅ ነበር፥ የቀረውንም በእግርዋ ትረግጥ ነበር፤ ከእርስዋም በፊት ከነበሩት አራዊት ሁሉ የተለየች ነበረች፤ ዐሥር ቀንዶችም ነበሩአት።'),
  ('ac81bcb4-db1a-5507-abfb-2e56355ba625', '421f1369-69bd-5cb7-ae23-85d43c738612', 'b057aa64-33e9-56b5-a924-421c1214c5f2', 8, 8, 'ቀንዶችንም ተመለከትሁ፤ እነሆም፤ በመካከላቸው ሌላ ትንሽ ቀንድ ወጣ፤ በፊቱም ከቀደሙት ቀንዶች ሦስት ተነቃቀሉ፤ እነሆም በዚያ በትንሹ ቀንድ እንደ ሰው ዐይኖች የነበሩ ዐይኖች፥ በትዕቢትም የሚናገር አፍ ነበሩበት።'),
  ('f5237780-392c-5c6c-a9be-160a78569619', '421f1369-69bd-5cb7-ae23-85d43c738612', 'b057aa64-33e9-56b5-a924-421c1214c5f2', 9, 9, '“ዙፋኖችም እስኪዘረጉ ድረስ አየሁ፤ በዘመናት የሸመገለውም ተቀመጠ፤ ልብሱም እንደ በረዶ ነጭ፥ የራሱም ጠጕር እንደ ነጭ ሱፍ ነበረ፤ ዙፋኑም የእሳት ነበልባል ነበረ፥ መንኰራኵሮቹም የሚነድድ እሳት ነበሩ።'),
  ('f42c984b-3d82-5fde-a4b1-7b2f72ae494d', '421f1369-69bd-5cb7-ae23-85d43c738612', 'b057aa64-33e9-56b5-a924-421c1214c5f2', 10, 10, 'የእሳትም ፈሳሽ ከፊቱ ይፈልቅና ይወጣ ነበር፤ ሺህ ጊዜ ሺህ የሆኑ ያገለግሉት ነበር፤ እልፍ አእላፋትም በፊቱ ቆመው ነበር፤ ለፍርድም ተቀመጠ፤ መጻሕፍትንም ገለጠ።'),
  ('3790765c-25e9-5f90-a0b0-8a71213c2cbf', '421f1369-69bd-5cb7-ae23-85d43c738612', 'b057aa64-33e9-56b5-a924-421c1214c5f2', 11, 11, 'የዚያን ጊዜም ይህ ቀንድ ከተናገረው ነገር የተነሣ አውሬው እስኪርቅና እስኪጠፋ ድረስ አየሁ፤ በእሳትም ያቃጥሉት ዘንድ ሰውነቱን አሳልፈው ሰጡት፤'),
  ('9fdcc4eb-795d-5a24-a832-4d473da2f81d', '421f1369-69bd-5cb7-ae23-85d43c738612', 'b057aa64-33e9-56b5-a924-421c1214c5f2', 12, 12, 'ከቀሩትም አራዊት ግዛታቸው ተወሰደ፤ የሕይወታቸው ዘመን ግን እስከ ተወሰነ ጊዜ ድረስ ረዘመ።'),
  ('c60d0cfe-c141-5a30-ad95-6d4857ae3fc8', '421f1369-69bd-5cb7-ae23-85d43c738612', 'b057aa64-33e9-56b5-a924-421c1214c5f2', 13, 13, '“በሌሊትም ራእይ አየሁ፤ እነሆም የሰው ልጅ የሚመስል በሰማይ ደመና መጣ፤ በዘመናትም ወደ ሸመገለው ደረሰ፤ ወደ ፊቱም አቀረቡት።'),
  ('df2035d6-3147-5dbf-ad5a-c56637cce392', '421f1369-69bd-5cb7-ae23-85d43c738612', 'b057aa64-33e9-56b5-a924-421c1214c5f2', 14, 14, 'ወገኖችና አሕዛብ፥ በልዩ ልዩ ቋንቋም የሚናገሩ ሁሉ ይገዙለት ዘንድ ግዛትና ክብር፥ መንግሥትም ተሰጠው፤ ግዛቱም የማያልፍ የዘለዓለም ግዛት ነው፥ መንግሥቱም የማይጠፋ ነው።'),
  ('3ac62e06-b617-5ad1-acb7-624cbd211ff3', '421f1369-69bd-5cb7-ae23-85d43c738612', 'cbfe5710-0d14-5e88-aaa7-b400bdbabd6a', 1, 15, '“እኔም ዳንኤል መንፈሴ ተንቀጠቀጠብኝ፤ ከራሴም ራእይ የተነሣ ልቤ ደነገጠብኝ።'),
  ('63d5399b-296e-5700-a6b8-1c0c24ee20bf', '421f1369-69bd-5cb7-ae23-85d43c738612', 'cbfe5710-0d14-5e88-aaa7-b400bdbabd6a', 2, 16, 'በዚያም ከቆሙት ወደ አንዱ ቀርቤ ስለዚህ ሁሉ እውነቱን ጠየቅሁት፤ እርሱም ነገረኝ፤ የነገሩንም ፍቺ አስታወቀኝ፥ እኔም ነገሩን ተረዳሁት።'),
  ('69e6616e-5a6b-529f-adff-b975184c3463', '421f1369-69bd-5cb7-ae23-85d43c738612', 'cbfe5710-0d14-5e88-aaa7-b400bdbabd6a', 3, 17, 'እንዲህም አለኝ፦ እነዚህ ያየሃቸው አራቱ ታላላቅ አራዊት ከምድር የሚነሡ አራት ነገሥታት ናቸው፤ ዳግመኛም ይወገዳሉ።'),
  ('a7c68298-7cfc-57ea-a8d6-4a2e1ca503ee', '421f1369-69bd-5cb7-ae23-85d43c738612', 'cbfe5710-0d14-5e88-aaa7-b400bdbabd6a', 4, 18, 'ነገር ግን መንግሥት ለልዑሉ ቅዱሳን ይመለሳል፤ የልዑሉ ቅዱሳንም መንግሥቱን ይወስዳሉ፤ እስከ ዘለዓለም ዓለምም መንግሥቱን ይወርሳሉ።'),
  ('390f308f-3e7e-514a-a3b8-52ec266898fd', '421f1369-69bd-5cb7-ae23-85d43c738612', 'cbfe5710-0d14-5e88-aaa7-b400bdbabd6a', 5, 19, 'ከዚህም በኋላ ከቀሩት ሁሉ ተለይታ እጅግ ስለምታስፈራው፥ ጥርሶችዋም የብረት፥ ጥፍሮችዋም የናስ ስለ ሆኑት፥ ስለምትበላውና ስለምታደቅቀው፥ የቀረውንም በእግርዋ ስለምትረግጠው ስለ አራተኛዪቱ አውሬ፥'),
  ('036e52a5-7d3e-5ccf-a51a-dc62a3d8e1bf', '421f1369-69bd-5cb7-ae23-85d43c738612', 'cbfe5710-0d14-5e88-aaa7-b400bdbabd6a', 6, 20, 'በራስዋም ላይ ስለ ነበሩ ስለ ዐሥር ቀንዶች፥ በኋላም ስለ ወጣው፥ በፊቱም ስለ ወደቁ ሦስቱ ቀንዶች፥ ዐይኖችና ትዕቢት የተናገረ አፍ ስለ ነበሩት ራሱም ከሌሎች ስለ በለጠ ስለ ሌላው ቀንድ እውነቱን ለማወቅ ጠየቅሁት።'),
  ('e37e5fe2-1beb-5682-aa60-fd48b1431098', '421f1369-69bd-5cb7-ae23-85d43c738612', 'cbfe5710-0d14-5e88-aaa7-b400bdbabd6a', 7, 21, 'እነሆም፥ ያ ቀንድ ከቅዱሳን ጋር ሲዋጋ አየሁ፤ አሸነፋቸውም፤'),
  ('0bec7347-d07c-585f-ac45-59772403f73a', '421f1369-69bd-5cb7-ae23-85d43c738612', 'cbfe5710-0d14-5e88-aaa7-b400bdbabd6a', 8, 22, 'በዘመናት የሸመገለው እስኪመጣ ድረስ፥ ፍርድም ለልዑሉ ቅዱሳን እስኪሰጥ ድረስ፥ ቅዱሳኑም መንግሥቱን የሚወስዱበት ዘመን እስኪመጣ ድረስ አሸነፋቸው።'),
  ('1f7a388f-656a-584e-a319-ce346e27b6d7', '421f1369-69bd-5cb7-ae23-85d43c738612', 'cbfe5710-0d14-5e88-aaa7-b400bdbabd6a', 9, 23, '“እንዲህም አለኝ፦ አራተኛው አውሬ በምድር ላይ የሚነሣ አራተኛ መንግሥት ነው፤ እርሱም ከመንግሥታት ሁሉ ይበልጣል። ምድሪቱንም ሁሉ ይበላል፤ ይረግጣታል፤ ያደቅቃትማል።'),
  ('d48985c0-8a71-59fc-a90d-2ed2fd335560', '421f1369-69bd-5cb7-ae23-85d43c738612', 'cbfe5710-0d14-5e88-aaa7-b400bdbabd6a', 10, 24, 'ዐሥሩም ቀንዶች ከዚያ መንግሥት የሚነሡ ዐሥር ነገሥታት ናቸው፤ ከእነርሱም በኋላ ሌላ ይነሣል፤ እርሱም ከፊተኞቹ በክፋት የበለጠ ይሆናል፤ ሦስቱንም ነገሥታት ያዋርዳል።'),
  ('ceb3924b-cf0a-56ed-afa1-74b2ad8ee7df', '421f1369-69bd-5cb7-ae23-85d43c738612', 'cbfe5710-0d14-5e88-aaa7-b400bdbabd6a', 11, 25, 'በልዑሉም ላይ ቃልን ይናገራል፤ የልዑልንም ቅዱሳን ይሰባብራል፤ ዘመናትንና ሕግን ይለውጥ ዘንድ ያስባል፤ እስከ ዘመንና እስከ ዘመናት እስከ እኩሌታ ዘመንም በእጁ ይሰጣሉ።'),
  ('a0fd9516-e190-58c6-a9ae-763e0419e00e', '421f1369-69bd-5cb7-ae23-85d43c738612', 'cbfe5710-0d14-5e88-aaa7-b400bdbabd6a', 12, 26, 'ነገር ግን ፍርድ ይሆናል፤ እስከ ፍጻሜውም ድረስ ያፈርሱትና ያጠፉት ዘንድ ግዛቱን ያስወግዱታል።'),
  ('1e546228-e254-55d2-a781-00a41b1ef7d0', '421f1369-69bd-5cb7-ae23-85d43c738612', 'cbfe5710-0d14-5e88-aaa7-b400bdbabd6a', 13, 27, 'መንግሥትም፥ ግዛትም፥ ከሰማይም ሁሉ በታች ያሉ የመንግሥታት ታላቅነት ለልዑሉ ቅዱሳን ሕዝብ ይሰጣል፤ መንግሥቱ የዘለዓለም መንግሥት ነው፤ መኳንንቱም ሁሉ ይገዙለታል፤ ይታዘዙለትማል።”'),
  ('5f1e6563-49d6-5cbd-a8e4-af98635d526b', '421f1369-69bd-5cb7-ae23-85d43c738612', 'cbfe5710-0d14-5e88-aaa7-b400bdbabd6a', 14, 28, 'የነገሩም ፍጻሜ እስከዚህ ድረስ ነው። እኔም ዳንኤል በአሳቤ እጅግ ተቸገርሁ፤ ፊቴም ተለወጠብኝ፤ ዳሩ ግን ነገሩን በልቤ ጠብቄአለሁ።'),
  ('b8359fac-c60d-5b87-aa8f-cf8c15e50e72', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '9a0abe46-fa96-5711-a755-d7cfba51010e', 1, 1, 'በመጀመሪያ ከተገለጠልኝ ራእይ በኋላ፥ ንጉሡ ብልጣሶር በነገሠ በሦስተኛው ዓመት ለእኔ ለዳንኤል ራእይ ተገለጠልኝ፤'),
  ('dc70ec31-d276-57cf-a577-ce6238a9666a', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '9a0abe46-fa96-5711-a755-d7cfba51010e', 2, 2, 'በኤላም አውራጃ በአለው በሱሳ ግንብ ሳለሁ ራእይ አየሁ፤ በኡባልም ወንዝ አጠገብ ነበርሁ።'),
  ('3d2f429e-3679-55bd-a797-b8b13615ffe1', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '9a0abe46-fa96-5711-a755-d7cfba51010e', 3, 3, 'ዐይኖችንም አቅንቼ አየሁ፤ እነሆም አንድ የበግ አውራ መጥቶ በኡባል አጠገብ ቆመ፤ ሁለት ቀንዶች ነበሩት፤ ቀንዶቹም ረዣዥሞች ነበሩ፤ አንዱ ቀንዱ ግን ከሌላው ቀንዱ ይበልጥ ነበር፤ ረዥሙም ቀንዱ በስተኋላ የበቀለ ነበር።'),
  ('dd49aa49-cda2-5d5d-acad-7e337ee0cfef', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '9a0abe46-fa96-5711-a755-d7cfba51010e', 4, 4, 'አውራውም በግ ወደ ምዕራብ፥ ወደ ሰሜንም፥ ወደ ደቡብም በቅንዱ ሲጐሽም አየሁ፤ አራዊትም ሁሉ በፊቱ አይቆሙም ነበር፤ ከእጁም የሚያድን አልነበረም፤ እንደ ፈቃዱም አደረገ፤ ከፍ ከፍም አለ።'),
  ('34f77db0-a3a6-5b56-a407-3fdd15477183', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '9a0abe46-fa96-5711-a755-d7cfba51010e', 5, 5, 'እኔ ዳንኤልም የባሪ ክፍል በምትሆን በሱሳ ነበርሁ፤ ስመለከትም እነሆ ከምዕራብ ወገን አንድ አውራ ፍየል በምድር ሁሉ ፊት ላይ ወጣ፤ ምድርንም አልነካም፤ ለፍየሉም በዐይኖቹ መካከል አንድ ታላቅ ቀንድ ነበረው።'),
  ('7c8e43f3-402f-52c1-a73c-05cc4342d06d', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '9a0abe46-fa96-5711-a755-d7cfba51010e', 6, 6, 'ሁለትም ቀንድ ወደ አለው፥ በኡባል ወንዝም ፊት ቆሞ ወደ አየሁት አውራ በግ መጣ፤ በኀይሉም ቍጣ ፈጥኖ ወደ እርሱ ሮጠ።'),
  ('547ba4fb-469b-5a6c-a122-78ad838b874e', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '9a0abe46-fa96-5711-a755-d7cfba51010e', 7, 7, 'ወደ አውራውም በግ ቀርቦ አየሁት፤ እርሱም ዘልሎ ወጣበት፤ አውራውንም በግ መታ፤ ሁለቱንም ቀንዶች ሰበረ፤ አውራውም በግ በፊቱ ሊቆም ኀይል አልነበረውም፤ እርሱም በምድር ላይ ጥሎ ረገጠው፤ አውራውንም በግ ከእጁ ያድን ዘንድ የሚችል አልነበረም።'),
  ('3aeefcab-5b47-5463-a02b-739453eb8be7', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '9a0abe46-fa96-5711-a755-d7cfba51010e', 8, 8, 'አውራውም ፍየል ራሱን እጅግ ታላቅ አደረገ፤ በበረታም ጊዜ ታላቁ ቀንዱ ተሰበረ፤ ወደ አራቱም የሰማይ ነፋሳት የሚመለከቱ አራት ቀንዶች ከበታቹ ወጡ።'),
  ('169dc7a4-5d19-5300-a54a-6a17addf6895', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '9a0abe46-fa96-5711-a755-d7cfba51010e', 9, 9, 'ከእነርሱም ከአንደኛው አንድ ጠንካራ ቀንድ ወጣ፤ ወደ ደቡብም፥ ወደ ምሥራቅም፥ ወደ መልካሚቱም ምድር እጅግ ከፍ አለ።'),
  ('1fc4bfdb-351c-5fe0-adf3-d66f2a9efcb9', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '9a0abe46-fa96-5711-a755-d7cfba51010e', 10, 10, 'እስከ ሰማይም ሠራዊት ድረስ ከፍ አለ፤ ከሰማይ ሠራዊትና ከሰማይ ከዋክብትም የተወሰኑትን ወደ ምድር ጣለ፥ ረገጣቸውም።'),
  ('7a9d2a46-4990-570b-a79a-6564c2edb3c2', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '9a0abe46-fa96-5711-a755-d7cfba51010e', 11, 11, 'እስከ ሠራዊትም አለቃ ድረስ ምርኮን አዳነ፤ ከእርሱም የተነሣ የዘወትሩ መሥዋዕት ተሻረ፤ የመቅደሱም ስፍራ ፈረሰ።'),
  ('cd489ebb-a92d-5f29-a0ec-715a34a651cc', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '9a0abe46-fa96-5711-a755-d7cfba51010e', 12, 12, 'የኀጢአትም መሥዋዕት ከዘወትሩ መሥዋዕት ጋር ተሰጠ፤ እውነትም ወደ ምድር ተጣለች፤ አደረገም፤ ተከናወነም።'),
  ('1daa872b-a31e-5716-a2e1-3300a0d60311', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '9a0abe46-fa96-5711-a755-d7cfba51010e', 13, 13, 'ከቅዱሳኑም አንዱ ሲናገር ሰማሁ፤ ለተናገረው ለቅዱሱም ሁለተኛው ቅዱስ “ስለ ዘወትሩ መሥዋዕት፥ መቅደሱና ሠራዊቱም ይረገጡ ዘንድ ስለሚሰጥና ስለሚያጠፋ ኀጢአት የሆነው ይህ ራእይ እስከ መቼ ይቈያል?” አለው።'),
  ('c02d9f63-aab0-5c63-a305-e87c7cc196b3', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '9a0abe46-fa96-5711-a755-d7cfba51010e', 14, 14, 'እርሱም፥ “እስከ ሁለት ሺህ ሦስት መቶ ማታና ጥዋት ድረስ ነው፤ ከዚያም በኋላ መቅደሱ ይነጻል” አለኝ።'),
  ('f9300408-0e25-56a3-ad5f-8d690b9876fe', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '1b28a4b5-fe45-50b4-a9c0-145ce2fbb77b', 1, 15, 'እኔም ዳንኤል ራእዩን በአየሁ ጊዜ ልረዳው ፈለግሁ፤ እነሆም የሰው አምሳል በፊቴ ቆሞ ነበር።'),
  ('343f0469-64dd-54d1-ac37-c6d019908f4b', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '1b28a4b5-fe45-50b4-a9c0-145ce2fbb77b', 2, 16, 'በኡባልም ወንዝ መካከል የሰው ድምፅ ሰማሁ፤ ጠርቶም “ገብርኤል ሆይ! ራእዩን ለዚህ ሰው ግለጥለት” አለ።'),
  ('3cc5e989-28a3-5303-a723-aab273920bcc', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '1b28a4b5-fe45-50b4-a9c0-145ce2fbb77b', 3, 17, 'እኔም ወደ ቆምሁበት ቀረበ፤ በመጣም ጊዜ ፈርቼ በግንባሬ ተደፋሁ፤ እርሱም፥ “የሰው ልጅ ሆይ! ራእዩ ለፍጻሜ ዘመን እንደ ሆነ አስተውል” አለኝ።'),
  ('46dcc465-d774-507a-afbc-b2a40bcac4b4', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '1b28a4b5-fe45-50b4-a9c0-145ce2fbb77b', 4, 18, 'ሲናገረኝም ደንግጬ በምድር ላይ በግንባሬ ተደፋሁ፤ እርሱም ዳሰሰኝ፤ አንሥቶም በእግሬ አቆመኝ።'),
  ('8c18455b-3503-5b60-a75b-20f4dfd3bd25', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '1b28a4b5-fe45-50b4-a9c0-145ce2fbb77b', 5, 19, 'እንዲህም አለኝ- “እነሆ በመቅሠፍቱ በመጨረሻ ዘመን የሚሆነውን አስታውቅሃለሁ፤ ይህ ገና ለፍጻሜ ዘመን ነውና።'),
  ('cc95aef5-9ce5-574a-a168-6fd4d776a119', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '1b28a4b5-fe45-50b4-a9c0-145ce2fbb77b', 6, 20, 'ያየኸው፥ ቀንዶች ያሉት አውራ በግ የሜዶንና የፋርስ ንጉሥ ነው።'),
  ('fbb21e92-95e8-5237-ad6e-77504ef15be8', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '1b28a4b5-fe45-50b4-a9c0-145ce2fbb77b', 7, 21, 'አውራውም ፍየል የግሪኮች ንጉሥ ነው፤ በዐይኖቹም መካከል ያለው ታላቁ ቀንድ መጀመሪያው ንጉሥ ነው።'),
  ('a48566d1-e72e-5497-ab1f-495dca6d1328', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '1b28a4b5-fe45-50b4-a9c0-145ce2fbb77b', 8, 22, 'እርሱም በቆመበት በተሰበረ ጊዜ በእርሱ ፋንታ አራቱ እንደ ተነሡ፤ እንዲሁ ከወገኑ አራት መንግሥታት ይነሣሉ፤ ነገር ግን በኀይል አይተካከሉትም።'),
  ('a0cad460-5462-5571-a5c4-511e5e9eb911', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '1b28a4b5-fe45-50b4-a9c0-145ce2fbb77b', 9, 23, 'በመንግሥታቸውም መጨረሻ ኀጢአታቸው በተሞላች ጊዜ፥ እንቆቅልሽን የሚያስተውል፥ ፊቱ ጨካኝ የሆነ ንጉሥ ይነሣል።'),
  ('9e1a7fa2-a27f-5844-ae39-cf32a8f4c17b', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '1b28a4b5-fe45-50b4-a9c0-145ce2fbb77b', 10, 24, 'ኀይሉም ይበረታል፤ በተአምርም ያጠፋል፤ ያደርግማል፤ ያከናወንማል፤ ኀያላንንና ቅዱሳንን ሕዝብ ያጠፋል።'),
  ('d05aeca0-c45e-5b85-a5ec-bec8b61f5b79', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '1b28a4b5-fe45-50b4-a9c0-145ce2fbb77b', 11, 25, 'ያንገቱን ቀንበር ያቀናል። ተንኰል በእጁ አለ፤ በልቡም ይታበያል፤ በሽንገላም ብዙዎችን ያጠፋል፤ በአለቆቹም አለቃ ላይ ይቆማል፤ ያለ እጅም ይሰብራል።'),
  ('8b876924-b9b2-5d7d-ab86-8a9dfeb735e7', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '1b28a4b5-fe45-50b4-a9c0-145ce2fbb77b', 12, 26, 'የተነገረውም የማታውና የጥዋቱ ራእይ እውነተኛ ነው፤ ነገር ግን ከብዙ ዘመን በኋላ ስለሚሆን ራእዩን ዝጋ።”'),
  ('c4fe27e2-b161-5f1e-aed8-f0421cfd741e', '0b0ae5ec-d786-5088-a1fc-7bb154ad4652', '1b28a4b5-fe45-50b4-a9c0-145ce2fbb77b', 13, 27, 'እኔም ዳንኤል ተኛሁ፤ አያሌም ቀን ታመምሁ፤ ከዚያም በኋላ ተነሥቼ የንጉሡን ሥራ እሠራ ነበር፤ ስለ ራእዩም አደንቅ ነበር፤ የሚያስተውለው ግን አልነበረም።'),
  ('6cf79b84-7847-56fc-ae9e-ce15a9fac75e', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 1, 1, 'በከለዳውያን መንግሥት ላይ በነገሠ፥ ከሜዶን ዘር በነበረ በአሕሻዊሮስ ልጅ በዳርዮስ በመጀመሪያው ዓመት፥'),
  ('d4f194db-75f9-529d-aa98-ec69aae0ab2d', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 2, 2, 'በነገሠ በመጀመሪያው ዓመት እኔ ዳንኤል በሰባ ዓመት የኢየሩሳሌም ጥፋት እንደሚፈጸም እግዚአብሔር በነቢዩ ኤርምያስ የተናገረው ቃል በተጻፈበት መጽሐፍ ያለውን የዘመኑን ቍጥር ዐወቅሁ።'),
  ('9ddf4a1a-4634-5219-a954-719b9070046d', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 3, 3, 'ማቅ ለብሼ፥ በአመድም ላይ ሆኜ ስጾም እጸልይና እለምን ዘንድ ፊቴን ወደ ጌታ ወደ አምላክ አቀናሁ።'),
  ('701d3ae3-61f3-5be0-a096-c63e57f96586', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 4, 4, 'ወደ አምላኬም ወደ እግዚአብሔር ጸለይሁ፤ ተናዝዤም እንዲህ አልሁ፥ “ጌታ ሆይ! ከሚወድዱህና ትእዛዝህን ከሚፈጽሙ ጋር ቃል ኪዳንንና ምሕረትን የምትጠብቅ ታላቅና የምታስፈራ አምላክ ሆይ!'),
  ('48b610fc-8b7a-5f01-a011-954660399025', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 5, 5, 'ኀጢአትን ሠርተናል፥ በድለንማል፤ ክፋትንም አድርገናል፤ ዐምፀንማል፤ ከትእዛዝህና ከፍርድህም ፈቀቅ ብለናል፤'),
  ('accf5a27-b714-58b3-ab43-921e3cbc8a4d', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 6, 6, 'በስምህም ለነገሥታቶቻችንና ለአለቆቻችን፥ ለአባቶቻችንም፥ ለሀገሩም ሕዝብ ሁሉ የተናገሩትን ባሪያዎችህን ነቢያትን አልሰማንም።'),
  ('820a4c86-3cf3-5a46-aa2c-827b4c6cdd1c', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 7, 7, 'ጌታ ሆይ! ጽድቅ ለአንተ ነው፤ እንደ ዛሬም ለእኛ ለይሁዳ ሰዎችና በኢየሩሳሌም ለሚቀመጡ፥ ለእስራኤልም ሁሉ በቅርብና በሩቅም ላሉት አንተን በበደሉበት በበደላቸው ምክንያት በበተንህበት ሀገር ሁሉ የፊት እፍረት ነው።'),
  ('da547078-702f-574a-a328-a7123dfe3731', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 8, 8, 'ጌታ ሆይ! በአንተ ላይ ኀጢአት ስለ ሠራን ለእኛና ለነገሥታቶቻችን፥ ለአለቆቻችንና ለአባቶቻችንም የፊት እፍረት ነው።'),
  ('5d284e48-5682-5e43-ac86-71afd06de62f', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 9, 9, 'ለጌታ ለአምላካችን ምሕረትና ይቅርታ ነው፤ በእርሱ ላይ ዐምፀናልና።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('71825918-abbd-599c-a544-9041b2a49506', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 10, 10, 'በባሪያዎቹም በነቢያት እጅ በፊታችን በአኖረው በሕጉ እንሄድ ዘንድ የአምላካችንን የግዚአብሔርን ቃል አልሰማንምና።'),
  ('17cd20a3-e2a9-5054-a777-d3850c9074c1', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 11, 11, 'እስራኤልም ሁሉ ሕግህን ተላልፈዋል፤ ቃልህንም መስማትን እንቢ ብለዋል፤ በእርሱ ላይ ኀጢአት ሠርተናልና መርገምና በእግዚአብሔር ባሪያ በሙሴ ሕግ የተጻፈው መሐላ መጣብን።'),
  ('a498494e-a777-54e7-a500-69e893f49320', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 12, 12, 'እጅግ ክፉ ነገርንም በእኛ ላይ በማምጣቱ በላያችንና በእኛ ዘንድ በተሾሙት ፈራጆቻችን ላይ የተናገረውን ቃል አጸና፤ በኢየሩሳሌምም ላይ እንደ ተደረገው ያለ ነገር ከቶ ከሰማይ ሁሉ በታች አልተደረገም።'),
  ('3d7c621c-2723-5fe3-adc7-5dfc75010e72', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 13, 13, 'በሙሴም ሕግ እንደ ተጻፈ ይህ ክፉ ነገር ሁሉ መጣብን፤ ከኀጢአታችን እንመለስ፤ እውነትህንም እናስብ ዘንድ ወደ አምላካችን ወደ እግዚአብሔር ፊት አልለመንንም።'),
  ('5e4c7fc1-291c-5b36-a653-3113b4c3ddbf', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 14, 14, 'ስለዚህም እግዚአብሔር ክፉ ነገርን በእኛ ላይ ፈጥኖ አመጣ፤ አምላካችን እግዚአብሔር በሚሠራው ሥራ ሁሉ ጻድቅ ነውና፤ እኛም ቃሉን አልሰማንምና።'),
  ('b3631318-0703-5473-a258-1a1a19203381', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 15, 15, 'አሁንም ሕዝብህን ከግብፅ ምድር በበረታች እጅ ያወጣህ፥ እንደ ዛሬም ቀን ስምን ለአንተ ያደረግህ ጌታ አምላካችን ሆይ! ኀጢአትን ሠርተናል፤ ክፋትንም አድርገናል።'),
  ('c559a56b-b6a2-53ae-af8f-18ab2366382c', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 16, 16, 'ጌታ ሆይ! በፍጹም ቸርነትህ ቍጣህንና መቅሠፍትህን ከከተማህ ከኢየሩሳሌምና ከተቀደሰው ተራራህ መልስ፤ ስለ ኀጢአታችንና ስለ አባቶቻችን በደል ኢየሩሳሌምና ሕዝብህ በዙሪያችን ላሉት ሁሉ መሰደቢያ ሆነዋልና።'),
  ('878dbb69-fa6d-5879-a665-d50700447375', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 17, 17, 'አሁንም አምላካችን ሆይ! የባሪያህን ጸሎትና ልመናውን ስማ፤ ጌታ ሆይ! በፈረሰው በመቅደስህ ላይ ስለ አንተ ስትል ፊትህን አብራ።'),
  ('3670763c-eb82-558e-a932-2f90f027a47f', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 18, 18, 'አምላኬ ሆይ! በፊትህ የምንለምን ስለ ብዙ ምሕረትህ ነው እንጂ ስለ ጽድቃችን አይደለምና ጆሮህን አዘንብለህ ስማ፤ ዐይንህንም ገልጠህ ጥፋታችንንና ስምህ የተጠራባትን ከተማ ተመልከት።'),
  ('73f7a46a-2376-5523-aaa6-0c2e9f96881d', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 19, 19, 'አቤቱ! ስማ፤ አቤቱ፥ ይቅር በል፤ አቤቱ! አድምጥና አድርግ፤ አምላኬ ሆይ! ስምህ በከተማህና በሕዝብህ ላይ ተጠርቶአልና ስለ ራስህ አትዘግይ።”'),
  ('4a48b4b1-0f90-553f-a37e-3868eea1fb67', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 20, 20, 'እኔም ገና ስናገርና ስጸልይ፥ በኀጢአቴና በሕዝቤም በእስራኤል ኀጢአት ስናዘዝ፥ በአምላኬም በእግዚአብሔር ፊት ስለ ተቀደሰው ስለ አምላኬ ተራራ ይቅርታን ስጠይቅ፥'),
  ('93fb4d47-5c71-5153-acc8-4debf667a79d', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 21, 21, 'ገናም በጸሎት ስናገር አስቀድሜ በራእይ አይችው የነበረው ሰው ገብርኤል እነሆ እየበረረ መጣ፤ በማታም መሥዋዕት ጊዜ ዳሰሰኝ።'),
  ('8b178659-32c0-5d60-a1e4-043e1190809d', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 22, 22, 'አስተማረኝም፤ ተናገረኝም፤ እንዲህም አለ፥ “ዳንኤል ሆይ! ጥበብንና ማስተዋልን እሰጥህ ዘንድ አሁን መጥቻለሁ።'),
  ('0b650c90-7dd0-5329-aadb-f80c5e2ceb20', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 23, 23, 'አንተ እጅግ የተወደድህ ሰው ነህና በልመናህ መጀመሪያ ላይ ቃል ወጥቶአል፤ እኔም እነግርህ ዘንድ መጥቻለሁ፤ አሁንም ነገሩን መርምር፤ ራእዩንም አስተውል።'),
  ('8dab8cee-ad35-554c-aa52-70ce49b8fb86', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 24, 24, '“ዐመፃን ይጨርስ፥ ኀጢአትንም ይፈጽም፥ በደልንም ያስተሰርይ፥ የዘለዓለምንም ጽድቅ ያገባ፥ ራእይንና ትንቢትን ያትም፥ ቅዱሰ ቅዱሳኑንም ይቀባ ዘንድ በሕዝብህና በቅድስት ከተማህ ላይ ሰባ ሱባዔ ተቀጥሮአል።'),
  ('56b1c35a-4e8f-55be-a5f2-ba7a27ae9a1f', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 25, 25, 'ስለዚህ ዕወቅ፤ አስተውልም፤ ኢየሩሳሌምን መጠገንና መሥራት ትእዛዙ ከሚወጣበት ጀምሮ እስከ ንጉሥ ክርስቶስ ድረስ ሰባት ሱባዔና ስድሳ ሁለት ሱባዔ ይሆናል፤ ጎዳናዋና ቅጥርዋ ተመልሶ ይሠራል፤ ጊዜውም ይፈጸማል።'),
  ('aaebdc19-e8b7-50d9-ad6d-428d73efa2e2', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 26, 26, 'ከስድሳ ሁለት ሱባዔ በኋላም መሢሕ ይገደላል፤ በእርሱም ዘንድ ፍትሕ የለም፤ ከሚመጣውም አለቃ ጋር ከተማዪቱንና መቅደሱን ያጠፋል፤ ፍጻሜውም በጎርፍ ይሆናል፤ እስከ መጨረሻም ድረስ ጦርነት ይሆናል፤ ጥፋትም ተቀጥሮአል።'),
  ('52a94110-3413-5aed-a32e-a455b9f5f740', '9c56918f-b1b1-587e-a57a-7393324fa86e', 'ef27ce94-3961-5ea7-a400-e0047d959282', 27, 27, 'እርሱም ከብዙ ሰዎች ጋር ቃል ኪዳን ለአንድ ሱባዔ ያጸናል፤ በሱባዔውም እኩሌታ መሥዋዕቱንና ቍርባኑን ያስቀራል፤ በቤተ መቅደስም የጥፋት ርኵሰት ይሆናል፤ እስከ ዘመኑም ፍጻሜ የጥፋት መጨረሻ ይሆናል።”'),
  ('6607789f-e6a6-5c8e-aa8c-a7b21ba24e84', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 1, 1, 'በፋርስ ንጉሥ በቂሮስ በሦስተኛው ዓመተ መንግሥት ብልጣሶር ለተባለው ለዳንኤል ነገር ተገለጠለት፤ ነገሩም እውነት ነበረ፤ ታላቅ ኀይልና ማስተዋልም በራእዩ ውስጥ ተሰጠው።'),
  ('55c1dcd8-164f-5fde-a958-361ea45ad8b0', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 2, 2, 'በዚያም ወራት እኔ ዳንኤል ሦስት ሳምንት ሙሉ ሳዝን ነበርሁ።'),
  ('4021a679-3fef-542d-a5dc-b4992a64c5fc', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 3, 3, 'ማለፊያ እንጀራም አልበላሁም፤ ሥጋና የወይን ጠጅም በአፌ አልገባም፤ ሦስቱም ሳምንት እስኪፈጸም ድረስ ዘይት አልተቀባሁም።'),
  ('8a97ea48-af0f-5125-a633-f270aa0049cf', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 4, 4, 'ከመጀመሪያውም ወር በሃያ አራተኛው ቀን ጤግሮስ በተባለው በታላቁ ወንዝ አጠገብ ነበርሁ።'),
  ('7a218fb8-3e4d-58d3-a546-ac08cbe2cec4', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 5, 5, 'ዐይኖችንም አነሣሁ፤ እነሆም በፍታ የለበሰውንም ጥሩም የአፌዝን ወርቅ በወገቡ ላይ የታጠቀውን ሰው አየሁ።'),
  ('b37b7a2c-643c-5875-aec9-a3c6eee23f49', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 6, 6, 'አካሉም እንደ ቢረሌ ይመስል ነበር፤ ፊቱም እንደ መብረቅ አምሳያ ነበረ፤ ዐይኖቹም እንደሚንበለበል ፋና፥ ክንዶቹና እግሮቹም እንደ ጋለ ናስ፥ የቃሉም ድምፅ እንደ ብዙ ሕዝብ ድምፅ ነበረ።'),
  ('ff8f6368-6da5-503c-a64f-32163f73e159', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 7, 7, 'እኔም ዳንኤል ብቻዬን ራእዩን አየሁ፤ ከእኔ ጋር የነበሩ ሰዎች ግን ራእዩን አላዩም፤ ነገር ግን ታላቅ ድንጋጼ ወደቀባቸው፤ ከፍርሃትም የተነሣ ሸሹ።'),
  ('8b4cf7c3-9c5d-53f6-a412-61ee45175bd7', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 8, 8, 'እኔም ብቻዬን ቀረሁ፤ ይህንም ታላቅ ራእይ አየሁ፤ ኀይልም አልቀረልኝም፤ ክብሬም ወደ ውርደት ተለወጠብኝ፤ ኀይልም አጣሁ።'),
  ('1e379afe-e9af-5e78-a342-e4623190a86c', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 9, 9, 'የቃሉንም ድምፅ ሰማሁ፤ የቃሉንም ድምፅ በሰማሁ ጊዜ ደንግጬ በምድር ላይ በግምባሬ ተደፋሁ።'),
  ('69f1f9e5-cf9f-5c76-a1b6-0fdb60816f5f', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 10, 10, 'እነሆም እጅ ዳሰሰችኝ፤ እጄንም ይዞ በጕልበቴ አቆመኝ።'),
  ('e13fe25c-9bc8-5f2f-a77f-a29e9eac0b0c', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 11, 11, 'እርሱም፥ “እጅግ የተወደድህ ሰው ዳንኤል ሆይ! እኔ ዛሬ ወደ አንተ ተልኬአለሁና የምነግርህን ቃል አስተውል፤ ቀጥ ብለህም ቁም” አለኝ። ይህንም ቃል በአለኝ ጊዜ እየተንቀጠቀጥሁ ቆምሁ።'),
  ('3c985635-27a8-5805-aec5-2d4362ee5b3b', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 12, 12, 'እርሱም እንዲህ አለኝ፥ “ዳንኤል ሆይ! አትፍራ፤ ልብህ ያስተውል ዘንድ፥ ሰውነትህም በአምላክህ ፊት ይዋረድ ዘንድ ከአደረግህበት ከመጀመሪያው ቀን ጀምሮ ቃልህ ተሰምቶአል፤ እኔም ስለ ቃልህ መጥቻለሁ።'),
  ('4374e3db-ce61-502c-a40a-989ab17f059c', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 13, 13, 'የፋርስ መንግሥት አለቃ ግን ሃያ አንድ ቀን በፊቴ ቁሞ ነበር። እነሆም ከዋነኞቹ አለቆች አንዱ ሚካኤል ሊረዳኝ መጣ፤ እኔም ከፋርስ ንጉሥ ጋር በዚያ ተውሁት።'),
  ('82984336-a908-56a5-a926-97e33091c997', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 14, 14, 'የራእዩም ጊዜ ገና ነውና በኋለኛው ዘመን ለሕዝብህ የሚሆነውን አስታውቅህ ዘንድ አሁን መጥቻለሁ።”'),
  ('5c9a650b-73a1-5bbe-a37d-cf48e443d664', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 15, 15, 'ይህንም ቃል በተናገረኝ ጊዜ ፊቴን ወደ ምድር ደፋሁ፤ ዲዳም ሆንሁ።'),
  ('69c453df-6890-5fdd-a39e-4df3af25945f', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 16, 16, 'እነሆም የሰው ልጅ የሚመስል ከንፈሬን ዳሰሰኝ፤ ያን ጊዜም አፌን ከፍቼ ተናገርሁ፤ በፊቴም ቁሞ የነበረውን፥ “ጌታዬ ሆይ! ከራእዩ የተነሣ ሰውነቴ ታወከች፤ ኀይልም አጣሁ።'),
  ('862483e0-7054-5a70-ad2f-c59a7442ef45', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 17, 17, 'አቤቱ! አገልጋይህ ከጌታዬ ጋር ይናገር ዘንድ እንዴት ይችላል? ከአሁንም ጀምሮ ኀይሌ አይጸናም፤ እስትንፋስም አልቀረልኝም” አልሁት።'),
  ('ce23183a-c175-5745-a1fd-a13a23c22c2d', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 18, 18, 'ደግሞ ሰው የሚመስል ዳሰሰኝ፤ አበረታኝም።'),
  ('fdde3da4-cdb3-544c-ae10-c436952319da', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 19, 19, 'እርሱም፥ “እጅግ የተወደድህ ሰው ሆይ! አትፍራ፤ ሰላም ለአንተ ይሁን፤ በርታ፤ ጽና፥” አለኝ። በተናገረኝም ጊዜ በረታሁና፥ “አበርትተኸኛልና ጌታዬ ይናገር” አልሁ።'),
  ('fba04454-4712-5b5b-acc2-9da3d02c35cd', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 20, 20, 'እርሱም እንዲህ አለኝ፥ “ወደ አንተ የመጣሁት ስለ ምን እንደ ሆነ፥ ታውቃለህን? አሁንም የፋርስን አለቃ እወጋው ዘንድ እመለሳለሁ፤ እኔም ስወጣ፥ እነሆ የግሪኮች አለቃ ይመጣል።'),
  ('eff4271c-8f6f-531c-a774-e2ba44dde1c4', 'db457c68-5b45-59c7-ad9b-57d18be92b69', '476419b8-8866-5d46-a6a3-033defc79cc9', 21, 21, 'ነገር ግን በእውነት መጽሐፍ የተጻፈውን እነግርሃለሁ፤ በዚህም ነገር ከአለቃችሁ ከሚካኤል በቀር የሚረዳኝ ማንም የለም።'),
  ('a1de1b94-a468-508f-a0d5-03f9c4d5e853', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 1, 1, '“እኔም በሜዶናዊው በዳርዮስ መጀመሪያ ዓመት አጸናውና አበረታው ዘንድ ቆሜ ነበር።'),
  ('ee5ce16e-84f0-5243-a088-42cf45ea58c2', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 2, 2, '“አሁንም እውነትን እነግርሃለሁ። እነሆ ሦስት ነገሥታት ደግሞ በፋርስ ይነሣሉ፤ አራተኛውም ከሁሉ ይልቅ እጅግ ባለጸጋ ይሆናል፤ በባለጸግነቱም በበረታ ጊዜ በግሪክ መንግሥት ላይ ሁሉን ያስነሣል።'),
  ('eeb2bb05-cee1-5802-a0a5-e86787a5930b', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 3, 3, 'ኀያልም ንጉሥ ይነሣል፤ ትልቅ አገዛዝንም ይገዛል፤ እንደ ፈቃዱም ያደርጋል።'),
  ('469fa060-6bef-5e3e-a0a2-648bcdac4258', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 4, 4, 'በተነሣም ጊዜ መንግሥቱ ትሰበራለች፤ በአራቱም ነፋሳት ትበተናለች፤ ለዘሩ ግን አይከፋፈልም፤ ከእርሱም በኋላ እርሱ እንደ ገዛበት አገዛዝ አይሆንም፤ መንግሥቱ ታልፋለች፤ ከእነዚህም ለሌሎች ትሰጣለች።'),
  ('bd188c2d-5603-5ca7-a735-dcb95d55750f', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 5, 5, '“የአዜብም ንጉሥ ይበረታል፤ ከአለቆቹም አንዱ በእርሱ ላይ ይበረታል፤ ከእርሱም ይልቅ ብዙ ግዛትን ይገዛል።'),
  ('810c5307-4d2a-5662-a032-a3633d28b8df', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 6, 6, 'ከዘመናትም በኋላ ይቀላቀላሉ፤ የአዜብም ንጉሥ ሴት ልጅ ቃል ኪዳን ለማድረግ ወደ መስዕ ንጉሥ ትመጣለች። የክንድዋ ኀይል ግን አይጸናም፤ ዘሩም አይጸናም፤ እርስዋና እርስዋን ያመጡ፥ የወለዳትም፥ በዚያም ዘመን ያጸናት አልፈው ይሰጣሉ።'),
  ('9ab37f49-3beb-59c9-a057-5d100458ba4e', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 7, 7, 'ነገር ግን ከሥርዋ ቍጥቋጥ አንዱ በስፍራው ይነሣል፤ ወደ ሠራዊቱም ይመጣል፤ ወደ መስዕም ንጉሥ አምባ ይገባል፤ በላያቸውም ያደርጋል፤ ያሸንፍማል።'),
  ('b4e2a7b6-787f-5d03-a6f6-0948cbb98e07', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 8, 8, 'አማልክቶቻቸውንና ቀልጠው የተሠሩትን ምስሎቻቸውን ከብርና ከወርቅም የተሠሩትን የከበሩትን ዕቃዎች ወደ ግብፅ ይማርካል፤ እርሱም ከመስዕ ንጉሥ በላይ ሆኖ ይቆማል።'),
  ('c38023e4-3501-5c7a-a535-634f59310059', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 9, 9, 'ይህም ወደ አዜብ ንጉሥ መንግሥት ይገባል፥ ነገር ግን ወደ ገዛ ምድሩ ይመለሳል።'),
  ('1f23635e-bb7f-5baf-a3b9-50163e9f4853', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 10, 10, '“ልጆቹም ይዋጋሉ፤ ብዙ ሕዝብንና ሠራዊትን ይሰበስባሉ፤ እርሱም ይመጣል፤ ይበረታማል፤ ያልፍማል፤ ተመልሶም እስከ አምባው ድረስ ይዋጋል።'),
  ('b313dc59-8886-5d18-a161-d38d14151c60', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 11, 11, 'የአዜብም ንጉሥ ይቈጣል፤ ወጥቶም ከመስዕ ንጉሥ ጋር ይዋጋል፤ ብዙ ሕዝብንም ለሰልፍ ያቆማል፤ ሕዝቡም አልፎ በእጁ ይሰጣል።'),
  ('59669487-ea60-520e-a88f-261df47df9b9', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 12, 12, 'ሕዝቡንም ይወስዳል፤ ልቡንም ያስታብያል፤ አእላፋትንም ይጥላል፤ ነገር ግን አያሸንፍም።'),
  ('5edc0287-c554-54a0-a11e-70027c500c15', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 13, 13, 'የመስዕም ንጉሥ ይመለሳል፥ ከቀደመውም የበለጠ ብዙ ሕዝብን ያቆማል፤ በዘመናትና በዓመታትም ፍጻሜ ከታላቅ ሠራዊትና ከብዙ ሀብት ጋር ይመጣል።'),
  ('b435abad-1289-5c72-a08a-03f0c93be6ec', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 14, 14, 'በዚያም ዘመን ብዙ ሰዎች በአዜብ ንጉሥ ላይ ይነሣሉ፤ ከሕዝብህም መካከል የዐመፅ ልጆች ራእዩን ያጸኑ ዘንድ ይነሣሉ፤ ነገር ግን ይወድቃሉ።'),
  ('ca83b4e0-e6d1-5725-abde-5737548d0196', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 15, 15, 'የመስዕም ንጉሥ ይመጣል፤ አፈርንም ይደለድላል፤ የተመሸገችንም ከተማ ይይዛል፤ የአዜብም ክንድ የተመረጡትም ሕዝብ አይቆሙም፤ ለመቋቋምም ኀይል የላቸውም።'),
  ('5912dac1-f35c-5bc7-a992-6388f77f9e32', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 16, 16, 'ወደ እርሱ የሚመጣው እንደ ፈቃዱ ያደርጋል፤ በፊቱም የሚቆም የለም፤ በመልካሚቱም ምድር ይቆማል፤ ሁሉም በእጁ ይፈጸማል።'),
  ('319887cb-7410-5322-a7e4-473781135382', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 17, 17, 'ከመንግሥቱም ሁሉ ኀይል ጋር ይመጣ ዘንድ ፊቱን ያቀናል፤ ከእርሱም ጋር አንድነትን ያደርጋል፤ ለጥፋቱም ሴት ልጅ ትሰጠዋለች፤ እርስዋም አትጸናም፤ ለእርሱም አትሆንም።'),
  ('adbf6ebc-6961-5955-aad4-25d2f8ecf707', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 18, 18, 'ከዚህም በኋላ ፊቱን ወደ ደሴቶች ይመልሳል፤ ብዙዎችንም ይወስዳል፤ የኀፍረት አለቆቹንም ይሽራል፤ ኀፍረቱም በላዩ ይመለሳል።'),
  ('64fe2726-9048-5367-a173-89d6c261824c', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 19, 19, 'ፊቱንም ወደ ገዛ ምድሩ አንባዎች ይመልሳል፤ ደክሞም ይወድቃል፤ አይገኝምም።'),
  ('a2429de6-a1e3-5327-a0bd-777449c2de3f', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '4e331c7e-f82c-5adf-a6d9-b3c9c1bab4af', 20, 20, '“የመንግሥትን ሥልጣንና ክብር የሚሽር ይነሣል፤ በመንበሩም ይቀመጣል፤ ነገር ግን በቍጣም ሳይሆን፥ በጦርነትም ሳይሆን ከጥቂት ቀን በኋላ ይሰበራል።'),
  ('4e21133b-d5d4-59df-a610-e0c0b03cdf99', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 1, 21, 'በእርሱም ስፍራ የተጠቃ ሰው ይነሣል፤ የመንግሥቱንም ክብር አይሰጡትም፤ በቀስታ ይመጣል፤ መንግሥትንም በማታለል ይይዛል።'),
  ('f5fd3ebb-8553-5847-a443-456d1d143fc2', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 2, 22, 'የሚጐርፉ ተዋጊዎቹም ክንዶች ከፊቱ ይሰበራሉ፤ እርሱና የቃል ኪዳኑ አለቃም ይሰበራሉ።'),
  ('2e7cdd31-9ee3-51e9-a000-2f363c7a8048', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 3, 23, 'ከእርሱም ጋር ከተወዳጀ በኋላ ተንኰልን ያደርጋል፤ ከጥቂትም ሕዝብ ጋር ወጥቶ ይበረታል።'),
  ('269924b1-06a5-56b9-a274-1a4e65bae852', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 4, 24, 'በቀስታም ከሀገር ሁሉ ወደ ለመለመችው ክፍል ይገባል፤ አባቶቹና የአባቶቹ አባቶች ያላደረጉትንም ያደርጋል፤ ብዝበዛውንና ምርኮውን፥ ሀብቱንም በመካከላቸው ይበትናል፤ በምሽጎችም ላይ እስከ ጊዜው ድረስ ዐሳቡን ይፈጥራል።'),
  ('fce17965-d6ca-5acc-ab27-45532544b65f', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 5, 25, 'በታላቅም ሠራዊት ሆኖ ኀይሉንና ልቡን በአዜብ ንጉሥ ላይ ያስነሣል፤ የአዜብም ንጉሥ በታላቅና በብዙ ሠራዊት ይበረታል፤ ነገር ግን ዐሳብ በእርሱ ላይ ይፈጥራሉና አይጸናም።'),
  ('fb0c993e-fe03-5464-af2e-a9aa7b954efe', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 6, 26, 'መብሉንም የሚበሉ ሰዎች ይሰብሩታል፤ ሠራዊቱም ይጐርፋል፤ ብዙዎችም ተገድለው ይወድቃሉ።'),
  ('2011a060-7efa-5d0d-a550-3a40cd41aed0', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 7, 27, 'እነዚህም ሁለት ነገሥታት በልባቸው ክፋትን ያደርጋሉ፤ በአንድ ገበታም ተቀምጠው ሐሰትን ይናገራሉ፤ ገና ጊዜው አልደረሰምና አይከናወንላቸውም።'),
  ('b50d76ad-976c-54ce-aec2-1fa0b6b8c471', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 8, 28, '“ከብዙም ሀብት ጋር ወደ ምድሩ ይመለሳል፥ ልቡም በተቀደሰው ቃል ኪዳን ላይ ይሆናል፤ ፈቃዱንም ያደርጋል፥ ወደ ገዛ ምድሩም ይመለሳል።'),
  ('52ea1424-9e39-55e6-a278-2e7889b25014', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 9, 29, 'በተወሰነውም ጊዜ ይመለሳል፤ ወደ አዜብም ይመጣል፤ ነገር ግን የኋለኛው እንደ ፊተኛው አይሆንም።'),
  ('a47cadc1-6a31-53a8-a7a9-58a88915c633', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 10, 30, 'ጺም፥ ከይተምና ኔባእ በእርሱ ላይ ይመጣሉ ስለዚህ አዝኖ ይመለሳል፥ በቅዱሱም ቃል ኪዳን ላይ ይቈጣል፤ ፈቃዱንም ያደርጋል፤ ተመልሶም ቅዱሱን ቃል ኪዳን የተዉትን ሰዎች ይመለከታል።'),
  ('00d9b0d6-747b-5153-a16d-bca74906a19e', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 11, 31, 'ዘሮችም ከእርሱ ይነሣሉ፤ ቤተ መቅደሱንም ያረክሳሉ፤ የዘወትሩንም መሥዋዕት ያስቀራሉ፤ የጥፋትንም ርኵሰት ያቆማሉ።'),
  ('2e289174-7af4-5b0e-a084-a38a77a200c5', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 12, 32, 'ቃል ኪዳኑን የሚበድሉትንም በማታለል ያስታሉ፤ ነገር ግን አምላካቸውን የሚያውቁ ሕዝብ ይበረታሉ፤ ያደርጋሉም።'),
  ('f6b67ef2-6650-5868-a2ed-3c2ed5fcbaba', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 13, 33, 'በሕዝቡም መካከል ያሉ ጥበበኞች ብዙ ሰዎችን ያስተምራሉ፤ ነገር ግን በሰይፍና በእሳት ነበልባል በምርኮና በብዙ ዘመን ብዝበዛ ይደክማሉ።'),
  ('42841c27-cb08-5960-a3bd-9530c707ff54', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 14, 34, 'በመከራም ጊዜ በጥቂት ርዳታ ይረዳሉ፤ ብዙ ሰዎችም በግብዝነት ወደ እነርሱ ይጨመራሉ።'),
  ('c88f2950-6b2d-52dd-a90e-50d7518b1525', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 15, 35, 'ጊዜው ገና አልደረሰምና ያግሏቸው፥ ያነጿቸውና ያጠሯቸው ዘንድ ከዐዋቂዎች እኩሌቶቹ እስከ ጊዜው ድረስ መከራ ይቀበላሉ፤ በከበረ ቦታ የሚቆም፥ መጽሐፍንም የሚያነብብ ሰው ይህን ነገር ልብ ያድርግ።'),
  ('b9efa5a1-33c0-5403-abac-551a47e339b1', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 16, 36, '“ንጉሡም እንደ ፈቃዱ ያደርጋል፤ ራሱንም ከፍ ከፍ ያደርጋል፤ በአማልክት ሁሉ ላይ ራሱን ታላቅ ያደርጋል፤ በአማልክትም አምላክ ላይ በትዕቢት ይናገራል፤ ቍጣም እስኪፈጸም ድረስ ይከናወንለታል፤ የተወሰነው ይደረጋልና።'),
  ('445a2d2f-fd9b-5368-a0a7-32dab60c2079', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 17, 37, 'የአባቶቹንም አምላክ፥ የሴቶችንም ምኞት አያከብርም፤ ራሱንም በሁሉ ላይ ታላቅ ያደርጋልና አማልክትን ሁሉ አያውቅም።'),
  ('0e4e413a-1922-5173-ab28-fc2065e82c02', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 18, 38, 'ጽኑዕ በሆነ በእግዚአብሔር ሥልጣንም ይኰራል፤ አባቶቹም ያላወቁትን አምላክ በወርቅና በብር፥ በዕንቍና በከበረ ነገር ያከብረዋል።'),
  ('a8a4d0c7-38d2-5cec-aa3b-e3763e1cb457', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 19, 39, 'ከባዕድም አምላክ ጋር የተመሸጉ ጽኑ አምባዎችን ያደርጋል፤ ክብርን ያበዛላቸዋል፤ በብዙም ላይ ያስገዛቸዋል፤ ምድርንም በዋጋ ይከፍላል።'),
  ('4442370d-c9b0-5eb6-a3a7-8f417989a167', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 20, 40, '“በፍጻሜ ዘመንም የዐዜብ ንጉሥ ከእርሱ ጋር ይዋጋል፤ የመስዕም ንጉሥ ከሠረገሎችና ከፈረሰኞች፥ ከብዙ መርከቦችም ጋር ይመጣበታል፤ ወደ ሀገሮችም ይገባል፤ ይጐርፍማል፥ ያልፍማል።'),
  ('b2baefcd-f83c-5eeb-a745-3ab8a6e7ea77', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 21, 41, 'ወደ መልካሚቱም ምድር ይገባል፤ ብዙ ሀገሮችም ይወድቃሉ፤ ነገር ግን ኤዶምያስና ሞዓብ፥ ከአሞንም ልጆች የበለጡት ከእጁ ይድናሉ።'),
  ('f6c77c15-0e50-54ef-a258-eedb384d0cc0', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 22, 42, 'እጁን በሀገሮች ላይ ይዘረጋል፤ የግብፅም ምድር ከእጁ አታመልጥም።'),
  ('1cada673-daf0-500e-a221-0f28c3f8a858', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 23, 43, 'በወርቅና በብርም መዝገብ ላይ ፥ በከበረችም በግብፅ ዕቃ ሁሉ ላይ ይሠለጥናል፤ የሊብያና የኢትዮጵያ ሰዎችም ረዳቶች ይሆኑታል።'),
  ('5291b736-d0d3-5f4f-a2a8-3fd1cb25218a', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 24, 44, 'ከምሥራቅና ከሰሜን ግን ወሬ ይደርሰዋል፤ ይቸኩላልም፤ ብዙ ሰዎችንም ይገድልና ፈጽሞ ያጠፋ ዘንድ በታላቅ ቍጣ ይወጣል።'),
  ('b4bd45dd-90f1-5c39-aaf8-792c523a7060', '107e309f-2bf4-5f05-a799-22c07c2b14bf', '42ba067c-404d-5b9f-aa0a-e61aa7b578ef', 25, 45, 'ንጉሣዊ ድንኳኑንም በባሕርና በከበረው በቅዱሱ ተራራ መካከል ይተክላል፤ እስከ ጊዜውም ይበረታል። የሚረዳውም የለም።'),
  ('edbdcadc-4c7d-5440-af85-873d57905256', 'e917077e-93d9-5603-a2f0-918c9b74e1dd', 'd2890df2-b46c-5729-a138-8d0deddcaed7', 1, 1, '“በዚያም ዘመን ስለ ሕዝብህ ልጆች የሚቆመው ታላቁ አለቃ ሚካኤል ይነሣል፤ ሕዝብም በምድር ከተፈጠረ ጀምሮ እስከዚያ ዘመን ድረስ እንደ እርሱ ያለ ያልሆነ የመከራ ዘመን ይሆናል፤ በዚያም ዘመን በመጽሐፉ ተጽፎ የተገኘው ሕዝብህ ሁሉ እያንዳንዱ ይድናል።'),
  ('af2fccea-6779-5158-a056-e0d2994eed68', 'e917077e-93d9-5603-a2f0-918c9b74e1dd', 'd2890df2-b46c-5729-a138-8d0deddcaed7', 2, 2, 'በምድርም ትቢያ ውስጥ ከአንቀላፉት ብዙዎች እኩሌቶቹ ለዘለዓለም ሕይወት፥ እኩሌቶቹም ለእፍረትና ለዘለዓለም ጕስቍልና ይነሣሉ።'),
  ('34111622-2094-592d-aa12-f69ec8793876', 'e917077e-93d9-5603-a2f0-918c9b74e1dd', 'd2890df2-b46c-5729-a138-8d0deddcaed7', 3, 3, 'ጥበበኞቹም እንደ ሰማይ ፀዳል፥ ከጻድቃንም ብዙዎች እንደ ከዋክብት ለዘለዓለም ያበራሉ።'),
  ('1a1f32ce-382b-52ce-afce-cccd78a8306f', 'e917077e-93d9-5603-a2f0-918c9b74e1dd', 'd2890df2-b46c-5729-a138-8d0deddcaed7', 4, 4, 'ዳንኤል ሆይ! አንተ ግን እስከ ፍጻሜ ዘመን ድረስ ቃሉን ዝጋ፤ መጽሐፉንም አትም፤ ብዙ ሰዎች ይመረምራሉ፤ እውቀትም ይበዛል።”'),
  ('b50f4394-607e-59e6-a434-99f0d942d655', 'e917077e-93d9-5603-a2f0-918c9b74e1dd', 'd2890df2-b46c-5729-a138-8d0deddcaed7', 5, 5, 'እኔም ዳንኤል አየሁ፤ እነሆም ሁለት ሌሎች ቆመው ነበር፤ አንዱ በዚህ በወንዙ ዳር፥ ሌላውም በዚያ በወንዙ ዳር።'),
  ('104d79ec-6507-5e86-aafc-c1188a8d9cde', 'e917077e-93d9-5603-a2f0-918c9b74e1dd', 'd2890df2-b46c-5729-a138-8d0deddcaed7', 6, 6, 'አንዱም ከወንዙ ውኃ በላይ የነበረውን በፍታም የለበሰውን፥ “የዚህ ምልክት ፍጻሜ እስከ መቼ ነው?” አለው።'),
  ('30df63a3-3f4b-582d-a46f-842f49043a72', 'e917077e-93d9-5603-a2f0-918c9b74e1dd', 'd2890df2-b46c-5729-a138-8d0deddcaed7', 7, 7, 'ከወንዙም ውኃ በላይ የነበረው፥ በፍታም የለበሰው ሰው ቀኝና ግራ እጁን ወደ ሰማይ አንሥቶ፥ “ለዘመንና ለዘመናት፥ ለዘመንም እኩሌታ ነው ፤ የተቀደሰውም ሕዝብ ኀይል መበተን በተጨረሰ ጊዜ ይህ ሁሉ ይፈጸማል” ብሎ ለዘለዓለም ሕያው ሆኖ በሚኖረው ሲምል ሰማሁ።'),
  ('c6b14cd0-5c18-5b18-af11-9c7561ec9f9b', 'e917077e-93d9-5603-a2f0-918c9b74e1dd', 'd2890df2-b46c-5729-a138-8d0deddcaed7', 8, 8, 'ሰማሁም፤ ነገር ግን አላስተዋልሁም፤ የዚያን ጊዜም፥ “ጌታዬ ሆይ! የዚህ ሁሉ ፍጻሜ ምንድን ነው?” አልሁ።'),
  ('25c7fe72-1b9c-5a5d-a36f-3c7d43dd1b9d', 'e917077e-93d9-5603-a2f0-918c9b74e1dd', 'd2890df2-b46c-5729-a138-8d0deddcaed7', 9, 9, 'እርሱም እንዲህ አለኝ፥ “ዳንኤል ሆይ! ቃሉ እስከ ፍጻሜ ዘመን ድረስ የተዘጋና የታተመ ነውና ሂድ፤'),
  ('d71cea06-6a79-575e-a197-2733d25f99ed', 'e917077e-93d9-5603-a2f0-918c9b74e1dd', 'd2890df2-b46c-5729-a138-8d0deddcaed7', 10, 10, 'ብዙ ሰዎችም ሰውነታቸውን ያጠራሉ፤ ያነጡማል፤ ይፈተኑማል፤ ክፉዎች ግን ክፋትን ያደርጋሉ፤ ክፉዎችም ሁሉ አያስተውሉም፤ ጥበበኞች ግን ያስተውላሉ።'),
  ('8d523bc8-57f4-5a80-aab8-8e79d7c5aa25', 'e917077e-93d9-5603-a2f0-918c9b74e1dd', 'd2890df2-b46c-5729-a138-8d0deddcaed7', 11, 11, 'ለጥፋት ርኵሰት ለመስጠት የዘወትሩ መሥዋዕት ከቀረ ጀምሮ፥ ሺህ ሁለት መቶ ዘጠና ቀን ይሆናል።'),
  ('56c80a17-9b73-5b0a-a4df-2df06f63c04d', 'e917077e-93d9-5603-a2f0-918c9b74e1dd', 'd2890df2-b46c-5729-a138-8d0deddcaed7', 12, 12, 'የሚታገሥ፥ እስከ ሺህ ሦስት መቶ ሠላሳ አምስት ቀንም የሚደርስ ምስጉን ነው።'),
  ('51cf29d0-8620-5279-ae9a-c805577cf0ab', 'e917077e-93d9-5603-a2f0-918c9b74e1dd', 'd2890df2-b46c-5729-a138-8d0deddcaed7', 13, 13, 'አንተ ግን ሂድና እረፍ፤ ለፍጻሜው ገና ቀንና ዘመን አለ፤ በቀኑም መጨረሻ ትነሣለህ፤ በዕጣ ክፍልህም ትቆማለህ።”'),
  ('7be1e6fb-dc1f-5c0f-af01-1fc21f3de51e', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 1, 1, 'በባቢሎን የሚኖር ስሙ ኢዮአቄም የሚባል አንድ ሰው ነበረ።'),
  ('d50eee85-55fa-52b2-a708-dbe49742306b', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 2, 2, 'የኬልቅዩ ልጅ ስሟ ሶስና የምትባል ሚስት አግብቶ ነበር። እጅግም መልከ መልካምና እግዚአብሔርን የምትፈራ ነበረች።'),
  ('ff4cbc9b-4247-5055-a178-7369d6b0ed53', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 3, 3, 'ወላጆችዋም ደጋግ ሰዎች ነበሩ። ለልጃቸውም የሙሴን ሕግ አስተምረዋት ነበር።'),
  ('b24ce199-37e5-59b4-ac28-2e961ed2d063', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 4, 4, 'ባሏ ኢዮአቄምም እጅግ ባለጸጋ ነበር፤ በቤቱም አጠገብ የተክል ቦታ ነበረው፤ ከሁሉ እርሱ ይከብር ነበርና አይሁድም ወደ እርሱ ይመጡ ነበር።'),
  ('fbee9e53-cfba-5e25-ab6a-e1c7ca5cd971', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 5, 5, 'ኀጢአት ከባቢሎን፥ ሕዝቡን እንጠብቃቸዋለን ከሚሉ ግብዞች መምህራንም እንደ ወጣች እግዚአብሔር ስለ እነርሱ የተናገረባቸው ሁለት ግብዞች መምህራን በዚያ ወራት በሕዝቡ መካከል ታዩ።'),
  ('f563b42e-1dd8-5980-a80d-836a1a913973', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 6, 6, 'እነርሱም በኢዮአቄም ቤት ያገለግሉ ነበር፥ የሚፈራረዱ ሰዎችም ሁሉ ወደ እርሱ ይመጡ ነበር።'),
  ('53f97618-6e23-513a-a8b6-01293b04956b', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 7, 7, 'ሕዝቡ ሁሉ ወደ ቤታቸው ከገቡ በኋላ ቀትር በሆነ ጊዜ ሶስና ወደ ባሏ ተክል ቦታ እየገባች በዚያ ትመላለስ ነበር።'),
  ('44b211f7-3639-5022-a64d-5d633909b30a', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 8, 8, 'እነዚያም ሁለት መምህራንበዚያ እየገባች ስትመላለስ ሁልጊዜ ያይዋት ነበር። እርሷንም ተመኙአት።'),
  ('cba01ca9-f9bd-53e0-a6e8-9ebf9605dfed', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 9, 9, 'ልቡናቸውንም ለወጡ፤ ሰማይንም እንዳያዩ ዐይናቸውን ከደኑ፤ እውነተኛ ሕግንም አላሰቡም።'),
  ('3571b46a-70bf-5451-a8a3-7cec7e74ca8a', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 10, 10, 'ሁለቱም ሁሉ በፍቅሯ ተነደፉ፤ እርስ በርሳቸውም በልቡናቸው ያለውን ነገር አልተነጋገሩም።'),
  ('b5b6d8fb-f0fb-5219-ad02-b6e8e472a93f', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 11, 11, 'ምኞታቸውን መናገር አፍረዋልና። ከእርስዋም ጋር ይተኙ ዘንድ ይፈልጉ ነበር።'),
  ('99b7e088-9c5a-5570-a6eb-b26fc6e91099', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 12, 12, 'ያገኝዋትም ዘንድ ሁልጊዜ ይጠብቋት ነበር።'),
  ('a6f88ced-d96d-5370-a69b-aa99f48bcd6c', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 13, 13, 'አንዱ ሁለተኛውን፥ “የምሣ ጊዜ ነውና ወደ ቤታችን እንግባ አለው፤”'),
  ('591c53d5-d8dc-5d04-a3a9-c0921ee3979d', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 14, 14, 'እየራሳቸውም ተለያይተው ሄዱ። ተመልሰውም በዚያ በአንድነት ተገናኙ፤ ሁለቱም ሁሉ ተያዩ፤ ያንጊዜም ምኞታቸውን ተነጋገሩ። እርስዋንም ብቻዋን የሚያገኙበትን ጊዜ ተቃጠሩ።'),
  ('0b249ec6-c788-5202-a280-3ecd193533d3', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 15, 15, 'ከዚህ በኋላ ቀን ሲጠብቋት ሶስና ሁልጊዜም ትገባ እንደ ነበር ከሁለቱ ደንገጥሮችዋ ጋር ገባች፤ አልቧትም ነበርና በተክል ቦታ ውስጥ ትታጠብ ዘንድ ወደደች።'),
  ('7d2adf1c-659c-593a-ab42-db5797d141ae', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 16, 16, 'ተሰውረውም ከሚጠብቋት ከሁለቱ መምህራን በቀር በዚያ ማንም አልነበረም።'),
  ('d6d17f41-94c7-5a9c-a653-9bc434f0ae8e', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 17, 17, 'ትታጠብም ዘንድ ደንገጥሮችዋን ሽቱና ዘይት እንዲያመጡና የተክሉን ቦታ በር እንዲዘጉ አዘዘቻቸው።'),
  ('889f05f8-a1fd-5967-a399-570c0cab8ad7', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 18, 18, 'እነርሱም እንዳዘዘቻቸው አደረጉ፤ የተክሉንም ቦታ በር ዘግተው ያዘዘቻቸውን ያመጡ ዘንድ በስርጥ ጎዳና ወጡ፤ የተሰወሩ እነዚያን መምህራን ግን አላዩአቸውም ነበር።'),
  ('ed2e2178-5dcd-5607-a822-d2430334cefa', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 19, 19, 'እነዚያም ደንገጥሮች ከወጡ በኋላ ሁለቱ መምህራን ተነሥተው ወደ እርስዋ ሮጡ።'),
  ('22803673-b212-5abb-a79f-c02c5ed0a183', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 20, 20, '“እነሆ የተክሉ ቦታ በር ተዘግትዋል፤ የሚያየንም የለም፤ ከአንቺ ጋር እንተኛ ዘንድ እንወዳለንና እሺ በዪን።'),
  ('b3ad8e1d-bda6-5dde-a1df-8bb995c64a20', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 21, 21, 'ይህ ከአልሆነ ግን ከአንቺ ጋር ወንድ እንደ አገኘን ተናግረን እናጣላሻለን፤ ስለዚህም ነገር ደንገጥሮችሽን ከአንቺ አስወጥተሽ ሰደድሽ” አሏት።'),
  ('463d61ea-dd1d-5987-a659-1dc4899492f4', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 22, 22, 'ሶስናም አለቀሰች፤ ”በሁሉም ፈጽሜ ተቸነፍሁ፤ ባደርገውም እሞታለሁ፤ ባላደርገውም አልድንም፤ ከእጃቸው ማምለጥንም አልችልም።'),
  ('5d0c1c81-d0ed-5608-a5fe-f8c911c790ad', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 23, 23, 'በእግዚአብሔር ፊት ከምበድል ኀጢአት ሳልሠራ በእጃችሁ መውደቅ ይሻለኛል” አለች።'),
  ('6d902282-9995-5f6f-aca5-d14b20467890', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 24, 24, 'ሶስናም ቃሏን አሰምታ ጮኸች፤ እነዚያም መምህራን ከእርሷ ጋር ጮኹ።'),
  ('99a42972-af4e-5876-ac25-186116b54ebb', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 25, 25, 'አንዱም ሮጦ የተክሉን ቦታ በር ከፈተ።'),
  ('80325d0b-c5df-515f-a81e-aec6a937654d', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 26, 26, 'በቤትዋም ያሉ ሰዎች በተክል ቦታW መካከል ጩኸትን ሰምተው ወጡ፤ ምንም እንደ ሆነ ያዩ ዘንድ በሥርጥ ጎዳና ሮጡ።'),
  ('2081ff46-8245-5708-a2b3-056d4a697a0e', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 27, 27, 'እነዚህም ሁለቱ መምህራን ይህን ነገር በተናገሩ ጊዜ በሶስና እንደዚህ ያለ ነገር ፈጽሞ ተሰምቶ አያውቅም ነበርና ዘመዶችዋና አገልጋዮችዋ እጅግ አፈሩ።'),
  ('10422cee-e624-55ef-a788-844fbfd827f4', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 28, 28, 'በማግሥቱም ሕዝቡ በባሏ በኢዮአቄም ዘንድ በተሰበሰቡ ጊዜ እነዚያ ሁለት መምህራን ሶስናን ያስገድሏት ዘንድ ከአመፀኛ ልቡናቸው ጋር መጡ።'),
  ('d13e4b01-04f0-5951-a802-d196930ad904', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 29, 29, '“በሕዝቡ ሁሉ ፊት ያመጧት ዘንድ ወደ ኢዮአቄም ሚስት ወደ ሶስና ላኩ” አሉ ወደሷም ላኩባት።'),
  ('f0ba61ce-5e04-52cc-a531-782a78326676', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 30, 30, 'እርሷም ከእናትና ከአባትዋ፥ ከልጆችዋና ከዘመዶችዋም ሁሉ ጋር መጣች።'),
  ('79f8791d-e87e-51c0-adfd-ed2ea46cbc92', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 31, 31, 'ሶስናም እጅግ ደመ ግቡና መልከ መልካም ነበረች።'),
  ('a29375c3-46ce-5642-a3cd-b1f6380b1ec8', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 32, 32, 'እነዚያም ዐመፀኞች መምህራን መልኳን ለመጥገብ ክንብንቧን ይገልጧት ዘንድ አዘዙ፤ ክንብንቧንም ገለጧት።'),
  ('4db0482e-d55a-5ae5-a524-59654e3dc5ae', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 33, 33, 'አባትዋና እናትዋ፥ ቤተ ሰቦችዋም፥ የሚያውቋትም ሰዎች ሁሉ አለቀሱላት።'),
  ('6776e02c-b9e9-5680-ad62-7854a19c0d5b', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 34, 34, 'እነዚያም ሁለቱ መምህራን በሕዝቡ መካከል ተነሥተው እጆቻቸውን በራሷ ላይ አኖሩ።'),
  ('27df3e16-023a-5546-ac2c-4361cf85e55f', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 35, 35, 'እሷ ግን ልቡናዋ በእግዚአብሔር አምኗልና እያለቀሰች ወደ ሰማይ ተመለከተች።'),
  ('3bc5c075-bb81-5c11-a50d-6e8275520dac', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 36, 36, 'እነዚያም መምህራን፥ “ብቻችንን በተክል ቦታ ውስጥ ስንመላለስ ይህች ሴት ከሁለቱ ደንገጥሮችዋ ጋር ገባች፤ ደንገጥሮችዋም ልካቸዋለችና የተክሉን ቦታ በር ዘግተው ሄዱ።'),
  ('33fc8336-b805-5b4e-ac5a-537e2ee5e4d0', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 37, 37, 'ደንገጥሮችዋንም ከላከቻቸው በኋላ አንድ ጎልማሳ ከተሰወረበት መጥቶ ከእርስዋ ጋር ተኛ።'),
  ('1aa5981e-2069-5c0c-a1b5-6818ecf81149', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 38, 38, 'እኛም በዚያ ተክል ቦታ ዳርቻ ሆነን ኀጢአታቸውን አየን፤ ወደ እነርሱም ሮጠን ሄድን፤ በአንድነትም ተኝተው አገኘናቸው።'),
  ('db7dc359-15e5-5585-a1af-519241fc11a2', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 39, 39, 'እኛም እርሱን መያዝ ተሳነን፤ እሱ በርትቶብናልና አመለጠን፤ የተክል ቦታውንም በር ከፍቶ ወጣ።'),
  ('d9e4034c-bf82-5bdc-a79c-e79b34278e7e', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 40, 40, 'እርስዋን ግን ያዝናት፤ ሰውየውም ማን እንደ ሆነ ጠየቅናት፤ ነገር ግን አልነገረችንም፤ ለዚህም ነገር እኛ ምስክሮች ነን” አሉ።'),
  ('d0b76062-a2c6-58fb-accf-223bd1c31542', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 41, 41, 'የሕዝብ መምህራን ነበሩና ፈራጆችም ነበሩና በአደባባይ የተሰበሰቡ ሰዎች ነገራቸውን አመኗቸው፤ ትሞትም ዘንድ ፈረዱባት።'),
  ('4894b0e1-c6a8-5504-a524-e94cf1251d66', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 42, 42, 'ሶስናም ቃሏን አሰምታ ጮኸች፥ “ዘለዓለማዊ የሆንህ፥ የተሰወረውን የምታውቅ፥ ከመሆኑ በፊት ሁሉን የምታውቅ አምላክ ሆይ!'),
  ('70585f9d-86dd-5e1e-a494-b00c0f757100', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 43, 43, 'በሐሰት እንደ መሰከሩብኝ አንተ ታውቃለህ፤ እነዚህ መምህራን ክፉ ነገርን ስለአደረጉብኝ የሠራሁት ነገር ሳይኖር እነሆ እሞታለሁ” አለች።'),
  ('3556fba2-befd-56fd-aea0-d7c2a779eab0', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 44, 44, 'እግዚአብሔርም ቃሏን ሰማት።'),
  ('0dc31dcd-71cd-58fc-a359-b439f3b05386', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 45, 45, 'ይገድሏትም ዘንድ ሲወስዷት እግዚአብሔር ስሙ ዳንኤል የሚባል የአንድ ወጣት ልጅ ልቡናን አነሣሣ።'),
  ('3d84bdf3-af64-5f4b-a3ce-e60f8161d95b', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 46, 46, 'እርሱም፥ “እኔ ከዚች ሴት ደም ንጹሕ ነኝ” ብሎ ቃሉን አሰምቶ ተናገረ።'),
  ('017067f3-f675-5f2a-a9b7-ef3fba2209a5', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 47, 47, 'ሕዝቡም ሁሉ ወደ እርሱ ተመልሰው፥ “አንተ የምትናገረው ይህ ነገር ምንድን ነው?” አሉ።'),
  ('c439841d-1f18-5d54-a7cb-1a344eedfb32', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 48, 48, 'ዳንኤልም በመካከላቸው ቆሞ፥ “አላዋቂዎች የምትሆኑ እናንት የእስራኤል ልጆች! ሳትመረምሩ፥ ነገሩንም ሳትረዱ በእስራኤል ሴት ልጅ ላይ እንደዚህ ትፈርዳላችሁን?'),
  ('68ebb89a-ba60-5a64-abb3-4e55011db5c3', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 49, 49, 'እነዚህ መምህራን በሐሰት መስክረውባታልና ወደ አደባባይ ተመለሱ” አላቸው።'),
  ('c94e01c1-cfb8-5b00-a3a0-e05a96f8559f', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 50, 50, 'ሕዝቡም ሁሉ እየሮጡ ወደ አደባባይ ተመለሱ፤ አለቆችም ዳንኤልን፥ “እግዚአብሔር አንተን አልቆሃልና በመካከላችን ተቀምጠህ ንገረን” አሉት።'),
  ('b3c8a514-b59d-5c08-a46f-471a59b74397', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 51, 51, 'ዳንኤልም፥ “እየራሳቸው አራርቃችሁ አቁሟቸው፤ እኔም ልመርምራቸው” አላቸው።'),
  ('19d3f52b-dc54-5383-a180-1654c80cfeb0', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 52, 52, 'እያንዳንዳቸውንም አራርቀው አቆሟቸው፤ እርሱም አንዱን ጠርቶ፥ “አንተ በክፋት ያረጀህ፥ ቀድሞ የሠራሃቸው ኀጢአቶችህ ደረሱብህ።'),
  ('73c2352d-d216-5eb2-a7be-0208c2b65711', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 53, 53, 'የሐሰት ፍርድን ፈርደሃልና ጻድቁንና ንጹሑን አትግደል ብሎ እግዚአብሔር ቢከለክል በደለኛውን አዳንህ፤ ንጹሑንም ገደልህ።'),
  ('7a98b4f7-c8f3-52ff-a3a3-596208ac6f37', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 54, 54, 'አሁንም ይህቺን ሴት ከአየሃት ሁለቱን ሁሉ በምን ዐይነት ዛፍ ሥር ሲጫወቱ አየህ? ንገረኝ” አለው “በኮክ ዛፍ ሥር ሲጫወቱ አየኋቸው” አለ።'),
  ('a17badd9-cca1-5b20-a577-e6d703de7f49', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 55, 55, 'ዳንኤልም፥ “በእውነት ሐሰትን ተናገርህ፤ ደምህ በራስህ ላይ ነው፤ ከመካከልህ ይሰነጥቅህ ዘንድ የእግዚአብሔር መልአክ እነሆ፥ ከእግዚአብሔር ዘንድ ታዘዘ” አለው።'),
  ('e1de9695-6203-5e99-a8c3-9cfd7daff21e', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 56, 56, 'እርሱንም እልፍ አደረገው፤ ሁለተኛውንም ያመጡት ዘንድ አዘዘ፤ አመጡትም፤ “አንተ የይሁዳ ዘር ያይደለህ የከነዓን ዘር ነህ፤ ውበት አሳተህ፤ ክፉ ፈቃድም ልቡናህን ገለበጠው።'),
  ('62108b1e-2ec8-5010-aae1-a58da4daa7ae', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 57, 57, 'እርስዋ እናንተን መከራከር አልቻለችምና፥ የይሁዳ ሴት ልጅ እናንተን ፈርታለችና፥ ዐመፃችሁንም ታግሣለችና የእስራኤልን ሴት ልጅ እንዲህ ታደርጓታላችሁን።'),
  ('70a1f3f2-440c-57aa-aa9a-8fe6915e3039', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 58, 58, 'አሁንም ሁለቱ ሲጫወቱ ያየህበት ዛፍ ምንድን ነው? ንገረኝ” አለው። እርሱም፥ “ሮማን በሚባል ዛፍ ሥር አየኋት” አለው።'),
  ('aac2325b-ff29-5d1d-a788-dbe0c8627a0b', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 59, 59, 'ዳንኤልም፥ “አንተም በእውነት ሐሰትን ተናገርህ፤ ደምህም በራስህ ላይ ነው፤ በሰይፍ ከሁለት ይሰነጥቅህ ዘንድ፥ ፈጽሞም ያጠፋህ ዘንድ እነሆ የእግዚአብሔር መልአክ ይጠብቅሃል” አለው።'),
  ('91be811d-5ec7-518b-a08f-4058938fd158', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 60, 60, 'ሕዝቡም ሁሉ ቃላቸውን አሰምተው ጮኹ፤ ያመነችበት፥ ሶስናን ያዳናት እግዚአብሔርንም አመሰገኑ።'),
  ('a95341c0-8a61-5a62-a99c-5587c65724d9', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 61, 61, 'ከቃላቸው የተነሣ ዳንኤል ነቅፏቸዋልና፥ ምስክርነታቸውንም ሐሰት አድርጎባቸዋልና በእነዚያ በሁለቱ መምህራን ላይ በጠላትነት ተነሡባቸው።'),
  ('6a807faa-dee6-5a6a-a502-ae719a9138b9', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 62, 62, 'እንደ ሙሴም ሕግ በባልንጀራቸው ላይ ክፉ እንደ አደረጉ በእነርሱም ላይ አደረጉባቸው። ገደሉአቸውም፤ በዚያችም ቀን ንጹሕ ደምን አዳኑ።'),
  ('4f48ff59-8610-503e-a570-5ed2df82a9d2', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 63, 63, 'በእርሷ ላይ ክፉ ሥራ አልተገኘምና ስለ ልጃቸው ስለ ሶስና ኬልቅዩና ሚስቱ ከባልዋ ከኢዮአቄምና ከዘመዶችዋ ሁሉ ጋር እግዚአብሔርን አመሰገኑት።'),
  ('b31884b9-086d-5e93-a200-b280eeff5d1d', '49625e03-a470-574e-a361-a2bd2a076ba6', '31693fb2-0633-5f20-a9aa-6518dfc9b159', 64, 64, 'ዳንኤልም ከዚያች ቀን ጀምሮ ሁልጊዜ በእግዚአብሔርና በሕዝቡ ፊት ገናና ሆነ።'),
  ('7c56b419-406c-5ee1-ab20-a0f69ab9f65b', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 1, 1, 'ንጉሡ አስጢያጊስም ሞቶ በአባቶቹ መቃብር ከተቀበረ በኋላ የፋርሱ ንጉሥ ቂሮስ መንግሥቱን ያዘ።'),
  ('865bc166-485d-5534-ab9c-4f1f7a7b4c1e', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 2, 2, 'ዳንኤልም የንጉሡ እልፍኝ አሽከር ነበረ፤ ከጓደኞቹም ሁሉ እርሱ ይከብር ነበር።'),
  ('46ab8a8b-6589-528a-a344-903631f67b59', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 3, 3, 'የባቢሎን ሰዎች የሚያመልኩት ስሙ ቤል የሚባል ጣዖት ነበር፤ ምግቡንም ሁልጊዜ ዐሥራ ሁለት ጫን በሚፈጅ ቻል ዐሥራ ሁለት መስፈሪያ ስንዴ፥ አርባ በግ፥ ስድስት ፊቀንም ወይን እያውጣጡ ይሰጡት ነበር።'),
  ('489cbd51-84e7-5e32-a20d-82b91c4da6c7', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 4, 4, 'ንጉሡም ያመልከው ነበር፤ ሁልጊዜም ወደ እርሱ እየሄደ ይሰግድለት ነበር፤ ዳንኤል ግን ለፈጣሪው ይሰግድ ነበር። ንጉሡም ዳንኤልን፥ “ለቤል የማትሰግድ ለምንድን ነው?” አለው።'),
  ('70201300-6448-5f28-a901-2bc13252812c', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 5, 5, 'ዳንኤልም ንጉሡን፥ “እኔስ ሰማይንና ምድርን የፈጠረ፥ ፍጥረትን ሁሉ የሚገዛ ሕያው አምላክን አመልካለሁ እንጂ የሰው እጅ የሠራው ጣዖትን አላመልክም” አለው።'),
  ('f06b8f60-44d3-53c8-a170-f7da8e6c0b68', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 6, 6, 'ንጉሡም፥ “ቤል ሕያው ያልሆነ አምላክ ይመስልሃልን? በየቀኑ እንደሚበላና እንደሚጠጣ አታይምን?” አለው።'),
  ('02a986d2-0b14-594d-a082-7d772c0dafa7', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 7, 7, 'ዳንኤልም ሳቀና፥ “ንጉሥ ሆይ! አያስቱህ፤ ይህስ ውስጡ ጭቃ፥ ላዩም ናስ ነው፤ ፈጽሞም አይበላም፥ አይጠጣምም” አለው።'),
  ('e1089cae-c849-5c0f-a243-d037a621167b', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 8, 8, 'ንጉሡም ተቈጣ፤ የቤልን ካህናት ጠርቶ፥ “ይህን የቤልን ምግብ ማን እንደሚበላው ካልነገራችሁኝ ትሞታላችሁ።'),
  ('1ded9647-c106-5e5c-a9c9-86dece6efb6b', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 9, 9, 'ቤል እንደሚበላ ብታረጋግጡልኝ ግን ቤልን የፀረፈ ዳንኤል ይሞታል” አላቸው። ዳንኤልም ንጉሡን፥ “እንዳልኸው ይሁን” አለው።'),
  ('02b4b15a-24c5-58c0-aa80-883c57fcbdd7', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 10, 10, 'ከሴቶቻቸውና ከልጆቻቸው በቀር የቤል ካህናት ሰባ ይሆኑ ነበር፤ ዳንኤልና ንጉሡም ወደ ቤል ቤት ሄዱ።'),
  ('e1f9d4a3-1423-5a8f-ab31-12ad40b10202', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 11, 11, 'የቤል ካህናትም እንዲህ አሉ፥ “እነሆ እኛ ወደ ውጭ እንሄዳለን፤ ንጉሥ ሆይ! አንተም ማዕዱን ሥራ፤ ወይኑንም ቀድተህ አዘጋጅተህ አኑር፤ ደጃፉንም ዝጋ፤ በማኅተምህም አትመው።'),
  ('bc840e93-a0e5-56be-a166-8de0d6804c36', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 12, 12, 'ሲነጋም ሂድ፤ ቤል ሁሉን ሳይበላ ቢገኝ እኛ እንሞታለን፤ ካልሆነ ግን በእኛ ላይ ሐሰትን የተናገረ ዳንኤል ይሞታል” አሉት።'),
  ('995f788f-70ae-5581-ae98-126b88af5dd7', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 13, 13, 'እነርሱ ግን የሚያደርጉትን ያውቁ ነበር፤ በማዕዱ በታች ስውር መግቢያ ነበራቸው፤ ሁልጊዜም በዚያ እየገቡ ይበሉ ነበር።'),
  ('36013ef7-8bc6-5064-a38e-810747fe8218', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 14, 14, 'እነርሱም ከወጡ በኋላ ንጉሡ ለቤል የሚበላውን አዘጋጀ፤ ዳንኤልም ብላቴናውን አመድ ያመጣ ዘንድ አዘዘው፤ በንጉሡ ፊት ብቻ በቤቱ ሁሉ ነሰነሰው፤ ከወጡም በኋላ ደጃፉን ዘግተው በንጉሡ ማኅተም አተሙት።'),
  ('1cdd0bb1-c932-5b70-a732-c933642c9b6f', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 15, 15, 'እነርሱም ከሄዱ በኋላ የቤል ካህናት እንደ ልማዳቸው ከልጆቻቸውና ከሚስቶቻቸው ጋር በሌሊት ገብተው ሁሉንም በሉ፤ ጠጡም።'),
  ('c53908f9-2103-52a0-ad83-c83d534aa65c', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 16, 16, 'ንጉሡና ዳንኤልም በማለዳ ሄዱ።'),
  ('7cd3eac9-5b2d-508b-a149-d33b763898a0', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 17, 17, 'ንጉሡም ዳንኤልን፥ “ማኅተሙ ደኅና ነውን?” አለው። ዳንኤልም፥ “ንጉሥ ሆይ፥ አወን ደኅና ነው” አለው።'),
  ('4ac582c9-2173-518f-a932-094a8d023bc2', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 18, 18, 'ከዚህም በኋላ ደጃፉን በከፈተ ጊዜ ንጉሡ ማዕዱን እንደ ጨረሱት አገኘ፤ በታላቅ ድምፅም ጮኸ፥ “ቤል ሆይ! አንተ ታላቅ ነህ፤ መታለልም የለብህም” አለ።'),
  ('f7be1dcc-2f9e-5cf7-a6da-86f0a207e759', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 19, 19, 'ዳንኤልም ሳቀ፤ ንጉሡንም ያዘው፤ ወደ ውስጥም እንዳይገባ ከለከለው፤ “ወደ ምድር ተመልከት፤ ፍለጋውንም እይ፤ ይህ የምን ፍለጋ ነው?” አለው።'),
  ('50c24e05-e61c-5e67-a258-797d10e07857', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 20, 20, 'ንጉሡም፥ “የወንዶችንና የሴቶችን፥ የልጆችንም ፍለጋ አያለሁ” አለ። ንጉሡም ተቈጣ።'),
  ('3328cbd3-da18-51f7-a27b-8799c233e62e', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 21, 21, 'ያንጊዜም የቤልን ካህናት ሚስቶቻቸውንና ልጆቻቸውን ያዛቸው፤ በማዕዱም የተዘጋጀውን ይበሉና ይጠጡ ዘንድ የሚገቡበትን ስውር በር አሳዩት።'),
  ('3a6a09a3-d7c9-5bba-a272-4c8d392b3ed2', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '13fa290c-b30f-5bbb-adf4-826ba602cecd', 22, 22, 'ስለዚህም ንጉሡ ገደላቸው፥ ቤልንም ለዳንኤል ሰጠው፤ ዳንኤልም ሰባበረው፤ ቤቱንም አፈረሰው።'),
  ('a5d75916-6857-5ff4-a182-85a23da972f3', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 1, 23, 'በዚያም ስፍራ የባቢሎን ሰዎች የሚያመልኩት ታላቅ ዘንዶ ነበር።'),
  ('1a129a6d-a42c-55dd-a7aa-2bc3b0a43037', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 2, 24, 'ንጉሡም ዳንኤልን፥ “ይህንም ናስ ነው ትለዋለህን? እነሆ ሕያው ነው፤ ይበላል፤ ይጠጣልም፤ ሕያው አምላክ አይደለም ትለው ዘንድ አትችልም፤ ስለዚህ ስገድለት” አለው።'),
  ('26283dae-b131-55f7-a8aa-302616689e73', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 3, 25, 'ዳንኤልም “ለፈጣሪዬ ለእግዚአብሔር እሰግዳለሁ፤ እርሱ ሕያው አምላክ ነውና።'),
  ('063f9ba0-d9ac-5de5-a63e-525ef25843c6', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 4, 26, 'ንጉሥ ሆይ! ይህን ዘንዶ ያለ ሰይፍና ያለ በትር እገድለው ዘንድ ፍቀድልኝ” አለው፤ ንጉሡም ዳንኤልን፥ “ፈቅጀልሃለሁ” አለው።'),
  ('7a0e238c-722b-520f-ae25-99c3ccd2fe72', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 5, 27, 'ዳንኤልም አደሮማርና ጠጕር ስብም አምጥቶ በአንድነት ቀቀለው፤ ልህሉህም አደረገው፤ ለዘንዶውም በአፉ አጐረሰው፤ ዘንዶውም በጐረሰው ጊዜ ተሰንጥቆ ሞተ፤ ዳንኤልም፥ “አምላካችሁን እዩ” አላቸው።'),
  ('62877735-3bbe-54b9-aa63-d9540a09a82f', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 6, 28, 'ከዚህ በኋላ የባቢሎን ሰዎች በሰሙ ጊዜ እጅግ ተቈጡ፤ በንጉሡም ላይ ተነሡ፤ እንዲህም አሉ፥ “ንጉሥ ይሁዳዊ ሆነ፤ ቤልን ሰበረ፤ ካህናቱንም አረደ፤ ዘንዶውንም ገደለ።”'),
  ('7bbe3aeb-d0a0-5e56-a771-a85520739bdf', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 7, 29, 'ወደ ንጉሡም ሄዱ፤ እንዲህም አሉት፥ “ዳንኤልን ስጠን። ይህ ካልሆነ ግን ገንዘብህን እንዘርፋለን፤ እንገድልሃለን፤ ቤትህንም በእሳት እናቃጥላለን” አሉት።'),
  ('e73e7b98-6506-5701-a91b-5c450c21dbd4', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 8, 30, 'ንጉሡም እጅግ እንዳስጨነቁት በአየ ጊዜ፥ ለንጉሡም ግዴታ በሆነበት ጊዜ ዳንኤልን አሳልፎ ሰጣቸው።'),
  ('034505c3-2f25-51d1-a546-68599d1d48d2', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 9, 31, 'እነርሱም ወደ አንበሶች ጕድጓድ ጣሉት፤ በዚያም ስድስት ቀን ተቀመጠ።'),
  ('0c20d45d-0c7f-535b-a526-a14a3ed7422d', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 10, 32, 'በዚያም ሰባት አንበሶች ነበሩ። በየቀኑም ሁለት ሰውና ሁለት በግ ይመግቧቸው ነበር፤ ያንጊዜ ግን ዳንኤልን እንዲበሉት ምንም አልሰጧቸውም ነበር።'),
  ('371d5761-e127-51c4-a1df-ce57f2adb32b', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 11, 33, 'ነቢዩ ዕንባቆምም በይሁዳ ነበር፤ የምስር ንፍሮም አስቀቀለ፤ እንጀራም አስጋገረ፤ በቅርጫትም አድርጎ እህል ለሚያጭዱ ሰዎች ይዞ ወደ እርሻ ሄደ።'),
  ('250ca87f-aaaa-516f-a888-20dde8c49b9a', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 12, 34, 'የእግዚአብሔርም መልአክ ዕንባቆምን፥ “ይህን ምሳ በባቢሎን በአንበሶች ጕድጓድ ላለው ለዳንኤል ውሰድ” አለው።'),
  ('4d8e65c7-0d3e-5c56-aecb-3a4eaba00287', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 13, 35, 'ዕንባቆምም፥ “አቤቱ! ባቢሎንን አላየሁም፤ የአንበሶችም ጕድጓድ ወዴት እንደ ሆነ አላውቅም” አለው።'),
  ('e66c47d3-0688-55d4-a65b-ccfcc9fa35b2', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 14, 36, 'የእግዚአብሔርም መልአክ በራሱ ጠጕር ተሸክሞ በመንፈስ ቅዱስ ኀይል በባቢሎን ወደ አለው ወደ አንበሶች ጕድጓድ አደረሰው።'),
  ('0985cbdf-d5be-552a-a896-c2895d83f0a1', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 15, 37, 'ዕንባቆምም እንዲህ ብሎ ጮኸ፥ “ዳንኤል! ዳንኤል! እግዚአብሔር የላከልህን ይህን ምሳ ተቀበል” አለ።'),
  ('af70fb3a-5a8a-50cc-a3c6-a8d0d6f1463e', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 16, 38, 'ዳንኤልም፥ “ወዳጆቹን የማይዘነጋቸው እግዚአብሔር አሰበኝን?” አለ።'),
  ('f3c59131-f140-5fe3-a505-ec98d01007d0', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 17, 39, 'ዳንኤልም ተነሥቶ በላ፤ የእግዚአብሔርም መልአክ ዕንባቆምን ወዲያውኑ ወደ ሀገሩ መለሰው።'),
  ('f45c040c-205a-594f-aecc-bb9628505246', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 18, 40, 'ንጉሡም በሰባተኛዪቱ ቀን መጥቶ ለዳንኤል አለቀሰለት፤ ወደ አንበሶቹም ጕድጓድ በቀረበ ጊዜ ዳንኤልን በአንበሶቹ መካከል ተቀምጦ አየው።'),
  ('8218c154-35b4-55ee-abcb-3939a45a4872', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 19, 41, 'ንጉሡም በታላቅ ቃል ጮኸ፤ እንዲህም አለ፥ “የዳንኤል አምላክ እግዚአብሔር ሆይ! አንተ ታላቅ ነህ፤ ያለ አንተም ሌላ አምላክ የለም” አለ።'),
  ('8c72f020-d057-5423-a06b-381f449f630a', '3c8b3476-ffca-5b54-ab89-52ebe38e5fa3', '03409dd6-d79d-557e-a50a-c07b8ced01eb', 20, 42, 'ዳንኤልንም ያንጊዜ ከአንበሶቹ ጕድጓድ አወጣው። ዳንኤልን ይገድሉት ዘንድ የወደዱ እነዚያንም ሰዎች ይዘው በአንበሶች ጕድጓድ ጣሏቸው፤ አንበሶቹም ወዲያውኑ በፊቱ በሉአቸው።'),
  ('aef7b94e-2811-5444-a269-12b12bea99e5', '7cb54daf-c36c-5b18-a23e-a62842cf98f7', 'b31a75e5-e0d3-53d5-af45-8584f256374f', 1, 1, 'በይሁዳ ነገሥታት በዖዝያንና በኢዮአታም በአካዝና በሕዝቅያስም ዘመን በእስራኤልም ንጉሥ በኢዮአስ ልጅ በኢዮርብዓም ዘመን ወደ ብኤሪ ልጅ ወደ ሆሴዕ የመጣ የእግዚአብሔር ቃል ይህ ነው።'),
  ('43d7ac18-4fea-50d4-a31e-b342fe64b745', '7cb54daf-c36c-5b18-a23e-a62842cf98f7', '11249bb3-a65d-5cc6-adcf-fdd90923d550', 1, 2, 'ወደ ሆሴዕ የመጣ የእግዚአብሔር የቃሉ መጀመሪያ ይህ ነው፤ እግዚአብሔር ሆሴዕን፥ “ምድሪቱ ከእግዚአብሔር ርቃ ታመነዝራለችና ሂድ፤ ዘማዊቱን ሴትና የዘማዊቱን ልጆች ለአንተ ውሰድ” አለው።'),
  ('e7033b6c-080d-5c23-aa2e-e271838cb3e4', '7cb54daf-c36c-5b18-a23e-a62842cf98f7', '11249bb3-a65d-5cc6-adcf-fdd90923d550', 2, 3, 'እርሱም ሄዶ የዴብላይምን ልጅ ጎሜርን አገባ፤ እርስዋም ፀነሰች፤ ወንድ ልጅንም ወለደችለት።'),
  ('dcd0c8df-0c42-56d2-aab9-0edff6314d98', '7cb54daf-c36c-5b18-a23e-a62842cf98f7', '11249bb3-a65d-5cc6-adcf-fdd90923d550', 3, 4, 'እግዚአብሔርም፥ “ከጥቂት ዘመን በኋላ የኢይዝራኤልን ደም በይሁዳ ቤት ላይ እበቀላለሁና፥ ከእስራኤልም ቤት መንግሥትን እሽራለሁና ስሙን ኢይዝራኤል ብለህ ጥራው፤'),
  ('93ca9427-81ab-5f5f-ac03-95cf64556f6a', '7cb54daf-c36c-5b18-a23e-a62842cf98f7', '11249bb3-a65d-5cc6-adcf-fdd90923d550', 4, 5, 'በዚያም ጊዜ እንዲህ ይሆናል፤ በኢይዝራኤል ሸለቆ ውስጥ የእስራኤልን ቀስት እሰብራለሁ” አለው።'),
  ('edb5d3e2-053f-52cf-aff1-8c071f52008d', '7cb54daf-c36c-5b18-a23e-a62842cf98f7', '11249bb3-a65d-5cc6-adcf-fdd90923d550', 5, 6, 'ደግሞ ፀነሰች፤ ሴት ልጅንም ወለደች። እግዚአብሔርም፥ “መለየትን እለያቸዋለሁ እንጂ ይቅር እላቸው ዘንድ የእስራኤልን ቤት ከእንግዲህ ወዲህ አልምራቸውምና ስምዋን ኢሥህልት ብለህ ጥራት፤'),
  ('e56955ac-6247-5b3f-a0f0-08639e696710', '7cb54daf-c36c-5b18-a23e-a62842cf98f7', '11249bb3-a65d-5cc6-adcf-fdd90923d550', 6, 7, 'ነገር ግን የይሁዳን ልጆች ይቅር እላቸዋለሁ፤ እኔ አምላካቸውም እግዚአብሔር አድናቸዋለሁ እንጂ በቀስት ወይም በሰይፍ፥ ወይም በጦር፥ ወይም በሠረገላ፥ ወይም በፈረሶች፥ ወይም በፈረሰኞች የማድናቸው አይደለም” አለው።'),
  ('f626dadf-586a-54a7-ad8a-1c0f925d28b3', '7cb54daf-c36c-5b18-a23e-a62842cf98f7', '11249bb3-a65d-5cc6-adcf-fdd90923d550', 7, 8, 'ኢሥህልትንም ጡት ባስጣሏት ጊዜ፥ ደግሞ ፀነሰች፤ ወንድ ልጅንም ወለደች።'),
  ('598699aa-f31a-59bf-ac19-8e938c8c50d4', '7cb54daf-c36c-5b18-a23e-a62842cf98f7', '11249bb3-a65d-5cc6-adcf-fdd90923d550', 8, 9, 'እግዚአብሔርም፥ “ሕዝቤ አይደላችሁምና፥ እኔም አምላክ አልሆናችሁምና ስሙን ኢሕዝብየ ብለህ ጥራው” አለው።'),
  ('94aaeb89-8082-596c-a90c-85f2cbccd3e9', '7cb54daf-c36c-5b18-a23e-a62842cf98f7', '0d3c292e-02bd-5006-a3a6-b636da40d099', 1, 10, 'የእስራኤልም ልጆች ቍጥር እንደማይሰፈርና እንደማይቈጠር እንደ ባሕር አሸዋ ይሆናል፤ እንዲህም ይሆናል፤ “እናንተ ሕዝቤ አይደላችሁም” ተብሎ በተነገረበት በዚያ ስፍራ የሕያው አምላክ ልጆች ይባላሉ።'),
  ('cefd9ba0-72ab-5795-ada5-03833d26ae25', '7cb54daf-c36c-5b18-a23e-a62842cf98f7', '0d3c292e-02bd-5006-a3a6-b636da40d099', 2, 11, 'የይሁዳ ልጆችና የእስራኤል ልጆች በአንድነት ይሰበሰባሉ፤ ለእነርሱም አንድ አለቃ ይሾማሉ፤ ከምድሪቱም ይወጣሉ፤ የኢይዝራኤል ቀን ታላቅ ይሆናልና።'),
  ('7b761a35-8d5f-5828-a716-39b8c664ae0f', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', 'ff2b31c3-36c6-50ab-a7ec-8716a720ce48', 1, 1, 'ወንድማችሁን ሕዝቤ፥ እኅታችሁንም፦ ሥህልት በሉአቸው።'),
  ('44b82977-333e-5e43-a8f6-778430d2c46c', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', '40adfe34-8283-5ff9-a1a6-9ce1edf1d2e3', 1, 2, 'እናታችሁ ሚስቴ አይደለችምና፥ እኔም ባልዋ አይደለሁምና እናታችሁን ተዋቀሱአት። ዝሙቷን ከፊቷ፥ ምንዝርናዋንም ከጡቶችዋ መካከል አስወግዳለሁ።'),
  ('9bbd9308-56fb-54a8-a0e6-1a8c4354106c', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', '40adfe34-8283-5ff9-a1a6-9ce1edf1d2e3', 2, 3, 'ዕራቁትዋንም እንድትቆም አደርጋታለሁ፤ እንደ ሕፃንነትዋ ወራት፥ እንደ ተወለደችባት እንደ መጀመሪያዪቱም ቀን አደርጋታለሁ። እንደ ምድረ በዳም አደርጋታለሁ፤ ውኃም እንደሌላት ምድር አደርጋታለሁ፤ በውኃም ጥም እገድላታለሁ።'),
  ('0169e432-f950-556d-aa13-c8a4db673bbf', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', '40adfe34-8283-5ff9-a1a6-9ce1edf1d2e3', 3, 4, 'የዝሙት ልጆች ናቸውና ልጆችዋን ይቅር አልላቸውም።'),
  ('b3a6e756-5c6f-50eb-aa0f-21d33c8ea54d', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', '40adfe34-8283-5ff9-a1a6-9ce1edf1d2e3', 4, 5, 'እናታቸው አመንዝራለችና፤ የወለደቻቸውም፥ “እንጀራዬንና ውኃዬን፥ ቀሚሴንና መደረቢያዬን፥ ዘይቴንና የሚገባኝን ሁሉ የሚሰጡኝ ወዳጆችን እከተላቸው ዘንድ እሄዳለሁ” ብላለችና አሳፈረቻቸው።'),
  ('b73da85d-f783-5672-ab4f-9337509dfdf8', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', '40adfe34-8283-5ff9-a1a6-9ce1edf1d2e3', 5, 6, 'ስለዚህ እነሆ ጎዳናዋን በእሾህ አጥረዋለሁ፤ መንገድዋንም እዘጋዋለሁ፤ ማለፊያም ታጣለች።'),
  ('d7042ce8-9f8d-5ef7-affb-20a37671c18c', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', '40adfe34-8283-5ff9-a1a6-9ce1edf1d2e3', 6, 7, 'ወዳጆችዋንም ትከተላለች፤ ነገር ግን አትደርስባቸውም፤ ትፈልጋቸውማለች፤ ነገር ግን አታገኛቸውም፤ እርስዋም፥ “ከዛሬ ይልቅ የዚያን ጊዜ ይሻለኝ ነበርና ተመልሼ ወደ ቀደመው ባሌ እሄዳለሁ” ትላለች።'),
  ('95b389f8-dc21-5877-af49-dd58b053299d', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', '40adfe34-8283-5ff9-a1a6-9ce1edf1d2e3', 7, 8, 'እርስዋም እህልንና ወይንን ዘይትንም የሰጠኋት፥ ብርንና ወርቅን ያበዛሁላት እኔ እንደ ሆንሁ አላወቀችም። እርስዋ ግን ወርቁንና ብሩን ለጣዖት አደረገች።'),
  ('ac910e17-2155-5601-a577-f18743a248cb', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', '40adfe34-8283-5ff9-a1a6-9ce1edf1d2e3', 8, 9, 'ስለዚህ እህሌን በጊዜው፥ ወይኔንም በወራቱ እወስዳለሁ፤ ኀፍረቷንም እንዳትሸፍን ልብሴንና መጎናጸፊያዬን እገፍፋታለሁ።'),
  ('62b11a7a-706d-5abb-a6ec-2650b56a9db9', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', '40adfe34-8283-5ff9-a1a6-9ce1edf1d2e3', 9, 10, 'አሁንም በወዳጆችዋ ፊት ነውርዋን እገልጣለሁ፤ ከእጄም ማንም አያድናትም።'),
  ('b750fb76-c5bf-5d4e-aa4a-8a56b306828e', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', '40adfe34-8283-5ff9-a1a6-9ce1edf1d2e3', 10, 11, 'ደስታዋንም ሁሉ፥ በዓላቶችዋንም፥ መባቻዎችዋንም፥ ሰንበቶችዋንም፥ ሥርዐቶችዋንም ሁሉ አስቀራለሁ።'),
  ('88453e70-bfb0-5d60-a71d-61772b815764', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', '40adfe34-8283-5ff9-a1a6-9ce1edf1d2e3', 11, 12, 'እርስዋም፥ “ወዳጆች የሰጡኝ ዋጋዬ ይህ ነው” ያለችውን ሁሉ ወይንዋንና በለስዋን አጠፋለሁ፤ ምስክርም ይሆኑ ዘንድ አኖራቸዋለሁ፤ የምድረ በዳም አራዊትና የሰማይ ወፎች፥ የምድር ተንቀሳቃሾችም ይበሉታል።'),
  ('ad52c4df-0f25-52c7-a57f-6b1153d1a7a4', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', '40adfe34-8283-5ff9-a1a6-9ce1edf1d2e3', 12, 13, 'እኔን ረስታ ወዳጆችዋን እየተከተለች፥ በጕትቾችዋና በጌጥዋም እያጌጠች ለበኣሊም የሠዋችበትን ወራት እበቀልባታለሁ፥” ይላል እግዚአብሔር።'),
  ('d423de98-f9f8-595e-ae73-49dd8be03018', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', 'ba35d3e7-1e72-5876-ad2d-5786424daf26', 1, 14, 'ስለዚህ እነሆ አቅበዘብዛታለሁ፤ ወደ ምድረ በዳም አመጣታለሁ፤ ለልብዋም እናገራለሁ።'),
  ('ec7f3b10-9e79-54ad-aab7-a90accfb69f1', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', 'ba35d3e7-1e72-5876-ad2d-5786424daf26', 2, 15, 'ከዚያም የተገኘውን ገንዘብዋን እሰጣታለሁ፤ ምክርዋንም በአኮር ሸለቆ እገልጣለሁ፤ እንደ ሕፃንነትዋ ወራት፥ ከግብፅም እንደ ወጣችበት ቀን ትዘምራለች።'),
  ('30a23a65-2e5d-5232-adc3-24f9bceb6c46', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', 'ba35d3e7-1e72-5876-ad2d-5786424daf26', 3, 16, 'በዚያ ቀን ባሌ ብለሽ ትጠሪኛለሽ እንጂ ዳግመኛ በዓሊም ብለሽ አትጠሪኝም፥ ይላል እግዚአብሔር፤'),
  ('2a0b5be4-eac0-512a-aa7b-4a4658e5592d', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', 'ba35d3e7-1e72-5876-ad2d-5786424daf26', 4, 17, 'የበዓሊምን ስሞች ከአፍዋ አሰወግዳቸዋለሁና፥ ስማቸውም ከእንግዲህ ወዲህ አይታሰብም።'),
  ('62e8d70f-c6eb-55cf-a328-4047ed9c9549', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', 'ba35d3e7-1e72-5876-ad2d-5786424daf26', 5, 18, 'በዚያም ቀን ከምድር አራዊትና ከሰማይ ወፎች፥ ከመሬትም ተንቀሳቃሾች ጋር ቃል ኪዳን አደርግላቸዋለሁ። ቀስትንና ሰይፍን፥ ጦርንም ከምድሩ እሰብራለሁ፤ ተዘልለሽም ትቀመጫለሽ።'),
  ('2c4483aa-8555-5c51-acfa-470b534c5a8e', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', 'ba35d3e7-1e72-5876-ad2d-5786424daf26', 6, 19, 'ለዘለዓለምም ለእኔ እንድትሆኚ አጭሻለሁ፤ በጽድቅና በፍርድ በምሕረትና በይቅርታ አጭሻለሁ።'),
  ('5d76b663-4993-5a4e-a4f8-3cfbf5c6d904', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', 'ba35d3e7-1e72-5876-ad2d-5786424daf26', 7, 20, 'ለእኔም እንድትሆኚ በመታመን አጭሻለሁ፤ አንቺም እግዚአብሔርን ታውቂአለሽ።'),
  ('87a2e3e1-ba67-5190-a7db-0eec08935b70', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', 'ba35d3e7-1e72-5876-ad2d-5786424daf26', 8, 21, 'በዚያም ቀን እንዲህ ይሆናል፥ ይላል እግዚአብሔር፤ ለሰማይ እመልሳለሁ፤ ሰማይም ለምድር ይመልሳል፤'),
  ('11762086-d41c-5fa3-a9d7-d7c876775394', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', 'ba35d3e7-1e72-5876-ad2d-5786424daf26', 9, 22, 'ምድርም ለእህል፥ ለወይንና ለዘይት ትመልሳለች፤ እነርሱም ለኢይዝራኤል ይመልሳሉ።'),
  ('c21e393d-4222-5a32-a921-f60acc202c3b', '9fa2f831-012a-5859-a9e8-e4818b10c9a3', 'ba35d3e7-1e72-5876-ad2d-5786424daf26', 10, 23, 'በምድርም ላይ ለእኔ እዘራታለሁ፤ ይቅርታ የሌላትን ይቅር እላታለሁ፤ ያልተወደደች የነበረችውን እወድዳታለሁ፤ ሕዝቤም ያልሆነውን፥ “አንተ ሕዝቤ ነህ” እለዋለሁ፤ እርሱም፥ “አንተ ጌታዬና አምላኬ ነህ” ይለኛል።'),
  ('dfdd19d7-bc2a-55c0-af06-4b231a08ff6c', '504bfc0b-22a9-5168-ad82-032c1e3c8476', '4c54be8b-877e-5c13-a44e-f86210ffe142', 1, 1, 'እግዚአብሔርም፥ “የእስራኤል ልጆች ወደ ሌሎች አማልክት ቢመለሱና የዘቢብ ጥፍጥፍን ቢወድዱ እንኳን፥ እግዚአብሔር እንደሚወድዳቸው አንተም ክፋትና ዝሙት ያለባትን ሴት ውደድ” አለኝ።'),
  ('2ef99e10-fa78-53a1-a4a3-270786ed9526', '504bfc0b-22a9-5168-ad82-032c1e3c8476', '4c54be8b-877e-5c13-a44e-f86210ffe142', 2, 2, 'እኔም በዐሥራ አምስት ብርና በአንድ ቆሮስ መስፈሪያ ተኩል ገብስና በአንድ ፊቀን ወይን ተወዳጀኋት።'),
  ('da6e6ea4-517b-5a15-aea1-43fd56ee96b0', '504bfc0b-22a9-5168-ad82-032c1e3c8476', '4c54be8b-877e-5c13-a44e-f86210ffe142', 3, 3, '“ከእኔ ጋር ብዙ ወራት ተቀመጪ፤ አታመንዝሪም፤ ሌላ ሰውንም አታግቢ፤ እኔም ከአንቺ ጋር እኖራለሁ” አልኋት።'),
  ('4b73c321-a152-593e-a44a-cf698a656043', '504bfc0b-22a9-5168-ad82-032c1e3c8476', '4c54be8b-877e-5c13-a44e-f86210ffe142', 4, 4, 'የእስራኤል ልጆች ያለ ንጉሥና ያለ አለቃ፥ ያለ መሥዋዕትና ያለ ምሥዋዕ፤ ያለ ካህንና ያለ ራእይ፤ ያለ ኤፉድና ያለ ተራፊም ብዙ ወራት ይቀመጣሉና፤'),
  ('0549df96-218e-5be6-af8a-db43a8b66ce0', '504bfc0b-22a9-5168-ad82-032c1e3c8476', '4c54be8b-877e-5c13-a44e-f86210ffe142', 5, 5, 'ከዚያም በኋላ የእስራኤል ልጆች ተመልሰው አምላካቸውን እግዚአብሔርንና ንጉሣቸውን ዳዊትን ይፈልጋሉ፤ በኋለኛውም ዘመን እግዚአብሔርንና ቸርነቱን ያስቡታል።'),
  ('21bfcec4-cab0-586a-a18c-24206520c646', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 1, 1, 'እናንተ የእስራኤል ልጆች ሆይ! እውነትና ምሕረት፥ እግዚአብሔርንም ማወቅ በምድር ስለሌለ እግዚአብሔር በምድር ላይ የሚኖሩትን ይወቅሳልና የእግዚአብሔርን ቃል ስሙ።'),
  ('8dedfaf9-acb2-5702-a438-d9369ae8ad33', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 2, 2, 'ነገር ግን ሐሰት፥ ግዳይና ስርቆት፥ ምንዝርናም ምድርን ሞልተዋል፤ ደምንም ከደም ጋር ይቀላቅላሉ።'),
  ('775ebb97-0fa0-50da-a131-451a450ea4d8', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 3, 3, 'ስለዚህ ምድሪቱ ታለቅሳለች፤ በእርስዋም ከሚቀመጡ ሁሉ ከምድር አራዊትና ከሰማይ ወፎች፤ ከምድርም ተንቀሳቃሾች ጋር ትጠፋለች፤ የባሕሩም ዓሦች ያልቃሉ።'),
  ('2a75bc59-ca9b-52fc-a92a-f24957c73436', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 4, 4, 'ነገር ግን ሕዝቤ እንደሚከራከር ካህን ነውና እንግዲህ የሚከራከር፥ ማንም አይኑር፥ የሚዘልፍም ማንም አይኑር።'),
  ('6bb8b1f7-9f89-589b-aaa5-d1eb79672138', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 5, 5, 'በቀንም ትደክማለህ፤ ነቢዩም ከአንተ ጋር ይደክማል፤ እናታችሁም ሌሊትን ትመስላለች።'),
  ('c7f6653a-f7f9-57ef-a569-d97bf6beb01b', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 6, 6, 'ሕዝቤ አእምሮ እንደሌላቸው ይመስላሉ፤ አንተም አእምሮህ ተለይቶሃልና እኔ ካህን እንዳትሆነኝ እተውሃለሁ፤ የአምላክህንም ሕግ ረስተሃልና እኔ ደግሞ ልጆችህን እረሳለሁ።'),
  ('241802d7-c3a0-5978-a62e-dc9d32312033', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 7, 7, 'እንደ ብዛታቸው መጠን ኀጢአት ሠሩብኝ፤ እኔም ክብራቸውን ወደ ውርደት እለውጣለሁ።'),
  ('d5c2ce57-5feb-5ea5-ac52-76133508e7d1', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 8, 8, 'ሕዝቤንም ኀጢአታቸው ትበላቸዋለች፤ ሰውነታቸውንም በበደላቸው ይወስዷታል።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('8d619273-b08f-52de-a5a8-874b9a344cc6', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 9, 9, 'እንደ ሕዝቡም እንዲሁ ካህኑ ይሆናል፤ በመንገዳቸውም እበቀላቸዋለሁ፤ እንደ ሥራቸውም እከፍላቸዋለሁ።'),
  ('e3640510-94b2-50f8-a164-e2dc506fe3db', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 10, 10, 'እግዚአብሔርንም መጠበቅ ትተዋልና ሲበሉ አይጠግቡም፤ ሲያመነዝሩም አይበዙም።'),
  ('38c49b01-a3e4-5c2a-a825-2bf3be59ea7a', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 11, 11, 'የሕዝቤ ልቡናቸው ዝሙትን፥ መጠጥንና ስካርን ወደደ።'),
  ('245b6ebf-a8f0-556e-a0e4-d544d8b1ae1e', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 12, 12, 'ሕዝቤ በዝሙት መንፈስ ስተዋልና ከአምላካቸውም ርቀው አመንዝረዋልና በትርን ይጠይቃሉ፤ በትሩም ይመልስላቸዋል።'),
  ('9825fc77-b546-5437-a29a-fb48cba6ca4a', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 13, 13, 'በተራሮችም ራስና በኮረብታዎች ላይ ይሠዋሉ፤ ጥላውም መልካም ነውና ከኮምበልና ከልብን፥ ከአሆማም ዛፍ በታች ያርዳሉ፤ ስለዚህ ሴቶች ልጆቻችሁ ይሰስናሉ፤ ሙሽሮቻችሁም ያመነዝራሉ።'),
  ('3fb87733-8c64-5908-a71c-e3e8ca3289cd', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 14, 14, 'ወንዶችም ደግሞ ከአመንዝሮች ጋር ይጫወታሉና፥ ከጋለሞቶችም ጋር ይሠዋሉና ሴቶች ልጆቻችሁ በሰሰኑ ጊዜ፥ ሙሽሮቻችሁም በአመነዘሩ ጊዜ አልቀጣኋቸውም፤ የማያስተውልም ሕዝብ ከአመንዝራ ጋር ይቀላቀላል።'),
  ('853f249e-7dd8-554a-aad1-414e618b6041', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 15, 15, 'እስራኤል ሆይ! አንተ አላዋቂ አትሁን፤ አንተም ይሁዳ! ወደ ጌልጌላ አትሂድ፤ ወደ ቤትአዊንም አትውጡ፤ በሕያው እግዚአብሔርም አትማሉ።'),
  ('7af004f9-62f6-51c8-a487-8a249da475c5', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 16, 16, 'እስራኤል እንደምትደነብር ጊደር ደንብሮአል፤ እግዚአብሔርም በሰፊው ቦታ እንደ ጠቦት ያሰማራዋል።'),
  ('f9910664-9a9b-56cd-a3db-1fef930e2253', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 17, 17, 'እንዲሁም ኤፍሬም ከጣዖታት ጋር ተጋጠመ፤ ለራሱም ዕንቅፋትን አኖረ።'),
  ('0148e065-1fdd-5d78-a18c-7f7a81eea985', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 18, 18, 'ከነዓናውያንንም መረጣቸው፤ ፈጽመውም አመነዘሩ፤ በክፋታቸውም ውርደትን መረጡ።'),
  ('57593342-4c00-590e-acc3-e90a310617ab', 'a8d69f2d-d144-5e42-aa4f-1f0d63689ee3', 'c40dc55f-2cb5-5310-aa6b-042dfac5e10a', 19, 19, 'አንተ በክንፎችዋ ውስጥ የነፋስ መናወጥ ነህ፤ ከመሥዋዕታቸውም የተነሣ ያፍራሉ።'),
  ('8108d097-988e-5428-a29e-2d075b47bee3', '5ee077d6-fffd-5ddd-addc-c1ca0c6bc2e2', '5215ea76-d0c8-51c3-a65a-7a5d5e172dca', 1, 1, 'ካህናት ሆይ! ይህን ስሙ፤ የእስራኤል ቤት ሆይ! አድምጡ፤ የንጉሥ ቤት ሆይ! ልብ አድርጉ፤ ለሚመለከት ወጥመድ፥ በታቦርም ላይ የተዘረጋ አሽክላ ሆናችኋልና ፍርድ በእናንተ ላይ ነው።'),
  ('6ca261ba-cf2b-5774-ad4b-8313b9cedd4f', '5ee077d6-fffd-5ddd-addc-c1ca0c6bc2e2', '5215ea76-d0c8-51c3-a65a-7a5d5e172dca', 2, 2, 'የሚያድኑ አዳኞች ያጠምዱባት ዘንድ ተከሏት፤ እኔ ግን መካሪያችሁ ነኝ።'),
  ('1ea1f123-308b-54f2-a58d-7c5a99af84ec', '5ee077d6-fffd-5ddd-addc-c1ca0c6bc2e2', '5215ea76-d0c8-51c3-a65a-7a5d5e172dca', 3, 3, 'እኔ ኤፍሬምን አውቀዋለሁ፤ እስራኤልም ከእኔ አልራቀም፤ ኤፍሬም ዛሬ አመንዝሮአልና፤ እስራኤልም ረክሶአልና።'),
  ('d348e762-6535-5dfc-ac3c-092c754ed21c', '5ee077d6-fffd-5ddd-addc-c1ca0c6bc2e2', '5215ea76-d0c8-51c3-a65a-7a5d5e172dca', 4, 4, 'ወደ አምላካቸው ይመለሱ ዘንድ ልባቸውን አላቀኑም፤ የዝሙት መንፈስ በውስጣቸው አለና፤ እግዚአብሔርንም አላወቁትምና።'),
  ('935c5551-0196-5df2-a4c5-b7b2865cc34d', '5ee077d6-fffd-5ddd-addc-c1ca0c6bc2e2', '5215ea76-d0c8-51c3-a65a-7a5d5e172dca', 5, 5, 'የእስራኤልም ትዕቢት በፊቱ ይመሰክራል፤ ስለዚህ እስራኤልና ኤፍሬም በኀጢአታቸው ይደክማሉ፤ ይሁዳም ከእነርሱ ጋር ይደክማል።'),
  ('da9cdde8-a89b-552f-ac00-c224a58100cf', '5ee077d6-fffd-5ddd-addc-c1ca0c6bc2e2', '5215ea76-d0c8-51c3-a65a-7a5d5e172dca', 6, 6, 'እግዚአብሔርንም ለመሻት ከበጎቻቸውና ከላሞቻቸው ጋር ይሄዳሉ፤ ነገር ግን እርሱ ከእነርሱ ተለይቶአልና አያገኙትም።'),
  ('739c3700-afc8-5493-a989-c222108fbda0', '5ee077d6-fffd-5ddd-addc-c1ca0c6bc2e2', '5215ea76-d0c8-51c3-a65a-7a5d5e172dca', 7, 7, 'ዲቃሎችን ልጆች ወልደዋልና እግዚአብሔርን ከድተዋል፤ አሁንም ኵብኵባ እነርሱንና ርስታቸውን ይበላቸዋል።'),
  ('d245f1f7-ce00-5111-a38a-25491bede770', '5ee077d6-fffd-5ddd-addc-c1ca0c6bc2e2', '6287c5ca-1771-5452-a512-ba64d13786a9', 1, 8, 'በኮረብታ ላይ መለከትን ንፉ፤ በተራሮችም ላይ ጩኹ፤ ብንያም በተዋረደበት በቤትአዌን ዐዋጅ ንገሩ።'),
  ('4075f38b-3cda-5ad3-a4d2-24a2f470ebdb', '5ee077d6-fffd-5ddd-addc-c1ca0c6bc2e2', '6287c5ca-1771-5452-a512-ba64d13786a9', 2, 9, 'ኤፍሬም በዘለፋ ቀን ለጥፋት ይሆናል፤ በእስራኤልም ነገዶች የታመነውን ነገር አሳየሁ።'),
  ('508456aa-9227-52ee-a48d-4e0c77cce731', '5ee077d6-fffd-5ddd-addc-c1ca0c6bc2e2', '6287c5ca-1771-5452-a512-ba64d13786a9', 3, 10, 'የይሁዳ አለቆች ድምበርን እንደሚያፈርሱ ሆነዋል፤ እኔም መዓቴን እንደ ውኃ አፈስስባቸዋለሁ።'),
  ('ddf4858b-8659-524f-a96f-9a67199f7f07', '5ee077d6-fffd-5ddd-addc-c1ca0c6bc2e2', '6287c5ca-1771-5452-a512-ba64d13786a9', 4, 11, 'ኤፍሬም የተገፋ ሆነ፤ በፍርድም ተረገጠ፤ ከንቱን ይከተል ዘንድ ጀምሮአልና።'),
  ('124eaaa9-a28f-56e8-a4bc-ffa0cde98039', '5ee077d6-fffd-5ddd-addc-c1ca0c6bc2e2', '6287c5ca-1771-5452-a512-ba64d13786a9', 5, 12, 'እኔም ለኤፍሬም እንደ ብል፥ ለይሁዳም ቤት እንደ ነቀዝ እሆንበታለሁ።'),
  ('225b9e2b-e3fd-5bad-a0df-f2b2e8e6979b', '5ee077d6-fffd-5ddd-addc-c1ca0c6bc2e2', '6287c5ca-1771-5452-a512-ba64d13786a9', 6, 13, 'ኤፍሬምም ደዌውን አያት፤ ይሁዳም ሥቃዩን አያት፤ ኤፍሬም ወደ አሦር ሄደ፤ ወደ ንጉሡም ወደ ኢያሪም መልእክተኛን ላከ፤ እርሱ ግን ፈጽሞ ይፈውሳችሁ ዘንድ አልቻለም፤ ከእናንተም ሕማም አልተወገደም።'),
  ('105a8b5d-4545-5da6-afc5-2fed7960eeaf', '5ee077d6-fffd-5ddd-addc-c1ca0c6bc2e2', '6287c5ca-1771-5452-a512-ba64d13786a9', 7, 14, 'እኔም ለኤፍሬም እንደ ነብር፥ ለይሁዳም ቤት እንደ አንበሳ ደቦል እሆናለሁና፤ እኔም ነጥቄ እሄዳለሁ፤ እወስድማለሁ፤ የሚያድናቸውም የለም።'),
  ('4d059491-8e62-5f88-ac5a-3dd7274395d1', '5ee077d6-fffd-5ddd-addc-c1ca0c6bc2e2', '6287c5ca-1771-5452-a512-ba64d13786a9', 8, 15, 'እስኪጠፉ ድረስ፥ ፊቴንም እስኪሹ ድረስ እሄዳለሁ፤ ወደ ስፍራዬም እመለሳለሁ።'),
  ('db2d4d9b-a5da-5514-a439-437f1cea1a66', '5b34aca3-2ea9-513f-ad1b-b5cd596e3950', 'e66747c7-0851-52a8-a9ae-fea47e38bb99', 1, 1, 'በመከራቸው ጊዜ በማለዳ ወደ እኔ ይገሰግሳሉ፤ እንዲህም ይላሉ፥ “ኑ፤ ወደ አምላካችን ወደ እግዚአብሔር እንመለስ፤ እርሱ ሰብሮናልና፥ እርሱም ይፈውሰናል፤ እርሱ መትቶናልና፥ እርሱም ይጠግነናል።'),
  ('28d8faa3-8f15-536f-a573-b319139a0f49', '5b34aca3-2ea9-513f-ad1b-b5cd596e3950', 'e66747c7-0851-52a8-a9ae-fea47e38bb99', 2, 2, 'ከሁለት ቀን በኋላ ያድነናል፤ በሦስተኛውም ቀን ያስነሣናል፤ በፊቱም በሕይወት እንኖራለን።'),
  ('75c3409d-1bc3-50a4-aedd-10b9acda80b3', '5b34aca3-2ea9-513f-ad1b-b5cd596e3950', 'e66747c7-0851-52a8-a9ae-fea47e38bb99', 3, 3, 'እንወቀው፤ እናውቀውም ዘንድ እግዚአብሔርን እንከተል፤ እንደ ወገግታም ተዘጋጅቶ እናገኘዋለን፤ በምድርም ላይ እንደ መጀመሪያውና እንደ ኋለኛው ዝናብ ወደ እኛ ይመጣል።'),
  ('7c2261e0-9901-5357-a16d-aacdb0c9a0d5', '5b34aca3-2ea9-513f-ad1b-b5cd596e3950', 'e66747c7-0851-52a8-a9ae-fea47e38bb99', 4, 4, '“ምሕረታችሁ እንደ ማለዳ ደመና፥ በማለዳም እንደሚያልፍ ጠል ነውና ኤፍሬም ሆይ! ምን ላድርግልህ? ይሁዳ ሆይ! ምን ላድርግልህ?'),
  ('6e705928-197b-5915-af8c-3200853654c2', '5b34aca3-2ea9-513f-ad1b-b5cd596e3950', 'e66747c7-0851-52a8-a9ae-fea47e38bb99', 5, 5, 'ስለዚህ ነቢያቶቻችሁን አጨድኋቸው፤ በአፌም ቃል ገደልኋቸው፤ ፍርዴም እንደ ብርሃን ይወጣል።'),
  ('8f25c666-3d49-57d4-ac03-bc0f09081b3f', '5b34aca3-2ea9-513f-ad1b-b5cd596e3950', 'e66747c7-0851-52a8-a9ae-fea47e38bb99', 6, 6, 'ከመሥዋዕት ይልቅ ምሕረትን፥ ከሚቃጠልም መሥዋዕት ይልቅ እግዚአብሔርን ማወቅ እወድዳለሁና።'),
  ('833de4d8-8a3d-59b2-a448-bd5d69885906', '5b34aca3-2ea9-513f-ad1b-b5cd596e3950', 'e66747c7-0851-52a8-a9ae-fea47e38bb99', 7, 7, 'እነርሱ ግን ቃል ኪዳንን እንደሚያፈርስ ሰው ሆኑ፤ በዚያም ላይ ከዱኝ።'),
  ('ac0e0cbd-149d-55ce-a768-ccaa691323ff', '5b34aca3-2ea9-513f-ad1b-b5cd596e3950', 'e66747c7-0851-52a8-a9ae-fea47e38bb99', 8, 8, 'ገለዓድ ከንቱን የምትሠራና በደም የተቀባች ከተማ ናት፥'),
  ('5f4c2c61-6d15-58ab-aa2a-442276cc9d16', '5b34aca3-2ea9-513f-ad1b-b5cd596e3950', 'e66747c7-0851-52a8-a9ae-fea47e38bb99', 9, 9, 'ሰውን እንደሚያደቡ ወንበዴዎች፥ እንዲሁ ካህናት በሴኬም መንገድ ላይ አድብተው ይገድላሉ፤ ዐመፅንም ያደርጋሉ።'),
  ('99c8e2c2-4f3d-552a-a2f6-e9559abedae5', '5b34aca3-2ea9-513f-ad1b-b5cd596e3950', 'e66747c7-0851-52a8-a9ae-fea47e38bb99', 10, 10, 'በእስራኤል ቤት የሚያሰፈራን ነገር አይቻለሁ፤ በዚያ የኤፍሬምንም ዝሙት አየሁ፤ እስራኤልም ረክሶአል።'),
  ('3dba3d31-90ac-5f20-ab54-09cf6caecffd', '5b34aca3-2ea9-513f-ad1b-b5cd596e3950', 'e66747c7-0851-52a8-a9ae-fea47e38bb99', 11, 11, 'ይሁዳ ሆይ! የሕዝቤን ምርኮ በምመልስበት ጊዜ ለአንተ ደግሞ መከር ተወስኖልሃል።”'),
  ('22ba0736-1fc8-5186-a219-4e97533458a2', 'b37ff9e3-6667-562f-a4ec-8e3b8988f1d8', 'd38dfbaf-b5d5-5f1f-a21b-0ab1b537e39e', 1, 1, 'በሐሰት አድርገዋልና፥ ሌባም ገብቶአልና፥ በውጭም ወንበዴዎች ቀምተዋልና እስራኤልን እፈውስ ዘንድ በወደድሁ ጊዜ የኤፍሬም ኀጢአትና የሰማርያ ክፋት ተገለጠ።'),
  ('9d1b954b-1e49-5057-ac07-6186b0ddc061', 'b37ff9e3-6667-562f-a4ec-8e3b8988f1d8', 'd38dfbaf-b5d5-5f1f-a21b-0ab1b537e39e', 2, 2, 'ወንጀላቸውን አንድ ያደርጉ ዘንድ በልባቸው እንደ አሰቡ ክፋታቸውን ሁሉ ዐሰብሁ፤ አሁንም ክፋታቸው ከብባቸዋለች፤ በደላቸውም በፊቴ አለች።'),
  ('c913692b-4387-5194-afe6-025dbc85abf2', 'b37ff9e3-6667-562f-a4ec-8e3b8988f1d8', 'd38dfbaf-b5d5-5f1f-a21b-0ab1b537e39e', 3, 3, 'ነገሥታቱ በክፋታቸው፥ አለቆቹም በሐሰታቸው ደስ ተሰኙ።'),
  ('8707c49c-5fc7-5085-a475-4ed5d0f2afeb', 'b37ff9e3-6667-562f-a4ec-8e3b8988f1d8', 'd38dfbaf-b5d5-5f1f-a21b-0ab1b537e39e', 4, 4, 'ሁሉም አመንዝራዎች ናቸው፤ ጋጋሪ እንደሚያነድድበት እንደ ምድጃ ናቸው፤ ሁሉም እስኪቦካ ድረስ እሳትን መቈስቈስና እርሾን መለወስ ይቈያል።'),
  ('5dc82296-81f8-59ec-aba0-0a333437b2ed', 'b37ff9e3-6667-562f-a4ec-8e3b8988f1d8', 'd38dfbaf-b5d5-5f1f-a21b-0ab1b537e39e', 5, 5, 'በንጉሦቻችን ቀን አለቆች ከወይን ጠጅ ሙቀት የተነሣ ታመሙ፤ እነርሱም ከዋዘኞች ጋር እጆቻቸውን ዘረጉ።'),
  ('ad704553-f891-57cf-a65f-c89f6919b2cd', 'b37ff9e3-6667-562f-a4ec-8e3b8988f1d8', 'd38dfbaf-b5d5-5f1f-a21b-0ab1b537e39e', 6, 6, 'እያደቡ ልባቸውን እንደ ምድጃ አዘጋጅተዋል፤ ጋጋሪያቸውም ሌሊቱን ሁሉ አንቀላፋ፤ በጠባም ጊዜ እንደ እሳት ነበልባል ይነድዳል።'),
  ('eda7c372-e028-5be9-a43c-a5759da23563', 'b37ff9e3-6667-562f-a4ec-8e3b8988f1d8', 'd38dfbaf-b5d5-5f1f-a21b-0ab1b537e39e', 7, 7, 'ሁሉም እንደ ምድጃ ግለዋል፤ ፈራጆቻቸውንም በሉ፤ ነገሥታቶቻቸውም ሁሉ ወደቁ፤ ከእነርሱም መካከል የሚጠራኝ የለም።'),
  ('aebbe506-642f-5412-a171-d4278bd3aef8', 'b37ff9e3-6667-562f-a4ec-8e3b8988f1d8', 'd38dfbaf-b5d5-5f1f-a21b-0ab1b537e39e', 8, 8, 'ኤፍሬም ከሕዝቡ ጋር ተደባለቀ፤ ኤፍሬም እንዳልተገላበጠ ቂጣ ነው።'),
  ('80e1d635-fa2a-5075-ac4f-30349fb17103', 'b37ff9e3-6667-562f-a4ec-8e3b8988f1d8', 'd38dfbaf-b5d5-5f1f-a21b-0ab1b537e39e', 9, 9, 'ጠላት ጕልበቱን በላው፤ እርሱ ግን አላወቀም፤ ሽበትም ወጣበት፤ እርሱም ገና አላስተዋለም።'),
  ('2c8812ae-c171-5406-a72a-4b81abc1b0b4', 'b37ff9e3-6667-562f-a4ec-8e3b8988f1d8', 'd38dfbaf-b5d5-5f1f-a21b-0ab1b537e39e', 10, 10, 'የእስራኤልም ውርደቱና ስድቡ በፊቱ ነው፤ ወደ አምላካቸው ወደ እግዚአብሔር ግን አልተመለሱም፤ በዚህም ሁሉ እግዚአብሔርን አልፈለጉትም።'),
  ('b6e5d431-8fce-5b88-ad19-f5aa2eac2ea7', 'b37ff9e3-6667-562f-a4ec-8e3b8988f1d8', 'd38dfbaf-b5d5-5f1f-a21b-0ab1b537e39e', 11, 11, 'ኤፍሬምም ልብ እንደሌላት እንደ ሰነፍ ርግብ ነው፤ ግብፅን ጠሩ፤ ወደ አሦርም ሄዱ።'),
  ('42dd9742-b56d-5d50-a90a-9abb3c6da0ff', 'b37ff9e3-6667-562f-a4ec-8e3b8988f1d8', 'd38dfbaf-b5d5-5f1f-a21b-0ab1b537e39e', 12, 12, 'ሲሄዱም አሽክላዬን እዘረጋባቸዋለሁ፤ እንደ ሰማይ ወፎችም አወርዳቸዋለሁ፤ መከራቸውን ሲሰሙ እገሥጻቸዋለሁ።'),
  ('f00f801c-e0bf-5517-a87a-b4522aceb612', 'b37ff9e3-6667-562f-a4ec-8e3b8988f1d8', 'd38dfbaf-b5d5-5f1f-a21b-0ab1b537e39e', 13, 13, 'ከእኔ ፈቀቅ ብለዋልና ወዮላቸው! እኔንም ስለ በደሉ ደንግጠዋል! እኔ ታደግኋቸው፤ እነርሱ ግን በሐሰት ተናገሩብኝ።'),
  ('7d80e884-7ee7-5882-a28c-ef02997f2bb2', 'b37ff9e3-6667-562f-a4ec-8e3b8988f1d8', 'd38dfbaf-b5d5-5f1f-a21b-0ab1b537e39e', 14, 14, 'በመኝታቸው ላይ ሆነው ያለቅሱ ነበር እንጂ በልባቸው ወደ እኔ አልጮኹም፤ ስለ እህልና ስለ ወይን ይገዳደሉ ነበር፤'),
  ('f839a60a-71a6-51b1-a629-46ac2b7887ca', 'b37ff9e3-6667-562f-a4ec-8e3b8988f1d8', 'd38dfbaf-b5d5-5f1f-a21b-0ab1b537e39e', 15, 15, 'በእኔም ዘንድ ተገሠጹ፤ እኔም ክንዳቸውን አጸናሁ፤ እነርሱ ግን ክፉ ነገርን መከሩብኝ።'),
  ('c9b4f0a8-06af-57f4-ae57-b157c0794050', 'b37ff9e3-6667-562f-a4ec-8e3b8988f1d8', 'd38dfbaf-b5d5-5f1f-a21b-0ab1b537e39e', 16, 16, 'ወደ ከንቱ ነገር ተመለሱ፤ እንደ ጠማማ ቀስትም ሆኑ፤ አለቆቻቸውም ከምላሳቸው ስንፍና የተነሣ በሰይፍ ይወድቃሉ፤ ይህም በግብፅ ምድር ውስጥ መሳለቂያ ይሆንባቸዋል።'),
  ('86fc3c26-1cda-5875-aa58-b886a0b0792c', '20f1318b-3aa7-53ea-a653-b1900c1d8490', 'f43207c1-8b11-5f67-a51e-1ba812408d2e', 1, 1, 'በብብታቸው እንደ መሬት፤ በእግዚአብሔርም ቤት እንደ ንስር ይመጣል። ቃል ኪዳኔን ተላልፈዋልና፥ በሕጌም ላይ ዐምፀዋልና።'),
  ('e24c2ff4-6e9b-552c-a5cf-3428b9c10e28', '20f1318b-3aa7-53ea-a653-b1900c1d8490', 'f43207c1-8b11-5f67-a51e-1ba812408d2e', 2, 2, 'አምላክ ሆይ! እኛ እስራኤል ዐወቅንህ ብለው ወደ እኔ ይጮኻሉ።'),
  ('778a086f-f409-5597-a522-6563c5969880', '20f1318b-3aa7-53ea-a653-b1900c1d8490', 'f43207c1-8b11-5f67-a51e-1ba812408d2e', 3, 3, 'እስራኤል ደግነቱን ጥሎአልና፤ ጠላትም ያሳድደዋልና።'),
  ('a7f8b44d-943a-534c-a600-b7e48e6f8398', '20f1318b-3aa7-53ea-a653-b1900c1d8490', 'f43207c1-8b11-5f67-a51e-1ba812408d2e', 4, 4, 'ራሳቸውን አነገሡ፤ ከእኔም ዘንድ አይደለም፤ አለቆችንም አደረጉ፤ እኔም አላወቅሁም፤ ለጥፋታቸውም ከብራቸውና ከወርቃቸው ጣዖታትን ለራሳቸው አደረጉ።'),
  ('d6ac88cd-b7a3-5659-ad52-c5749bc1812c', '20f1318b-3aa7-53ea-a653-b1900c1d8490', 'f43207c1-8b11-5f67-a51e-1ba812408d2e', 5, 5, 'ሰማርያ ሆይ! እምቦሳሽን መልሺ፤ ቍጣዬም በላያቸው ነድዶአል፤ እስከ መቼም ድረስ ንጹሕ ሊሆኑ አይችሉም።'),
  ('ee703d5e-52fa-51af-aab6-51aa444bdd99', '20f1318b-3aa7-53ea-a653-b1900c1d8490', 'f43207c1-8b11-5f67-a51e-1ba812408d2e', 6, 6, 'ይህ ደግሞ በእስራኤል ዘንድ ነው፤ ሠራተኛ ሠራው፤ እርሱም አምላክ አይደለም፤ ሰማርያ ሆይ! እንቦሳሽ ተቅበዝብዞአልና።'),
  ('9173b9d6-0cdd-57e8-afde-df3ab1f993b7', '20f1318b-3aa7-53ea-a653-b1900c1d8490', 'f43207c1-8b11-5f67-a51e-1ba812408d2e', 7, 7, 'ነፋስን ዘርተዋልና ዐውሎ ነፋስን አጨዱ፤ ለነዶአቸውም ኀይል የለውም፤ ከፍሬውም ዱቄት አይገኝም፤ ቢገኝም ጠላት ይበላዋል።'),
  ('9e826be0-809a-5423-a7ce-c37069243031', '20f1318b-3aa7-53ea-a653-b1900c1d8490', 'f43207c1-8b11-5f67-a51e-1ba812408d2e', 8, 8, 'እስራኤል ተውጦአል፤ በአሕዛብም መካከል ዛሬ እንደ ግትቻ ዕቃ ሆኖአል።'),
  ('ffc2c470-d4d8-58b5-a0a6-87e1e23d03d4', '20f1318b-3aa7-53ea-a653-b1900c1d8490', 'f43207c1-8b11-5f67-a51e-1ba812408d2e', 9, 9, 'ለብቻውም እንደሚቀመጥ እንደ ምድረ በዳ አህያ ወደ አሦር ወጥተዋል፤ ኤፍሬምም እንደ ገና ለመለመ፤ እጅ መንሻንም ወደደ።'),
  ('c8c930f2-4ddd-528b-ae80-19d85a6f8e3b', '20f1318b-3aa7-53ea-a653-b1900c1d8490', 'f43207c1-8b11-5f67-a51e-1ba812408d2e', 10, 10, 'ስለዚህ ለአሕዛብ አልፈው ይሰጣሉ፤ እኔም አሁን እቀበላቸዋለሁ፤ ንጉሥንና አለቆችንም ይቀቡ ዘንድ ፈጽመው ያንሣሉ።'),
  ('8d70cd0e-7bac-5626-a267-87a70c28934d', '20f1318b-3aa7-53ea-a653-b1900c1d8490', 'f43207c1-8b11-5f67-a51e-1ba812408d2e', 11, 11, 'ኤፍሬም መሠዊያን አብዝቶአልና የወደደው መሠዊያ ለኀጢአት ሆነበት።'),
  ('f50c9648-6355-5840-ad6d-f07b43a45a8b', '20f1318b-3aa7-53ea-a653-b1900c1d8490', 'f43207c1-8b11-5f67-a51e-1ba812408d2e', 12, 12, 'ብዙ ሕጎችን እጽፍለታለሁ፤ ነገር ግን ሥርዐቱና የተወደደው መሠዊያው እንደ እንግዳ ነገር ተቈጠሩ።'),
  ('5b0e15ba-4e16-59e5-ae10-cb7ee79ea5a2', '20f1318b-3aa7-53ea-a653-b1900c1d8490', 'f43207c1-8b11-5f67-a51e-1ba812408d2e', 13, 13, 'መሥዋዕትንም ቢሠዉ፥ ሥጋንም ቢበሉ፤ እግዚአብሔር አይቀበላቸውም፤ አሁንም በደላቸውን ያስባል፤ በኀጢአታቸውም ይበቀላቸዋል፤ እነርሱም ወደ ግብፅ ይመለሳሉ፤ በአሦርም ርኩስ ነገርን ይበላሉ።'),
  ('f3381733-ef9f-5519-ab42-5c172de63df5', '20f1318b-3aa7-53ea-a653-b1900c1d8490', 'f43207c1-8b11-5f67-a51e-1ba812408d2e', 14, 14, 'እስራኤል ፈጣሪውን ረስቶአል፤ መስገጃዎችንም ሠርቶአል፤ ይሁዳም የተመሸጉትን ከተሞች አብዝቶአል፤ እኔ ግን በከተሞች ላይ እሳትን እሰድዳለሁ፤ መሠረቶቻቸውንም ትበላለች።'),
  ('8089f373-3218-5caa-a947-561ab3152b97', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 1, 1, 'እስራኤል ሆይ! ከአምላክህ ርቀህ አመንዝረሃልና እንደ አሕዛብ ደስ አይበልህ፤ ሐሴትንም አታድርግ፤ ከእህሉና ከወይኑ አውድማ ሁሉ ይልቅ የግልሙትና ዋጋን ወድደሃል።'),
  ('7ab1ef39-8363-5fc5-a319-cf5bc3a2f17f', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 2, 2, 'የእህሉ አውድማና የወይኑ መጭመቂያ አላወቃቸውም፤ ወይኑም ጐደለባቸው።'),
  ('7b1f1e08-f891-59d7-a654-498749609683', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 3, 3, 'በእግዚአብሔር ምድር ላይ አይቀመጡም፤ ኤፍሬምም በግብፅ ይቀመጣል፤ በአሦርም ርኩስ ነገርን ይበላሉ።'),
  ('c0c80028-228b-5b12-a861-be250eb7ffda', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 4, 4, 'ለእግዚአብሔርም የወይን ጠጅን ቍርባን አያቀርቡም፤ መሥዋዕታቸውም ደስ አያሰኘውም፤ እንደ ኀዘንም እንጀራ ይሆንባቸዋል፤ የሚበላውም ሁሉ ይረክሳል፤ እንጀራቸውም ለሰውነታቸው ይሆናል እንጂ ወደ እግዚአብሔር ቤት አይገባም።'),
  ('2fa74369-8d78-59fc-ad1a-e866d732b6f5', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 5, 5, 'በዓመት በዓል ቀንና በእግዚአብሔር በዓል ቀን ምን ታደርጋላችሁ?'),
  ('e7b318db-f212-5d28-adef-acbd4e56eff0', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 6, 6, 'ስለዚህ እነሆ ከግብፅ ጕስቍልና የተነሣ ሸሽተው ይሄዳሉ፤ ሜምፎስም ትቀበላቸዋለች፤ በማከማስም ይቀብሩአቸዋል፤ ጥፋትም ወርቃቸውን ይወርሳል፥ እሾህም በድንኳኖቻቸው ውስጥ ይበቅላል።'),
  ('ce12f609-700d-5858-ae0c-5f6b351479fe', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 7, 7, 'የበቀል ወራት መጥቶአል፤ የፍዳም ወራት ደርሶአል፤ እስራኤልም እንደ አበደ ነቢይና ርኩስ መንፈስ እንደ አለበት ሰው ይታመማል፤ ከኀጢአትህና ከጠላትነትህ ብዛት የተነሣም ቍጣህን አበዛህ።'),
  ('610981f7-3695-523b-a291-b15037031094', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 8, 8, 'ኤፍሬም ከእግዚአብሔር ጋር ጉበኛ ነበረ፤ አሁን ግን ነቢዩ በመንገዱ ሁሉ ላይ ክፉ ወጥመድ ሆነ፤ በእግዚአብሔርም ቤት ርኵሰትን አደረጉ።'),
  ('fcfa464a-4106-510a-a0d6-f281f7181337', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 9, 9, 'በጊብዓ ዘመን እንደ ነበረ እጅግ ረከሱ፤ እርሱም በደላቸውን ያስባል፤ ኀጢአታቸውንም ይበቀላል።'),
  ('999a8dd0-5bb7-5d28-ac1a-2a5ec36f4173', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 10, 10, 'እስራኤልን በምድረ በዳ እንደ አለ ወይን ሆኖ አገኘሁት፤ አባቶቻችሁንም በመጀመሪያዋ ዓመት እንደ በለስ በኵራት ሆነው አየኋቸው፤ እነርሱ ግን ወደ ብዔልፌጎር መጡ፤ ለነውርም ተለዩ፤ እንደ ወደዱትም ርኩስ ሆኑ።'),
  ('3459322a-9276-51d1-a62e-c901b721936f', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 11, 11, 'ኤፍሬምም እንደ ወፍ በረረ፤ ክብራቸው ከመፅነስና ከመውለድ፥ ከማማጥም ነበር።'),
  ('338b60b6-0b30-5bc8-aa54-722b57ff001e', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 12, 12, 'ልጆቻቸውንም ቢያሳድጉ ከሰው ለይች ልጅ አልባ አደርጋቸዋለሁ፤ ሥጋዬ ከእነርሱ ነውና ወዮላቸው!'),
  ('5e1414a1-0804-5796-af74-43ce4d5f2f53', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 13, 13, 'እኔ እንደ አየሁ የኤፍሬም ልጆች ለወጥመድ ተሰጥተዋል፤ ኤፍሬምም ልጆቹን ወደ ገዳዮች አወጣ።'),
  ('41dbe701-e9c6-5a7b-a28e-02d095c92da8', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 14, 14, 'አቤቱ! ስጣቸው፤ ምን ትሰጣቸዋለህ? መካን ማኅፀንን፥ የደረቁትንም ጡቶች ስጣቸው።'),
  ('d371144f-cc78-55b4-abda-5f42464a47f6', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 15, 15, 'ክፋታቸውም ሁሉ በጌልገላ አለ፤ በዚያ ጠልቻቸዋለሁ፤ ስለ ሠሩት ክፋት ከቤቴ አሳድዳቸዋለሁ፤ ከእንግዲህ ወዲያ አልወድዳቸውም፤ አለቆቻቸው ሁሉ ዐመፀኞች ናቸውና።'),
  ('d48ac03c-5ef9-5570-a2e9-94be5177e29c', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 16, 16, 'ኤፍሬም ታመመ፤ ሥሩም ደረቀ፤ ከእንግዲህም ወዲህ ፍሬ አያፈራም፤ ደግሞም ቢወልዱ የተወደደውን የማኅፀናቸውን ፍሬ እገድላለሁ።'),
  ('0f3830b0-f77d-523d-ab8c-00a39a498fc5', '170a9304-e2e5-5648-a9bd-2efde8b552a7', 'c0062587-5539-5310-a888-3292ac0303ce', 17, 17, 'አልሰሙትምና እግዚአብሔር ይጥላቸዋል፤ በአሕዛብም መካከል ተቅበዝባዦች ይሆናሉ።'),
  ('aedccefd-d387-599f-a5f4-a1f2dade5c93', '9ecf6f22-f887-5aaf-a68a-8ff4f356c3c6', '4b125e5c-8f19-5fc7-a984-f4f586d5672a', 1, 1, 'እስራኤል ፍሬው የበዛለት የለመለመ ወይን ነው፤ እንደ ፍሬው ብዛት መሠዊያዉን አብዝቶአል፤ እንደ ምድሩም ማማር መጠን ሐውልቶችን ሠርተዋል።'),
  ('7a80f8ee-3837-5319-af5a-01744205a382', '9ecf6f22-f887-5aaf-a68a-8ff4f356c3c6', '4b125e5c-8f19-5fc7-a984-f4f586d5672a', 2, 2, 'ልባቸው ተከፈለ፤ አሁንም ይጠፋሉ፤ እርሱ መሠዊያቸውን ያፈርሳል፤ ሐውልቶቻቸውንም ያጠፋል።'),
  ('4990f8ee-75a2-5588-a934-036a6065f406', '9ecf6f22-f887-5aaf-a68a-8ff4f356c3c6', '4b125e5c-8f19-5fc7-a984-f4f586d5672a', 3, 3, 'አሁንም፥ “ንጉሥ የለንም፤ እግዚአብሔርን አልፈራንምና፤ ንጉሥስ ምን ያደርግልናል?” ይላሉ።'),
  ('85a7f4b2-41a6-5c8e-a914-39158efcc89a', '9ecf6f22-f887-5aaf-a68a-8ff4f356c3c6', '4b125e5c-8f19-5fc7-a984-f4f586d5672a', 4, 4, 'የማይረባውን የሐሰት ቃል ይናገራሉ፤ ቃል ኪዳንም ያደርጋሉ፤ ስለዚህ መርዛም ሣር በእርሻ ትልም ላይ እንደሚበቅል ፍርድ ይበቅልባቸዋል።'),
  ('25550422-f1d8-585e-a543-292c61e5a281', '9ecf6f22-f887-5aaf-a68a-8ff4f356c3c6', '4b125e5c-8f19-5fc7-a984-f4f586d5672a', 5, 5, 'የሰማርያ ሰዎች በቤትአዌን እንቦሳ አጠገብ ይኖራሉ፤ ሕዝቡ ያለቅሱለታል፤ ክብሩም ከእርሱ ዘንድ ወጥቶአልና እንዳዘኑበት እንዲሁ በክብሩ ደስ ይላቸዋል።'),
  ('d2997460-5735-5b33-a3c1-4f105358002e', '9ecf6f22-f887-5aaf-a68a-8ff4f356c3c6', '4b125e5c-8f19-5fc7-a984-f4f586d5672a', 6, 6, 'ለንጉሡ ለኢያሪም እጅ መንሻ ይሆን ዘንድ አስረው ወደ አሦር ይወስዱታል፤ ኤፍሬምን እፍረት ይይዘዋል፤ እስራኤልም በምክሩ ያፍራል።'),
  ('dd71fd9b-acf0-533b-aef3-0a4b20fb09ab', '9ecf6f22-f887-5aaf-a68a-8ff4f356c3c6', '4b125e5c-8f19-5fc7-a984-f4f586d5672a', 7, 7, 'ሰማርያ ንጉሥዋን እንደ ጥራጊ በውኃ ላይ ጣለችው።'),
  ('88c56e1c-6de0-5cf2-afcb-5afbebefa29b', '9ecf6f22-f887-5aaf-a68a-8ff4f356c3c6', '4b125e5c-8f19-5fc7-a984-f4f586d5672a', 8, 8, 'የእስራኤል ኀጢአት የሆኑት የአዎን የኮረብታው መስገጃዎች ይፈርሳሉ፤ እሾህና አሜከላም በመሠዊያዎቻቸው ላይ ይበቅላሉ፤ ተራሮችንም፥ “ክደኑን፤ ኮረብቶችንም፦ ውደቁብን” ይሉአቸዋል።'),
  ('ffd6c105-3d7b-5c2d-a2c1-fbc2c7b95427', '9ecf6f22-f887-5aaf-a68a-8ff4f356c3c6', '4b125e5c-8f19-5fc7-a984-f4f586d5672a', 9, 9, 'እስራኤል ከጊብዓ ዘመን ጀምሮ ኀጢአትን ሠርቶአል፤ በዚያም ጸንተዋል፤ በጊብዓ ላይ ጦር አይደርስባቸውምን? መጥቶም የዐመፅ ልጆችን ገሠጻቸው፤'),
  ('ca012a6d-1bab-5295-a65e-7728054d9a89', '9ecf6f22-f887-5aaf-a68a-8ff4f356c3c6', '4b125e5c-8f19-5fc7-a984-f4f586d5672a', 10, 10, 'ስለ ሁለቱም ኀጢአቶቻቸው በገሠጻቸው ጊዜ አሕዛብ በላያቸው ይሰበሰቡባቸዋል።'),
  ('61b933d3-9fba-575f-a9bf-8ca5abc1a76b', '9ecf6f22-f887-5aaf-a68a-8ff4f356c3c6', '4b125e5c-8f19-5fc7-a984-f4f586d5672a', 11, 11, 'ኤፍሬምም ቀንበርን እንደ ለመደች ጊደር ነው፤ እኔ ግን በአንገቱ ውበት እጫንበታለሁ፤ በኤፍሬም ላይ እጠምድበታለሁ፤ ይሁዳንም እለጕመዋለሁ፤ ያዕቆብም ለራሱ መንግሥትን ያስተካክላል።'),
  ('9d81a47f-6520-5e1e-ad2d-f7f79b52b63f', '9ecf6f22-f887-5aaf-a68a-8ff4f356c3c6', '4b125e5c-8f19-5fc7-a984-f4f586d5672a', 12, 12, 'ለእናንተ ጽድቅን ዝሩ፤ የሕይወት ፍሬን ሰብስቡ፤ የጥበብንም ብርሃን ለራሳችሁ አብሩ፤ የጽድቃችሁ መከር እስኪደርስ እግዚአብሔርን ፈልጉት።'),
  ('bc82b2c3-7f7b-568d-a635-0936ce19feba', '9ecf6f22-f887-5aaf-a68a-8ff4f356c3c6', '4b125e5c-8f19-5fc7-a984-f4f586d5672a', 13, 13, 'ዐመፅን ለምን ተከላችሁ? ኀጢአትንስ ለምን አጨዳችሁ፤ የሐሰትንም ፍሬ በልታችኋል፤ በሠረገሎችህና በሠራዊትህ ብዛት ታምነሃል።'),
  ('c37aeb03-98d5-5671-a2e5-141c9bf90f74', '9ecf6f22-f887-5aaf-a68a-8ff4f356c3c6', '4b125e5c-8f19-5fc7-a984-f4f586d5672a', 14, 14, 'በሕዝብህም መካከል ጥፋት ይነሣል፤ እናትም በልጆችዋ ላይ በተጣለች ጊዜ የሰልማን አለቃ ቤትአርብኤልን በጦርነት ቀን እንዳፈረሰ፥ አምባዎችህ ሁሉ ይፈርሳሉ።'),
  ('ff7edd94-261c-5fcc-ab3b-5a7e5b707de3', '9ecf6f22-f887-5aaf-a68a-8ff4f356c3c6', '4b125e5c-8f19-5fc7-a984-f4f586d5672a', 15, 15, 'የእስራኤል ቤት ሆይ! ከኀጢአታችሁ ክፋት የተነሣ እንዲሁ አደርግባችኋለሁ፤ በነጋም ጊዜ የእስራኤልን ንጉሥ ይጥሉታል።'),
  ('280986a4-6959-5f84-ab8a-8918d1e447c7', 'cf08c620-efc8-523c-ab5b-16a5799ba34b', '387c04d2-9067-5c8a-a5d9-fa8620ae36f8', 1, 1, 'እስራኤል ሕፃን በነበረ ጊዜ ወደድሁት፤ ልጄንም ከግብፅ ጠራሁት፤'),
  ('fa57cb5a-4de6-5d71-a145-c70ef23460ea', 'cf08c620-efc8-523c-ab5b-16a5799ba34b', '387c04d2-9067-5c8a-a5d9-fa8620ae36f8', 2, 2, 'አብዝች ብጠራቸው አጥብቀው ከፊቴ ራቁ፤ ለበዓሊምም ይሠዉ ነበር፤ ለተቀረጹ ምስሎችም ያጥኑ ነበር።'),
  ('c488b65a-93e7-5a8a-aa66-6bffbf214d89', 'cf08c620-efc8-523c-ab5b-16a5799ba34b', '387c04d2-9067-5c8a-a5d9-fa8620ae36f8', 3, 3, 'እኔም ኤፍሬምን ወደድሁት፤ በክንዴም ተቀበልሁት፤ እኔም እፈውሳቸው እንደ ነበርሁ አላወቁም።'),
  ('62adb354-ec89-55bf-a09e-1df4e374513e', 'cf08c620-efc8-523c-ab5b-16a5799ba34b', '387c04d2-9067-5c8a-a5d9-fa8620ae36f8', 4, 4, 'በሰው ገመድ በፍቅርም እስራት ሳብኋቸው፤ ለእነርሱም ፊቱን በጥፊ እንደሚመቱት ሰው ሆንሁላቸው፤ ወደ እርሱም እመለከታለሁ፤ እችለውማለሁ።'),
  ('7a8485a9-93f6-507d-ae8a-30a2166e668f', 'cf08c620-efc8-523c-ab5b-16a5799ba34b', '387c04d2-9067-5c8a-a5d9-fa8620ae36f8', 5, 5, 'ኤፍሬም በግብፅ ተቀመጠ፤ አሦርም ንጉሡ ነው፤ መመለስን እንቢ ብሎአልና።'),
  ('05ffad5c-e6e5-537f-a70e-cae849484545', 'cf08c620-efc8-523c-ab5b-16a5799ba34b', '387c04d2-9067-5c8a-a5d9-fa8620ae36f8', 6, 6, 'ጦር በከተማው ደከመች፤ ከእጁም ይለያታል፤ ከሥራቸውም ፍሬ ይበላሉ።'),
  ('35a1a011-97a0-5c54-ad96-4d892f2cddea', 'cf08c620-efc8-523c-ab5b-16a5799ba34b', '387c04d2-9067-5c8a-a5d9-fa8620ae36f8', 7, 7, 'ሕዝቤም ከመኖሪያው ተነሥቶአል፤ እግዚአብሔርም በክብሩ ላይ ተቈጣ፤ ከፍ ከፍም አያደርገውም።'),
  ('4b219d1d-a138-5031-a93d-c3bf827a7b04', 'cf08c620-efc8-523c-ab5b-16a5799ba34b', '387c04d2-9067-5c8a-a5d9-fa8620ae36f8', 8, 8, 'እኔም “አምልኮቴን ትተሃል አልሁ፤ ኤፍሬም ሆይ! እንዴት አደርግሃለሁ? እስራኤል ሆይ! እንዴትስ እደግፍሃለሁ? እንዴትስ አደርግሃለሁ? እንደ አዳማ ነውን? ወይስ እንደ ሲባዮ? ልቤ በውስጤ ተናውጣለች፤ ምሕረቴም ተገልጣለች።'),
  ('df9cbf87-147b-5ccd-a881-7f8b750b4aa8', 'cf08c620-efc8-523c-ab5b-16a5799ba34b', '387c04d2-9067-5c8a-a5d9-fa8620ae36f8', 9, 9, 'እኔ አምላክ ነኝ እንጂ ሰው አይደለሁምና፥ በመካካልህም ቅዱሱ ነኝና እንግዲህ የቍጣዬን መቅሠፍት አላደርግም፤ ኤፍሬምንም ያጠፉት ዘንድ አልተውም፤ ወደ ከተማም አልገባም አልሁ።'),
  ('170b268f-a269-50ed-a254-30c4eb78f021', 'cf08c620-efc8-523c-ab5b-16a5799ba34b', '387c04d2-9067-5c8a-a5d9-fa8620ae36f8', 10, 10, 'ጌታ እግዚአብሔርን እከተለው ዘንድ እሄዳለሁ፤ እርሱ ያድነናልና፤ እርሱም እንደ አንበሳ ያገሣል፤ የውኃ ልጆችም ይደነግጣሉ።'),
  ('d69a1ca5-308e-539e-a462-a0c55ccef6e9', 'cf08c620-efc8-523c-ab5b-16a5799ba34b', '387c04d2-9067-5c8a-a5d9-fa8620ae36f8', 11, 11, 'እንደ ወፍ ከግብፅ፥ እንደ ርግብም ከአሶር ምድር እየተንቀጠቀጡ ይወጣሉ፤ ወደ ቤታቸውም እመልሳቸዋለሁ፥” ይላል እግዚአብሔር።'),
  ('c95cd146-f62c-5060-a165-8845a16844bc', '96dee2ef-0214-5220-ac9b-f71806954b0f', '60ee9590-4f95-59a0-afde-a7c0a43f31c7', 1, 1, 'ኤፍሬም በሐሰት፥ የእስራኤል ቤትና ይሁዳም በተንኰል ከበቡኝ፤ አሁንም እግዚአብሔር ዐወቃቸው፤ ለእግዚአብሔርም ቅዱስ ሕዝብ ተባሉ።'),
  ('c6b4ca77-452d-506c-ad4e-a137a58f4253', '96dee2ef-0214-5220-ac9b-f71806954b0f', '60ee9590-4f95-59a0-afde-a7c0a43f31c7', 2, 2, 'ኤፍሬም ግን ክብርንና ከንቱ ነገርን የሚያሳድድ ክፉ ጋኔን ነው። ሁልጊዜም ሐሰትንና ተንኰልን ያበዛል፤ ከአሦርም ጋር ቃል ኪዳን ያደርጋል፤ ምሕረትም ያደርጉለት ዘንድ ወደ ግብፅ ዘይትን ይልካል።'),
  ('45fea452-7d70-5850-abaa-8c1102189abd', '96dee2ef-0214-5220-ac9b-f71806954b0f', '60ee9590-4f95-59a0-afde-a7c0a43f31c7', 3, 3, 'እግዚአብሔርም ደግሞ ከይሁዳ ጋር ይዋቀሳል፤ ያዕቆብንም እንደ መንገዱ ይበቀለዋል፤ እንደ ሥራውም ይከፍለዋል።'),
  ('df0f265b-116c-5138-afc4-bea0a1ae69e7', '96dee2ef-0214-5220-ac9b-f71806954b0f', '60ee9590-4f95-59a0-afde-a7c0a43f31c7', 4, 4, 'በማኅፀን ውስጥ ወንድሙን በተረከዙ ያዘው፤ በደካማነቱም ጊዜ ከአምላክ ጋር ታገለ።'),
  ('98c7bbd0-e286-5aa8-a7e0-58c9a5c3bdfb', '96dee2ef-0214-5220-ac9b-f71806954b0f', '60ee9590-4f95-59a0-afde-a7c0a43f31c7', 5, 5, 'ከመልአኩም ጋር ታግሎ አሸነፈ፤ አልቅሶም ለመነኝ። በቤትአዎንም አገኘኝ፤ በዚያም ከእኔ ጋር ተነጋገረ።'),
  ('7dea99e6-8d41-5002-a7a6-154fff702acb', '96dee2ef-0214-5220-ac9b-f71806954b0f', '60ee9590-4f95-59a0-afde-a7c0a43f31c7', 6, 6, 'ሁሉን የሚገዛ እግዚአብሔር መታሰቢያው ነው።'),
  ('ff55ffd2-85e0-5581-a3a2-f4708a0ef5d7', '96dee2ef-0214-5220-ac9b-f71806954b0f', '60ee9590-4f95-59a0-afde-a7c0a43f31c7', 7, 7, 'ስለዚህ ወደ አምላክህ ተመለስ፤ ምሕረትንና ፍርድን ጠብቅ፤ ዘወትርም ወደ አምላክህ ቅረብ።'),
  ('dabc0b9b-e0a8-5ba4-a511-459b3f18570b', '96dee2ef-0214-5220-ac9b-f71806954b0f', '60ee9590-4f95-59a0-afde-a7c0a43f31c7', 8, 8, 'በከነዓን እጅ የዐመፅ ሚዛን አለ፤ ቅሚያንም ይወድዳል።'),
  ('6784fb6a-7dc0-5a31-afdc-bb9fdf600ec7', '96dee2ef-0214-5220-ac9b-f71806954b0f', '60ee9590-4f95-59a0-afde-a7c0a43f31c7', 9, 9, 'ኤፍሬምም፥ “ባለጸጋ ሆኜአለሁ፤ ሀብትንም አግኝቻለሁ፤ በድካሜም ሁሉ ኀጢአት የሚሆን በደል አይገኝብኝም” አለ።'),
  ('bf518c59-2c07-5571-a187-b2c2372bfcce', '96dee2ef-0214-5220-ac9b-f71806954b0f', '60ee9590-4f95-59a0-afde-a7c0a43f31c7', 10, 10, 'እኔም ከግብፅ ምድር ያወጣሁህ አምላክህ እግዚአብሔር ነኝ፤ እንደ ዓመት በዓል ቀንም እንደ ገና በድንኳን አስቀምጥሃለሁ።'),
  ('2332637b-b4d6-5edd-a04a-3b6bd44a1fe3', '96dee2ef-0214-5220-ac9b-f71806954b0f', '60ee9590-4f95-59a0-afde-a7c0a43f31c7', 11, 11, 'ለነቢያትም ተናግሬአለሁ፤ ራእይንም አብዝቻለሁ፤ በነቢያትም እጅ ተመስያለሁ።'),
  ('22db012f-01c5-5249-a623-d035618f4511', '96dee2ef-0214-5220-ac9b-f71806954b0f', '60ee9590-4f95-59a0-afde-a7c0a43f31c7', 12, 12, 'በገለዓድ ባይሆንም እንኳ በጌልጌላ መሥዋዕታቸውን የሚሠዉ አለቆች ስተዋል፤ መሠዊያዎቻቸውም በእርሻ ትልም ላይ እንደ አለ የድንጋይ ክምር ነው።'),
  ('ca26692b-787c-5153-afae-7a2dd9013b34', '96dee2ef-0214-5220-ac9b-f71806954b0f', '60ee9590-4f95-59a0-afde-a7c0a43f31c7', 13, 13, 'ያዕቆብ ወደ ሶርያ ሀገር ሸሸ፤ እስራኤልም ስለ ሚስት አገለገለ፤ ስለ ሚስትም ጠበቀ።'),
  ('980c3eb4-fc59-54ae-ad07-a8c62f0fbd78', '96dee2ef-0214-5220-ac9b-f71806954b0f', '60ee9590-4f95-59a0-afde-a7c0a43f31c7', 14, 14, 'እግዚአብሔርም በነቢይ እስራኤልን ከግብፅ ምድር አወጣው፤ በነቢይም ጠበቀው።'),
  ('10e328fa-918b-5b46-a501-cec8bf99cc0e', '96dee2ef-0214-5220-ac9b-f71806954b0f', '60ee9590-4f95-59a0-afde-a7c0a43f31c7', 15, 15, 'ኤፍሬም ተመረረ፤ ተቈጣም፤ ደሙም በላዩ ላይ ይፈስሳል፤ እግዚአብሔርም ስድቡን በራሱ ላይ ይመልሳል።'),
  ('ba913f19-a02c-5e49-afea-a37cf771a0c7', 'd9090867-1d2f-50b6-a3c2-11447880f5f5', '362a8419-046b-5cff-ac67-1b8ebbb64743', 1, 1, 'ኤፍሬም እንደ ተናገረ በእስራኤል ሥርዐቱን ወሰደ፤ ለበዓልም አደረገው፤ ሞተም።'),
  ('0ef596a4-8724-5968-abe3-2317102a3b63', 'd9090867-1d2f-50b6-a3c2-11447880f5f5', '362a8419-046b-5cff-ac67-1b8ebbb64743', 2, 2, 'ዳግመኛም በደሉ፤ ጠራቢ በሚሠራው አምሳል ከወርቃቸውና ከብራቸው ጣዖትን ሠሩ፤ እንዲህም አሉ “ሰውን ሠዉ፤ ላሙ ግን አልቋል።”'),
  ('c12f15bd-741c-5efa-aba5-10af705f8a9d', 'd9090867-1d2f-50b6-a3c2-11447880f5f5', '362a8419-046b-5cff-ac67-1b8ebbb64743', 3, 3, 'ስለዚህም እንደ ማለዳ ደመና፥ በጥዋት እንደሚያልፍ ጠል፥ በዐውሎ ነፋስም ከዐውድማ እንደሚበተን እብቅ፥ ከምድጃም እንደሚወጣ ጢስ ይሆናሉ።'),
  ('9dcd4969-386d-5ff4-a7ff-a7dd74853842', 'd9090867-1d2f-50b6-a3c2-11447880f5f5', '362a8419-046b-5cff-ac67-1b8ebbb64743', 4, 4, 'ሰማይን ያጸናሁ፥ ምድርንም የፈጠርሁ፥ እጆችም የሰማይ ሠራዊትን ያቆሙ አምላክህ እግዚአብሔር እኔ ነኝ። እንዳትከተላቸውም እነርሱን አላሳየሁህም። ከግብፅ ምድርም ያወጣሁህ እኔ ነኝ። ከእኔ በቀር ሌላ አምላክ አትወቅ፤ ከእኔ በቀር የሚያድንህ የለምና።'),
  ('7616645c-2488-5970-ad79-93d0fd5a0163', 'd9090867-1d2f-50b6-a3c2-11447880f5f5', '362a8419-046b-5cff-ac67-1b8ebbb64743', 5, 5, 'በምድረ በዳና በዞርህበት ምድር ሁሉ ጠበቅሁህ።'),
  ('263cdea0-5f02-5a82-a6cb-c9e989b16b3d', 'd9090867-1d2f-50b6-a3c2-11447880f5f5', '362a8419-046b-5cff-ac67-1b8ebbb64743', 6, 6, 'ከተሰማራችሁ በኋላ ጠገባችሁ፤ በጠገባችሁም ጊዜ ልባችሁ ታበየ፤ ስለዚህም ረሳችሁኝ።'),
  ('eaeff883-eae8-5164-a648-16b9366c1d40', 'd9090867-1d2f-50b6-a3c2-11447880f5f5', '362a8419-046b-5cff-ac67-1b8ebbb64743', 7, 7, 'ስለዚህም ለይሁዳ ቤት እንደ አንበሳ፥ ለኤፍሬምም እንደ ነብር ሆንሁባቸው።'),
  ('6aace2cd-c770-5e7f-a652-673f0c696273', 'd9090867-1d2f-50b6-a3c2-11447880f5f5', '362a8419-046b-5cff-ac67-1b8ebbb64743', 8, 8, 'በአሦራውያንም መንገድ አጠገብ እንደ ተራበ ድብ እገጥማቸዋለሁ፤ የልባቸውንም ሥር እቈርጣለሁ፤ በዚያም የዱር አንበሶች ይበሏቸዋል፤ የምድረ በዳም አራዊት ይነጣጠቋቸዋል።'),
  ('d897e4e7-52a2-5092-a144-40b851ccb7c2', 'd9090867-1d2f-50b6-a3c2-11447880f5f5', '362a8419-046b-5cff-ac67-1b8ebbb64743', 9, 9, 'እስራኤል ሆይ! በመከራህ ጊዜ ማን ይረዳሃል?'),
  ('a6244e8c-eeab-5c8d-aebd-bc227d954fe6', 'd9090867-1d2f-50b6-a3c2-11447880f5f5', '362a8419-046b-5cff-ac67-1b8ebbb64743', 10, 10, 'ንጉሥህ ወዴት አለ? በየከተማህ ሁሉ እስኪ ያድንህ! ንጉሥና አለቃ ስጠኝ የምትለኝ እስኪ እነርሱ ይበቀሉልህ?'),
  ('c96b633e-200b-5bf5-a0a8-b9eef3434112', 'd9090867-1d2f-50b6-a3c2-11447880f5f5', '362a8419-046b-5cff-ac67-1b8ebbb64743', 11, 11, 'በቍጣዬ ንጉሥን ሰጠሁህ፤ በመዓቴም ሻርሁት።'),
  ('217e9c32-7692-5c43-a1be-36a7000c3666', 'd9090867-1d2f-50b6-a3c2-11447880f5f5', '362a8419-046b-5cff-ac67-1b8ebbb64743', 12, 12, 'የዐመፅህን ወንጀል ታገሥሁት፤ የኤፍሬም ኀጢአቱም ተከማችትዋል ።'),
  ('8a7e75aa-9f19-556e-a7c4-425c1b8d97ed', 'd9090867-1d2f-50b6-a3c2-11447880f5f5', '362a8419-046b-5cff-ac67-1b8ebbb64743', 13, 13, 'ምጥ እንደ ያዛት ሴት ጭንቅ ይይዘዋል፤ ይህ ልጅ ሰነፍ ነው፤ አዋቂም አይደለም፤ በልጆችም ተግሣጽ አይጸናም።'),
  ('f7b01cdb-ae76-5e76-aded-d15554f6585f', 'd9090867-1d2f-50b6-a3c2-11447880f5f5', '362a8419-046b-5cff-ac67-1b8ebbb64743', 14, 14, 'ከሲኦል እጅ እታደጋቸዋለሁ፤ ከሞትም እቤዣቸዋለሁ፤ ሞት ሆይ! መውጊያህ ወዴት አለ? ሲኦል ሆይ! ድል መንሣትህ ወዴት አለ? ደስታህ ከዐይኖችህ ተሰወረች።'),
  ('8b24c364-e6e3-5f25-a083-41fedd8c3dfc', 'd9090867-1d2f-50b6-a3c2-11447880f5f5', '362a8419-046b-5cff-ac67-1b8ebbb64743', 15, 15, 'ከወንድሞቹ መካከል ይለያል፤ እግዚአብሔርም ከምድረ በዳ የሚያቃጥል ነፋስን ያመጣል፤ ሥሩን ያደርቃል፤ ምንጩንም ያነጥፋል፤ ምድርን ያደርቃል፤ የተወደዱ ዕቃዎችንም ሁሉ ያጠፋል።'),
  ('23b63a58-44bc-5f57-ae2b-5c002b7d4f14', '2cefd0f6-4601-5c07-a8a4-7a234d079c2b', '4080e926-cffb-5d6a-a3d5-a216b885055a', 1, 1, 'ሰማርያ በአምላክዋ ላይ ዐምፃለችና ፈጽማ ትጠፋለች፤ በሰይፍም ይወድቃሉ፤ ሕፃኖቻቸውንም ይጥሉአቸዋል፤ እርጉዞቻቸውንም ይሰነጥቋቸዋል።'),
  ('faf90173-3e4c-509d-a4b8-8e9baed314a0', '2cefd0f6-4601-5c07-a8a4-7a234d079c2b', '4080e926-cffb-5d6a-a3d5-a216b885055a', 2, 2, 'እስራኤል ሆይ! በኀጢአትህ ወድቀሃልና ወደ አምላክህ ወደ እግዚአብሔር ተመለስ።'),
  ('d3dc3fe3-6fc6-5217-a87d-fd4daaf3505b', '2cefd0f6-4601-5c07-a8a4-7a234d079c2b', '4080e926-cffb-5d6a-a3d5-a216b885055a', 3, 3, 'ከእናንተ ጋር ቃልን ውሰዱ፤ ወደ እግዚአብሔርም ተመለሱ። እንዲህም በሉት፥ “ኀጢአትን ሁሉ አስወግድ፤ በቸርነትም ተቀበለን፤ በወይፈንም ፈንታ የከንፈራችንን ፍሬ ለአንተ እንሰጣለን።'),
  ('5efd4ed4-81f2-5aff-a5ef-22eb75383a37', '2cefd0f6-4601-5c07-a8a4-7a234d079c2b', '4080e926-cffb-5d6a-a3d5-a216b885055a', 4, 4, 'አሦር አያድነንም፤ በፈረስም ላይ አንቀመጥም፤ ድሃአደጉም በአንተ ዘንድ ይቅርታን ያገኛልና ከእንግዲህ ወዲህ የእጆቻችንን ሥራ አምላኮቻችን ናችሁ አንላቸውም።”'),
  ('f45e080e-2368-59a0-a628-ec04162ed1c3', '2cefd0f6-4601-5c07-a8a4-7a234d079c2b', '4080e926-cffb-5d6a-a3d5-a216b885055a', 5, 5, 'ቍጣዬ ከእርሱ ዘንድ ተመልሶአልና ሀገራቸውን አድናለሁ፤ በእውነትም እወድዳቸዋለሁ።'),
  ('9adcb64c-ef4a-5493-a08f-2514b3046936', '2cefd0f6-4601-5c07-a8a4-7a234d079c2b', '4080e926-cffb-5d6a-a3d5-a216b885055a', 6, 6, 'ለእስራኤልም እንደ ጠል እሆነዋለሁ፤ እንደ አበባም ያብባል፥ እንደ ሊባኖስም ሥሩን ይሰድዳል።'),
  ('c937bd4e-b503-5f6f-a0c9-585c43328d59', '2cefd0f6-4601-5c07-a8a4-7a234d079c2b', '4080e926-cffb-5d6a-a3d5-a216b885055a', 7, 7, 'ቅርንጫፎቹም ይዘረጋሉ፤ ውበቱም እንደ ወይራ፥ ሽታውም እንደ ሊባኖስ ይሆናል።'),
  ('f62925f1-3889-5508-a8b4-84feea9d3af3', '2cefd0f6-4601-5c07-a8a4-7a234d079c2b', '4080e926-cffb-5d6a-a3d5-a216b885055a', 8, 8, 'ተመልሰውም ከጥላው ሥር ይቀመጣሉ፤ በሕይወትም ይኖራሉ፤ ከእህሉም የተነሣ ይጠግባሉ፤ እንደ ወይንም አረግ ያብባሉ ፤ መታሰቢያውም እንደ ሊባኖስ ወይን ይሆናል።'),
  ('c6d0eac7-9bc2-5cd1-a53f-b551c933d56b', '2cefd0f6-4601-5c07-a8a4-7a234d079c2b', '4080e926-cffb-5d6a-a3d5-a216b885055a', 9, 9, 'ከእንግዲህ ወዲያ ጣዖት ለኤፍሬም ምንድን ነው? እኔ አደከምሁት፤ አጸናሁትም፤ እኔ እንደ ተወደደ አበባ አፈራዋለሁ፤ ፍሬህም በእኔ ዘንድ ይገኛል።'),
  ('2fba701a-6be4-5aee-a4a9-6335e3ce3a46', '2cefd0f6-4601-5c07-a8a4-7a234d079c2b', '4080e926-cffb-5d6a-a3d5-a216b885055a', 10, 10, 'ይህን ነገር የሚያስተውል ጠቢብ፤ የሚያውቃትም አስተዋይ ማን ነው? የእግዚአብሔር መንገዶች ቀናዎች ናቸው፥ ጻድቃንም ይሄዱባቸዋል፤ ኃጥአን ግን ይወድቁባቸዋል።'),
  ('7cd9d245-eb07-5b9b-a59b-ec1d3bab91c2', '41f666de-3d31-5ae4-a0b0-e89ad69243e1', '5344953b-d590-5dfa-ae9c-1da86ce20c1f', 1, 1, 'በቴቁሔ በላም ጠባቂዎች መካከል የነበረ አሞጽ በይሁዳ ንጉሥ በዖዝያን ዘመን፥ በእስራኤልም ንጉሥ በዮአስ ልጅ በኢዮርብዓም ዘመን፥ የምድር መናወጥ ከሆነበት ከሁለት ዓመት በፊት ስለ ኢየሩሳሌም ያየው ቃል ይህ ነው።'),
  ('b6c54ce0-6bd0-5741-abfa-cfd0968fe8d4', '41f666de-3d31-5ae4-a0b0-e89ad69243e1', '5344953b-d590-5dfa-ae9c-1da86ce20c1f', 2, 2, 'እንዲህም አለ፥ “እግዚአብሔር ከጽዮን ሆኖ ድምፁን ከፍ አድርጎ ይናገራል፤ ከኢየሩሳሌምም ሆኖ ቃሉን ይሰጣል፤ የእረኞችም ማሰማሪያዎች ያለቅሳሉ፤ የቀርሜሎስም ራስ ይደርቃል።”'),
  ('f8db55a2-09bc-51ef-ae0a-99571bd23a02', '41f666de-3d31-5ae4-a0b0-e89ad69243e1', '09d60039-e78b-56d3-a712-fab67e3a1933', 1, 3, 'እግዚአብሔር እንዲህ ይላል፥ “የገለዓድን ነፍሰ ጡሮች በብረት መጋዝ ሰንጥቀዋቸዋልና ስለ ሦስት ወይም ስለ አራት የደማስቆ ኀጢአት መቅሠፍቴን ከማድረግ አልመለስላቸውም።'),
  ('1e58301e-b53b-5524-a17a-227b6cb8f4b2', '41f666de-3d31-5ae4-a0b0-e89ad69243e1', '09d60039-e78b-56d3-a712-fab67e3a1933', 2, 4, 'በአዛሄል ቤት ላይ እሳትን እሰድዳለሁ፤ የወልደ አዴርንም መሠረቶች ትበላለች።'),
  ('4b062237-b47a-5f64-ae50-d2769cec11ed', '41f666de-3d31-5ae4-a0b0-e89ad69243e1', '09d60039-e78b-56d3-a712-fab67e3a1933', 3, 5, 'የደማስቆንም ቍልፎች እሰብራለሁ፤ በአዎን ሸለቆ የሚኖሩትንም ሰዎች አጠፋለሁ፤ የካራን ሰዎች ወገኖችንም እቈራርጣለሁ፤ የሶርያ ሕዝብም ወደ ቂር ይማረካሉ፤” ይላል እግዚአብሔር።'),
  ('687fc220-f02f-5e23-ae5c-803a81fa0355', '41f666de-3d31-5ae4-a0b0-e89ad69243e1', '8da41512-93f0-5f8a-ae2b-eef652f21171', 1, 6, 'እግዚአብሔር እንዲህ ይላል፥ “በኤዶምያስ ይዘጉባቸው ዘንድ የሰሎሞንን ምርኮ ማርከዋልና ስለ ሦስት ወይም ስለ አራት የጋዛ ኀጢአት መቅሠፍቴን ከማድረግ አልመለስላቸውም።'),
  ('ec1c9aff-3311-5185-a04d-34db58b9eab6', '41f666de-3d31-5ae4-a0b0-e89ad69243e1', '8da41512-93f0-5f8a-ae2b-eef652f21171', 2, 7, 'በጋዛ ቅጥር ላይ እሳትን እሰድዳለሁ፤ መሠረቶችዋንም ትበላለች።'),
  ('3f4a8082-3f51-597f-abc2-0ecb1ef9b92d', '41f666de-3d31-5ae4-a0b0-e89ad69243e1', '8da41512-93f0-5f8a-ae2b-eef652f21171', 3, 8, 'የአዛጦን ነዋሪዎችን አጠፋለሁ፤ የአስቀሎናም ሕዝብ ይጠፋለሁ፤ እጄንም በአቃሮን ላይ እመልሳለሁ፤ ከፍልስጥኤማውያን የቀሩትም ይጠፋሉ” ይላል ጌታ እግዚአብሔር።'),
  ('dc986dae-2db1-579f-a1f0-0b1c9540b6e1', '41f666de-3d31-5ae4-a0b0-e89ad69243e1', 'b4c2368c-5de5-53fb-ac27-03e8b1c30b75', 1, 9, 'እግዚአብሔር እንዲህ ይላል፥ “የሰሎሞን ምርኮኞችን በኤዶምያስ ዘግተዋልና፥ የወንድሞችንም ቃል ኪዳን አላሰቡምና ስለ ሦስት ወይም ስለ አራት የጢሮስ ኀጢአት አልመለስላቸውም።'),
  ('6c939b86-ab22-55be-a5f2-ed622474a6fb', '41f666de-3d31-5ae4-a0b0-e89ad69243e1', 'b4c2368c-5de5-53fb-ac27-03e8b1c30b75', 2, 10, 'በጢሮስ ቅጥር ላይ እሳትን አሰድዳለሁ፤ መሠረቶችዋንም ትበላለች።”'),
  ('0aca85fa-6bb4-5310-a2e5-a0f72dfe53dc', '41f666de-3d31-5ae4-a0b0-e89ad69243e1', 'c1e3693a-f116-5824-a7ae-d7b1151dfbeb', 1, 11, 'እግዚአብሔር እንዲህ ይላል፦“ወንድሙን በሰይፍ አሳድዶታልና፥ በምድር ላይም ማኅፀንን አርክሶአልና፥ የሚዘልፈውንና የሚያስደነግጠውን በርብሮአልና፥ መዓቱንም ለዘለዓለም ጠብቆአልና ስለ ሦስት ወይም ስለ አራት የኤዶምያስ ኀጢአት መቅሠፍቴን ከማድረግ አልመለስላቸውም።'),
  ('cd571e72-5711-51e3-ae19-16853d21ba2e', '41f666de-3d31-5ae4-a0b0-e89ad69243e1', 'c1e3693a-f116-5824-a7ae-d7b1151dfbeb', 2, 12, 'በቴማን ላይ እሳትን እሰድዳለሁ፤ የቅጥርዋንም መሠረቶች ትበላለች።”'),
  ('614ab8cc-1d0b-580b-a7c5-83ae55d957cb', '41f666de-3d31-5ae4-a0b0-e89ad69243e1', '5904f555-ca23-5e40-acb4-678d4ea975a3', 1, 13, 'እግዚአብሔር እንዲህ ይላል፥ “ዳርቻቸውን ያሰፉ ዘንድ የገለዓድን ነፍሰ ጡሮች ቀድደዋልና ስለ ሦስት ወይም ስለ አራት የአሞን ልጆች ኀጢአት መቅሠፍቴን ከማድረግ አልመለስም።'),
  ('31593ef6-7b84-5ec7-a3a0-9baa0340091e', '41f666de-3d31-5ae4-a0b0-e89ad69243e1', '5904f555-ca23-5e40-acb4-678d4ea975a3', 2, 14, 'በራባ ቅጥር ላይ እሳትን አነድዳለሁ፤ በጦርነት ቀን በጩኸት መሠረቶችዋን ትበላለች፤ በፍጻሜዋም ቀን ትናወጣለች።'),
  ('a67e5ed1-0325-532e-af48-e8293cb6ba40', '41f666de-3d31-5ae4-a0b0-e89ad69243e1', '5904f555-ca23-5e40-acb4-678d4ea975a3', 3, 15, 'ንጉሦቻቸውን፥ አለቆቻቸውንና ካህኖቻቸውን በአንድነት ይማርኳቸዋል፥” ይላል እግዚአብሔር።'),
  ('b3fb8ca0-5932-5c29-a938-2ae754f5546e', '3bb7032b-553e-5563-a1f7-f189c76b581e', '615df430-38d8-56e2-a342-085947a99b53', 1, 1, 'እግዚአብሔር እንዲህ ይላል፥ “የኤዶምያስን ንጉሥ አጥንት አመድ እስኪሆን ድረስ አቃጥሎታልና ስለ ሦስት ወይም ስለ አራት የሞዓብ ኀጢአት መቅሠፍቴን ከማድረግ አልመለስላቸውም።'),
  ('7927ae11-3186-5f96-a0b1-d1c1f0c9b484', '3bb7032b-553e-5563-a1f7-f189c76b581e', '615df430-38d8-56e2-a342-085947a99b53', 2, 2, 'በሞዓብ ላይ እሳትን እሰድዳለሁ፤ የከተሞችዋንም መሠረቶች ትበላለች፤ ሞዓብም በድካምና በውካታ፥ በመለከትም ድምፅ ይሞታል፤'),
  ('302663a6-1af3-510e-ae9f-e07d3f906e75', '3bb7032b-553e-5563-a1f7-f189c76b581e', '615df430-38d8-56e2-a342-085947a99b53', 3, 3, 'ፈራጅንም ከመካከልዋ አጠፋለሁ፤ ከእርሱም ጋር አለቆችዋን ሁሉ እገድላለሁ” ይላል እግዚአብሔር።'),
  ('4c3a1c48-4740-59c4-a683-f94089dc982d', '3bb7032b-553e-5563-a1f7-f189c76b581e', '1bcab8ca-8f05-52d9-a7c0-a80ad60d6a54', 1, 4, 'እግዚአብሔር እንዲህ ይላል፥ “የእግዚአብሔርን ሕግ አፍርሰዋልና፥ ትእዛዙንም አልጠበቁምና፥ አባቶቻቸውም የተከተሉት ከንቱ ነገር አስቶአቸዋልና ስለ ሦስት ወይም ስለ አራት የይሁዳ ኀጢአት መቅሠፍቴን ከማድረግ አልመለስላቸውም።'),
  ('7c120844-e519-5000-a86d-d67048523a52', '3bb7032b-553e-5563-a1f7-f189c76b581e', '1bcab8ca-8f05-52d9-a7c0-a80ad60d6a54', 2, 5, 'በይሁዳ ላይ እሳትን እሰድዳለሁ፤ የኢየሩሳሌምንም መሠረቶች ትበላለች።”'),
  ('13d3418f-d133-501a-ab2e-f5bc4b410d5e', '3bb7032b-553e-5563-a1f7-f189c76b581e', '62637eab-f53a-57e5-a31f-151c7a4633ea', 1, 6, 'እግዚአብሔር እንዲህ ይላል፥ “ጻድቁን በብር፥ ችጋረኛውንም ምድርን በሚረግጡበት አንድ ጥንድ ጫማ ሸጠውታልና ስለ ሦስት ወይም ስለ አራት የእስራኤል ኀጢአት መቅሠፍቴን ከማድረግ አልመለስላቸውም።'),
  ('34ef81cf-d941-55f0-a9a5-24e4b0f70880', '3bb7032b-553e-5563-a1f7-f189c76b581e', '62637eab-f53a-57e5-a31f-151c7a4633ea', 2, 7, 'የድሆችን ራስ ይቀጠቅጣሉ፤ የትሑታንንም ፍርድ ያጣምማሉ፤ የአምላካቸውንም ስም ያረክሱ ዘንድ አባትና ልጁ ወደ አንዲት ሴት ይገባሉ፤'),
  ('aca30946-c7d5-56d7-ad15-38d3c211727a', '3bb7032b-553e-5563-a1f7-f189c76b581e', '62637eab-f53a-57e5-a31f-151c7a4633ea', 3, 8, 'ልብሳቸውንም አስረው ለመሥዊያው መጋረጃ ያደርጋሉ፤ በአምላካቸውም ቤት የቅሚያ ወይን ጠጅ ይጠጣሉ።'),
  ('a68cd152-876a-57e4-a092-80f88b2f9c08', '3bb7032b-553e-5563-a1f7-f189c76b581e', '62637eab-f53a-57e5-a31f-151c7a4633ea', 4, 9, 'እኔ ግን ቁመቱ እንደ ዝግባ ቁመት፥ ብርታቱም እንደ ወይራ ዛፍ የነበረውን አሞራዊውን ከፊታቸው አጠፋሁ፤ ፍሬውንም ከላዩ፥ ሥሩንም ከታቹ አጠፋሁ።'),
  ('3f2e08f3-2c54-5da0-a056-d07276e515d9', '3bb7032b-553e-5563-a1f7-f189c76b581e', '62637eab-f53a-57e5-a31f-151c7a4633ea', 5, 10, 'የአሞራዊውንም ምድር ትወርሱ ዘንድ ከግብፅ ምድር አወጣኋችሁ፤ በምድረ በዳም አርባ ዓመት መራኋችሁ።'),
  ('8435d2c7-7660-5d00-a596-5f19b359ade2', '3bb7032b-553e-5563-a1f7-f189c76b581e', '62637eab-f53a-57e5-a31f-151c7a4633ea', 6, 11, 'ከወንድ ልጆቻችሁም ነቢያትን፥ ከጐበዛዝቶቻችሁም ለእኔ የተለዩትን አስነሣሁ፤ እናንተ የእስራኤል ልጆች ሆይ! ይህ እንደዚህ አይደለምን?” ይላል እግዚአብሔር።'),
  ('5491b3e7-72a6-5c57-a2a7-127945236a1e', '3bb7032b-553e-5563-a1f7-f189c76b581e', '62637eab-f53a-57e5-a31f-151c7a4633ea', 7, 12, '“እናንተ ግን ለእኔ የተለዩትን የወይን ጠጅ አጠጣችኋቸው፤ ነቢያቱንም፥ “ትንቢትን አትናገሩ ብላችሁ ከለከላችኋቸው።'),
  ('78015738-3ed9-5aca-aec8-58f2ff71ffcb', '3bb7032b-553e-5563-a1f7-f189c76b581e', '62637eab-f53a-57e5-a31f-151c7a4633ea', 8, 13, '“ስለዚህ ሠረገላ ብርዑን እንዲያደቅ፥ በበታቻችሁ ባለ መሬት እኔ አደቅቃችኋለሁ።'),
  ('d49765bd-390d-5a7b-a354-440328195fb1', '3bb7032b-553e-5563-a1f7-f189c76b581e', '62637eab-f53a-57e5-a31f-151c7a4633ea', 9, 14, 'የሚሮጥ ሰው ማምለጥ አይችልም፤ ኀይለኛውም በብርታቱ አይዝም፤ አርበኛውም ነፍሱን አያድንም።'),
  ('ec230a8d-e651-56be-a44f-8bac660dee09', '3bb7032b-553e-5563-a1f7-f189c76b581e', '62637eab-f53a-57e5-a31f-151c7a4633ea', 10, 15, 'ቀስተኛውም አይቆምም፤ ፈጣኑም አያመልጥም፤ ፈረሰኛውም ነፍሱን አያድንም፤'),
  ('f7aa7d28-948c-5313-a372-bc0de1253a8a', '3bb7032b-553e-5563-a1f7-f189c76b581e', '62637eab-f53a-57e5-a31f-151c7a4633ea', 11, 16, 'ልበ ሙሉው ኀይለኛም በኀይሉ አይተማመንም፤ ነገር ግን በዚያ ቀን ዕራቁቱን ሆኖ ይሸሻል” ይላል እግዚአብሔር።'),
  ('2c39ccac-e15b-5fe9-ae83-9e4eaff307bf', 'ba2d6833-167e-5432-ac80-a1bc7a13b173', '9ed182a6-ea16-590c-ae8a-5606fd448edc', 1, 1, 'የእስራኤል ቤት ሆይ! እኔ እግዚአብሔር በእናንተና ከግብፅ ምድር በአወጣሁት ወገን ሁሉ ላይ የተናገርሁትን ይህን ቃል ስሙ፤ እንዲህም አልሁ፦'),
  ('44275462-3cc2-5ad0-a01c-0baf580e2261', 'ba2d6833-167e-5432-ac80-a1bc7a13b173', '9ed182a6-ea16-590c-ae8a-5606fd448edc', 2, 2, '“እኔ ከምድር አሕዛብ ሁሉ እናንተን ብቻችሁን አውቄአችኋለሁ፤ ስለዚህ ስለ ኀጢአታችሁ ሁሉ እበቀላችኋለሁ።”'),
  ('24eb95b8-fb55-5993-a09c-6cb3c2c23018', 'ba2d6833-167e-5432-ac80-a1bc7a13b173', '9ed182a6-ea16-590c-ae8a-5606fd448edc', 3, 3, 'በውኑ ሁለት ሰዎች ሳይተያዩ በአንድነት ይሄዳሉን?'),
  ('dc9ca65e-1fd9-5a2d-ae75-7024648d4492', 'ba2d6833-167e-5432-ac80-a1bc7a13b173', '9ed182a6-ea16-590c-ae8a-5606fd448edc', 4, 4, 'ወይስ አንበሳ የሚነጥቀው ነገር ሳያገኝ በጫካው ውስጥ በከንቱ ያገሣልን? ወይስ የአንበሳ ደቦል አንዳች ሳይዝ በመደቡ ሆኖ በከንቱ ይጮኻልን?'),
  ('5cf7df42-dfbc-588c-af0e-3353e4c62651', 'ba2d6833-167e-5432-ac80-a1bc7a13b173', '9ed182a6-ea16-590c-ae8a-5606fd448edc', 5, 5, 'ወይስ ወፍ፥ አጥማጅ ከሌለው፥ በምድር ላይ በወጥመድ ይያዛልን? ወይስ ወስፈንጠር አንዳች ሳይዝ ከምድር በከንቱ ይፈናጠራልን?'),
  ('690a7c8f-cfa5-5d38-ac71-24c96b284c48', 'ba2d6833-167e-5432-ac80-a1bc7a13b173', '9ed182a6-ea16-590c-ae8a-5606fd448edc', 6, 6, 'ወይስ በከተማ ውስጥ መለከት ሲነፋ ሕዝቡ አይደነግጡምን? ወይስ እግዚአብሔር ያላዘዘው ክፉ ነገር በከተማ ላይ ይመጣልን?'),
  ('cc88306e-bf60-547b-a8d0-3681c2d3c902', 'ba2d6833-167e-5432-ac80-a1bc7a13b173', '9ed182a6-ea16-590c-ae8a-5606fd448edc', 7, 7, 'ጌታ እግዚአብሔር ለባሪያዎቹ ለነቢያት ያልገለጠውንና ያልነገረውን ምንም አያደርግምና።'),
  ('f4ba2ff6-42a7-578d-aff5-563ad8aa01a5', 'ba2d6833-167e-5432-ac80-a1bc7a13b173', '9ed182a6-ea16-590c-ae8a-5606fd448edc', 8, 8, 'አንበሳው አገሣ፤ የማይፈራ ማን ነው? ጌታ እግዚአብሔር ተናገረ፤ ትንቢት የማይናገር ማን ነው?'),
  ('e375b0b8-0848-50ba-a6b4-49279b52b4c5', 'ba2d6833-167e-5432-ac80-a1bc7a13b173', 'e417bb3e-30c0-50fa-a1ce-5e065156bc0d', 1, 9, 'በፋርስ ሀገሮችና በግብፅ ሀገሮች ዐውጁና፥ “በሰማርያ ተራሮች ላይ ተሰብሰቡ፤ በውስጥዋም የሆነውን ታላቁን ተአምር፥ በመካካልዋም ያለውን ግፍ ተመልከቱ” በሉ።'),
  ('5c7e8cbf-182f-5c62-a6a9-ade785963bf7', 'ba2d6833-167e-5432-ac80-a1bc7a13b173', 'e417bb3e-30c0-50fa-a1ce-5e065156bc0d', 2, 10, '“በፊቷ የሚመጣባትን አላወቀችም፤ ይላል እግዚአብሔር፤ በሀገራቸው ቅሚያንና ግፍን የሚያከማቹ ናቸው።”'),
  ('83c3245d-c45a-5c54-abc8-ac5aba613f0b', 'ba2d6833-167e-5432-ac80-a1bc7a13b173', 'e417bb3e-30c0-50fa-a1ce-5e065156bc0d', 3, 11, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፥ “እስከ ጢሮስ በአለው ዙሪያሽ ድረስ ምድርሽ ይጠፋል፥ ብርታትሽንም ከአንቺ ያወርዳል፤ ሀገሮችሽም ይበዘበዛሉ።”'),
  ('f12014a8-7f1b-5fd6-a2be-34f8612f78a6', 'ba2d6833-167e-5432-ac80-a1bc7a13b173', 'e417bb3e-30c0-50fa-a1ce-5e065156bc0d', 4, 12, 'ስለዚህ እግዚአብሔር እንዲህ ይላል፥ “እረኛ ከአንበሳ አፍ ሁለት እግርን ወይም የጆሮን ጫፍ እንደሚያድን፥ እንዲሁ በሰማርያ በአሕዛብ ፊትና በደማስቆ የተቀመጡት የእስራኤል ልጆች ይድናሉ።'),
  ('743de48c-cd98-53f9-acdc-6c6ecd408996', 'ba2d6833-167e-5432-ac80-a1bc7a13b173', 'e417bb3e-30c0-50fa-a1ce-5e065156bc0d', 5, 13, '“ካህናት ሆይ! ስሙ፤ በያዕቆብም ቤት ላይ መስክሩ፥ ይላል ሁሉን የሚችል ጌታ እግዚአብሔር።'),
  ('12e1bcfd-8a5f-5259-adb7-82def2c36bd1', 'ba2d6833-167e-5432-ac80-a1bc7a13b173', 'e417bb3e-30c0-50fa-a1ce-5e065156bc0d', 6, 14, 'እስራኤልን ስለ ኀጢአቱ በምበቀልበት ቀን የቤቴልን መሠዊያዎች ደግሞ እበቀላለሁ፤ የመሠዊያው ቀንዶች ይሰበራሉ፤ ወደ ምድርም ይወድቃሉ።'),
  ('e5252f5c-e40b-552d-a0f7-14148c033aba', 'ba2d6833-167e-5432-ac80-a1bc7a13b173', 'e417bb3e-30c0-50fa-a1ce-5e065156bc0d', 7, 15, 'የክረምቱንና የበጋዉን ቤት እመታለሁ፤ በዝሆንም ጥርስ የተለበጡት ቤቶች ይጠፋሉ፤ ሌሎችም ታላላቆች ቤቶች ይፈርሳሉ” ይላል ጌታ እግዚአብሔር።'),
  ('9a163c07-a451-5c16-af73-977849aeb032', 'b9b05139-715b-5906-aa63-dae309895833', '1dd51ab5-267d-5639-a4d3-738a954a1b99', 1, 1, 'በሰማርያ ተራራ የምትኖሩ፥ ድሆችንም የምትበድሉ፥ ችግረኞችንም የምታስጨንቁ፥ ጌቶቻቸውንም፦ አምጡ እንጠጣ የምትሉ እናንተ የባሳን ላሞች ሆይ! ይህን ቃል ስሙ።'),
  ('7a967800-67b9-5f96-acca-930d2b95c74d', 'b9b05139-715b-5906-aa63-dae309895833', '1dd51ab5-267d-5639-a4d3-738a954a1b99', 2, 2, 'ጌታ አግዚአብሔር፥ “እናንተን በሰልፍ ዕቃ፥ ቅሬታችሁንም በመቃጥን የሚወስዱበት ቀን እነሆ በላያችሁ ይመጣል” ብሎ በቅዱስነቱ ምሎአል።'),
  ('d48e3a67-3f02-5984-a494-206e5b8552ac', 'b9b05139-715b-5906-aa63-dae309895833', '1dd51ab5-267d-5639-a4d3-738a954a1b99', 3, 3, '“ዕራቁታችሁን ያወጡአችኋል፤ እርስ በርሳችሁም ትተያያላችሁ፤ በሬማንም ተራራ ትጣላላችሁ፥ ይላል ጌታ እግዚአብሔር።'),
  ('7ff2d69d-db2d-5910-a022-785b4f1fe731', 'b9b05139-715b-5906-aa63-dae309895833', 'fb2728ad-e572-53f3-a2e7-4acf44f89d9f', 1, 4, '“ወደ ቤቴል ገብታችሁ ኀጢአትን ሠራችሁ፤ በጌልገላም ኀጢአትን አበዛችሁ፤ በየማለዳውም መሥዋዕታችሁን፥ በየሦስተኛውም ቀን ዐሥራታችሁን አቀረባችሁ፤'),
  ('96c3669f-8080-5492-aad7-b4d7d2aa6268', 'b9b05139-715b-5906-aa63-dae309895833', 'fb2728ad-e572-53f3-a2e7-4acf44f89d9f', 2, 5, 'ሕጉን በውጭ አነበባችሁ፤ የታመነም አላችሁት፤ በፈቃዳችሁም የምታቀርቡትን አውጁና አውሩ፥” ይላል ጌታ እግዚአብሔር።'),
  ('ea356cc1-0415-5b7a-ac9f-ca03e2bfcae1', 'b9b05139-715b-5906-aa63-dae309895833', 'fb2728ad-e572-53f3-a2e7-4acf44f89d9f', 3, 6, '“በከተማችሁ ሁሉ ጥርስን ማጥረስን፥ በስፍራችሁም ሁሉ እንጀራን ማጣትን ሰጠኋችሁ፤ እናንተ ግን ወደ እኔ አልተመለሳችሁም ይላል እግዚአብሔር።'),
  ('ceb36d9c-151c-534a-a1d5-5d537176f53e', 'b9b05139-715b-5906-aa63-dae309895833', 'fb2728ad-e572-53f3-a2e7-4acf44f89d9f', 4, 7, 'መከር ሳይደርስ ገና ከሦስት ወር በፊት ዝናብን ከለከልኋችሁ፤ በአንድም ከተማ ላይ አዘነብሁ፤ በሌላውም ከተማ ላይ እንዳይዘንብ አደረግሁ፤ በአንድ ወገን ዘነበ፤ ያልዘነበበትም ወገን ደረቀ።'),
  ('3267e3c2-20d1-5af8-a272-fcd6670361f6', 'b9b05139-715b-5906-aa63-dae309895833', 'fb2728ad-e572-53f3-a2e7-4acf44f89d9f', 5, 8, 'የሁለት ወይም የሦስት ከተሞች ሰዎች ወደ አንዲት ከተማ ውኃ ይጠጡ ዘንድ ሄዱ፤ ነገር ግን አልረኩም፤ እናንተ ግን ወደ እኔ አልተመለሳችሁም፥ ይላል እግዚአብሔር።'),
  ('60f53cf8-fe11-557d-a452-6b43345129d7', 'b9b05139-715b-5906-aa63-dae309895833', 'fb2728ad-e572-53f3-a2e7-4acf44f89d9f', 6, 9, 'በአባርና በቸነፈር መታኋችሁ፤ አትክልታችሁ፥ ወይናችሁና በለሳችሁ፥ ወይራችሁም ከበጀ በኋላ ተምች በላው፤ ይህም ሆኖ እናንተ ወደ እኔ አልተመለሳችሁም፥ ይላል እግዚአብሔር።'),
  ('c3678f65-82e3-5231-ac46-4216fd29f233', 'b9b05139-715b-5906-aa63-dae309895833', 'fb2728ad-e572-53f3-a2e7-4acf44f89d9f', 7, 10, '“በግብፅ እንደ ሆነው ሞትን ሰደድሁባችሁ፤ ጐበዛዝቶቻችሁን በሰይፍ ገደልሁ፤ ፈረሶቻችሁንም አስማረክሁ፤ በሰፈራችሁም እሳትን ሰድጄ አጠፋኋችሁ፤ በዚህም ሁሉ እናንተ ወደ እኔ አልተመለሳችሁም፥ ይላል እግዚአብሔር።'),
  ('28da5bb1-40a6-5a4f-ad0d-3a77389b18b4', 'b9b05139-715b-5906-aa63-dae309895833', 'fb2728ad-e572-53f3-a2e7-4acf44f89d9f', 8, 11, 'ሰዶምንና ገሞራን አስቀድሜ እንደ ገለበጥኋቸው፥ እንዲሁ ገለበጥኋችሁ፤ እናንተም ከእሳት ውስጥ እንደ ተነጠቀ ትንታግ ሆናችሁ፤ በዚህም ወደ እኔ አልተመለሳችሁም” ይላል እግዚአብሔር።'),
  ('6f502d31-c620-5e8f-adb1-366e4b693a77', 'b9b05139-715b-5906-aa63-dae309895833', 'fb2728ad-e572-53f3-a2e7-4acf44f89d9f', 9, 12, '“ስለዚህ እስራኤል ሆይ! እንደዚህ አደርግብሃለሁ፤ እስራኤልም ሆይ! እንደዚህ ስለማደርግብህ የአምላክህን ስም ለመጥራት ተዘጋጅ።'),
  ('c481200f-7c43-5800-ac36-262e201b01e5', 'b9b05139-715b-5906-aa63-dae309895833', 'fb2728ad-e572-53f3-a2e7-4acf44f89d9f', 10, 13, 'እነሆ ነጐድጓድን የሚያጸና፥ ነፋስንም የፈጠረ፥ የመሢሕን ነገር ለሰው የሚነግር፥ ንጋትን ጭጋግ የሚያደርግ፥ በምድርም ከፍታዎች ላይ የሚረግጥ፥ ስሙ ሁሉን የሚችል ጌታ እግዚአብሔር እኔ ነኝ።”'),
  ('8c33b013-f10c-5bcc-a7e6-1b9062963a14', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 1, 1, 'የእስራኤል ቤት ሆይ! በእናንተ ላይ ለሙሾ የማነሣውን ይህን የእግዚአብሔርን ቃል ስሙ።'),
  ('3ac8eb55-bf50-5da4-a247-20d0cec71f68', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 2, 2, 'የእስራኤል ድንግል ወደቀች፤ ከእንግዲህም ወዲህ አትነሣም፤ በምድርዋ ላይ ተጣለች፤ የሚያስነሣትም የለም።'),
  ('829ebd20-8768-5912-a9a1-89d3be8e2906', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 3, 3, 'ጌታ እግዚአብሔርም እንዲህ ይላልና፥ “ሺህ ከሚወጡባት ከተማ መቶ ይቀራሉ፤ መቶም ከሚወጡባት ከተማ ለእስራኤል ቤት ዐሥር ይቀራሉ።”'),
  ('71d6ff0a-c02d-5f23-a75a-01806592bcf4', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 4, 4, 'እግዚአብሔርም ለእስራኤል ቤት እንዲህ ይላልና፥ “እኔን ፈልጉ፤ በሕይወትም ትኖራላችሁ፤'),
  ('62405eaf-5879-5b84-af63-4e0191ce5aba', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 5, 5, 'ነገር ግን ጌልገላ ፈጽሞ ትማረካለችና፥ ቤቴልም እንዳልነበረች ትሆናለችና ቤቴልን አትፈልጉ፤ ወደ ጌልገላም አትሂዱ፤ ወደ ቤርሳቤህም አትለፉ።”'),
  ('34cd2742-c7f5-5539-a744-263d95c5da6c', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 6, 6, 'በዮሴፍ ቤት እሳት እንዳትቃጠል፥ እንዳትበላቸውም የእስራኤልንም ቤት እሳት የሚያጠፋላቸው እንዳያጡ እግዚአብሔርን ፈልጉ፤ በሕይወትም ትኖራላችሁ።'),
  ('28299dec-9e6b-5554-ace8-190efc16adc7', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 7, 7, 'እግዚአብሔር ፍርድን በሰማይ ያደርጋል፤ ጽድቅንም በምድር ላይ ይመሠርታል።'),
  ('fc726b1d-9c83-51eb-ac13-d8edaa40ae75', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 8, 8, 'ሁሉን የሚሠራና የሚያቅናና፥ ብርሃኑን ወደ መስዕ የሚመልሰው፥ ቀኑን እንደ ሌሊት የሚያጨልመው፥ የባሕሩንም ውኃ ጠርቶ በምድር ፊት የሚያፈስሰው ስሙ ሁሉን የሚችል ጌታ እግዚአብሔር ነው።'),
  ('155356b3-ab90-54d6-a318-696121b950f2', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 9, 9, 'በኀያላን ላይ ቅጥቃጤን፥ በአንባዎችም ላይ ጕስቍልናን ያመጣል።'),
  ('987a020f-4d58-59b4-af5e-cc6ccb229afe', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 10, 10, 'በበሩ የሚገሥጸውን ጠሉ፤ እውነትንም የሚናገረውን ተጸየፉ።'),
  ('840601c2-ee2b-5201-a31a-c57bfb472625', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 11, 11, 'ድሃውንም ደብድባችኋልና፤ መማለጃንም ከእርሱ ወስዳችኋልና፤ ያማሩ ቤቶችንም መርጣችሁ ሠርታችኋልና፥ ነገር ግን አትኖሩባቸውም፤ ያማሩ የወይን ቦታዎችም ተክላችኋል፤ ነገር ግን ወይንን አትጠጡም።'),
  ('c60ec71c-a333-588e-ad22-f57471552a35', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 12, 12, 'ጻድቁን የምታስጨንቁ፥ ጉቦንም የምትቀበሉ፥ በበሩም የችግረኛውን ፍርድ የምታጣምሙ እናንተ ሆይ! በደላችሁ እንዴት እንደ በዛ፥ ኀጢአታችሁም እንዴት እንደ ጸና እኔ ዐውቃለሁና።'),
  ('708db43f-c5c6-569f-acc4-e516bfbff275', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 13, 13, 'ስለዚህ ዘመኑ ክፉ ነውና በዚያ ዘመን አስተዋይ ዝም ይላል።'),
  ('7074a6f8-087b-5b0c-a914-c49c5f23f537', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 14, 14, 'በሕይወት ትኖሩ ዘንድ መልካሙን ፈልጉ፤ ክፉውንም አይደለም፤ እንዲሁ እናንተ እንደ ተናገራችሁ ሁሉን የሚችል እግዚአብሔር ከእናንተ ጋር ይሆናል።'),
  ('1f19303e-fb8d-59de-ab4c-7a8e7d61d6e6', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 15, 15, 'ክፉውን ጥሉ፤ መልካሙንም ውደዱ፤ በበሩም አደባባይ ፍርድን አጽኑ፤ ምናልባት ሁሉን የሚችል እግዚአብሔር ለዮሴፍ ቅሬታ ይራራ ይሆናል።'),
  ('7f146899-1a47-5f5e-a02b-5fedb273d722', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 16, 16, 'ስለዚህ ሁሉን የሚችል እግዚአብሔር እንዲህ ይላል፥ “በየአደባባዩ ሁሉ ላይ ዋይታ ይሆናል፤ በየመንገዱም ሁሉ ላይ ወዮ ወዮ ይባላል፤ ገበሬዎቹም ወደ ልቅሶ፥ አልቃሾቹም ወደ ዋይታ ይጠራሉ።'),
  ('cff9d4ab-4965-5081-aa26-e335f04bff8b', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', 'cbde1688-c188-5479-ac83-61fb9a994b91', 17, 17, 'በመካከልህ አልፋለሁና በጎዳናው ሁሉ ልቅሶ ይሆናል” ይላል እግዚአብሔር።'),
  ('14935d0f-e1c7-5609-a9cd-55c1e631f89f', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', '8b393f9b-4112-5d14-a3c4-50cb59ea7c06', 1, 18, 'የእግዚአብሔርን ቀን ለምትፈልጉ ወዮላችሁ! የእግዚአብሔርን ቀን ለምን ትፈልጋላችሁ? ጨለማ ነው እንጂ ብርሃን አይደለም።'),
  ('8b346502-7cfd-52c6-a1b6-f20a9a8a6e68', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', '8b393f9b-4112-5d14-a3c4-50cb59ea7c06', 2, 19, 'ከአንበሳ ፊት እንደ ሸሸ፥ ድብም እንዳገኘው ሰው፥ ወደ ቤትም ገብቶ እጁን በግድግዳ ላይ እንዳስደገፈና እባብ እንደ ነደፈው ሰው ይሆናል።'),
  ('2ded8201-e44d-5c99-a6d2-ecf1d3d55c78', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', '8b393f9b-4112-5d14-a3c4-50cb59ea7c06', 3, 20, 'የእግዚአብሔር ቀን ብርሃን ሳይሆን ጨለማ አይደለምን? ፀዳል የሌለውም ድቅድቅ ጨለማ አይደለምን?'),
  ('bc4a515d-9130-5b1e-aa74-952d720fe46a', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', '8b393f9b-4112-5d14-a3c4-50cb59ea7c06', 4, 21, 'ዓመት በዓላችሁን ጠልችዋለሁ፤ አርቄውማለሁ፤ መዓዛ መሥዋዕታችሁን አላሸትም።'),
  ('05f5529a-b046-5a25-a0c1-08d17e4d5f55', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', '8b393f9b-4112-5d14-a3c4-50cb59ea7c06', 5, 22, 'የሚቃጠለውን መሥዋዕታችሁንና የእህሉን ቍርባናችሁን ብታቀርቡልኝም እንኳ አልቀበለውም፤ የድኅነት መሥዋዕታችሁንም አልመለከትም።'),
  ('4044fa20-7402-58e0-a4f7-143de72c1995', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', '8b393f9b-4112-5d14-a3c4-50cb59ea7c06', 6, 23, 'የዝማሬህንም ጩኸት ከእኔ ዘንድ አርቅ፤ የመሰንቆህንም ዜማ አላዳምጥም።'),
  ('51391fdf-1e15-5709-a4e0-6339af7938e8', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', '8b393f9b-4112-5d14-a3c4-50cb59ea7c06', 7, 24, 'ነገር ግን ፍርድ እንደ ውኃ፥ ጽድቅም እንደማይደርቅ ፈሳሽ ይፍሰስ።'),
  ('378fd8a1-0629-527d-ad08-241cb6827dc8', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', '8b393f9b-4112-5d14-a3c4-50cb59ea7c06', 8, 25, '“የእስራኤል ቤት ሆይ! በውኑ በምድረ በዳ አርባ ዓመት ሙሉ መሥዋዕትንና ቍርባንን አቅርባችሁልኛልን?'),
  ('24948bcb-ff93-555e-a932-7bf12576bf8c', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', '8b393f9b-4112-5d14-a3c4-50cb59ea7c06', 9, 26, 'ለራሳችሁም የሠራችኋቸውን ምስሎች፥ የሞሎክን ድንኳንና የአምላካችሁን የሬፋንን ኮከብ አነሣችሁ።'),
  ('26f12755-b04d-5c58-aeea-2dd6a20c03dc', 'ef5f901a-a8fd-511f-a4ec-46214f097ee0', '8b393f9b-4112-5d14-a3c4-50cb59ea7c06', 10, 27, 'ስለዚህ ከደማስቆ ወደዚያ አስማርካችኋለሁ” ይላል ስሙ የሠራዊት ጌታ የተባለ እግዚአብሔር።'),
  ('a9e3d608-4637-5687-a920-c4d3c05e9cdd', '28c73b93-1793-50e0-a216-d2afe4e20f75', '3c36c00a-75a8-5a2b-aee5-0daf7018b4c9', 1, 1, 'ጽዮንን ለሚንቁ፥ በሰማርያም ተራራ ለሚታመኑ ሰዎች ወዮላቸው፤ የአሕዛብን አለቆች ለቀሙአቸው።'),
  ('9f3bdff0-a850-54a6-a0f2-b39bade5be27', '28c73b93-1793-50e0-a216-d2afe4e20f75', '3c36c00a-75a8-5a2b-aee5-0daf7018b4c9', 2, 2, 'የእስራኤል ቤት ሆይ፥ ወደ ካልኔ ተሻግራችሁ ተመልከቱ፤ ከዚያም ወደ ኤማትራባ እለፉ፤ ከዚያም ወደ ፍልስጥኤም ጌት ውረዱ፤ እነርሱ ከእነዚህ መንግሥታት ይበረታሉ፤ ድንበራቸውም ከድንበራቸው ይሰፋልና።'),
  ('4bfd1f76-73de-5cf4-aeb1-282d219b023e', '28c73b93-1793-50e0-a216-d2afe4e20f75', '3c36c00a-75a8-5a2b-aee5-0daf7018b4c9', 3, 3, 'ክፉ ቀንን ለሚፈልጓት፥ የሐሰት ሰንበታትን ለሚያቀራርቡና አንድ ለሚያደርጉ፥'),
  ('430177a6-a59a-59f6-a647-b8f3a8087b3f', '28c73b93-1793-50e0-a216-d2afe4e20f75', '3c36c00a-75a8-5a2b-aee5-0daf7018b4c9', 4, 4, 'ከዝሆን ጥርስ በተሠራ አልጋ ላይ ለሚተኙ፥ በምንጣፋቸው ደስ ለሚሰኙ፥ ከበጎችም መንጋ ጠቦትን፥ ከጋጥም ውስጥ ጥጃን ለሚመገቡ፥'),
  ('3e1257af-e09e-5003-ae4e-eb81d22a7b4a', '28c73b93-1793-50e0-a216-d2afe4e20f75', '3c36c00a-75a8-5a2b-aee5-0daf7018b4c9', 5, 5, 'ከበገናው ድምፅ ጋር አስተባብረው ለሚያጨበጭቡ ሰዎች፤ ይኸውም የማያልፍ ለሚመስላቸውና እንደሚያመልጣቸው ለማያውቁ፤'),
  ('b9a5287e-cb27-5d88-a810-9141993f4a32', '28c73b93-1793-50e0-a216-d2afe4e20f75', '3c36c00a-75a8-5a2b-aee5-0daf7018b4c9', 6, 6, 'በጽዋ የቀላ ወይን ለሚጠጡ፥ እጅግ በአማረ ሽቱም ለሚቀቡ፥ በዮሴፍ ስብራት ለማያስቡ ወዮላቸው።'),
  ('7e375f46-32f9-5134-afd7-ca487c3cf198', '28c73b93-1793-50e0-a216-d2afe4e20f75', '3c36c00a-75a8-5a2b-aee5-0daf7018b4c9', 7, 7, 'ስለዚህ ከአለቆቻቸው አስቀድመው ይማረካሉ፤ ሯጮች የሚሆኑ የኤፍሬም ፈረሶችም ያልቃሉ።'),
  ('c3da03e9-9169-5132-a506-0f9702845f2d', '28c73b93-1793-50e0-a216-d2afe4e20f75', '3c36c00a-75a8-5a2b-aee5-0daf7018b4c9', 8, 8, 'ጌታ እግዚአብሔር፥ “የያዕቆብን ትዕቢት አረክሳለሁ፤ ሀገሮቹንም ጠላሁ፤ ከተሞቹንም ከሚኖሩባቸው ሰዎች ጋር አጠፋለሁ” ብሎ በራሱ ምሎአልና።'),
  ('81464230-7d02-5d87-aa69-1b7597dabecf', '28c73b93-1793-50e0-a216-d2afe4e20f75', '3c36c00a-75a8-5a2b-aee5-0daf7018b4c9', 9, 9, 'እንዲህም ይሆናል፤ ዐሥር ሰዎች በአንድ ቤት ውስጥ ቢቀሩ እነርሱ ይሞታሉ፤ የቀሩት ግን ይተርፋሉ።'),
  ('86494ec9-83d1-50a6-a718-2ef55ce02d22', '28c73b93-1793-50e0-a216-d2afe4e20f75', '3c36c00a-75a8-5a2b-aee5-0daf7018b4c9', 10, 10, 'አጥንቶቻቸውንም ከቤት ያወጡ ዘንድ ቤተሰቦቻቸው በወሰዱአቸው ጊዜ፥ ቤት ጠባቂውን በአንተ ዘንድ የቀረ አለን? በአለው ጊዜ እርሱ የለም ይላል። ያም የእግዚአብሔርንም ስም እንዳትጠራ ዝም በል ይለዋል።'),
  ('6375e0a8-33c4-5b16-a364-5a7def649d3a', '28c73b93-1793-50e0-a216-d2afe4e20f75', '3c36c00a-75a8-5a2b-aee5-0daf7018b4c9', 11, 11, 'እነሆም እግዚአብሔር ያዝዛል፤ ታላቁንም ቤት በማፍረስ፥ ታናሹንም ቤት በመሰባበር ይመታል።'),
  ('75a8c0c5-5d6d-53ad-a90d-9dd05f9fc529', '28c73b93-1793-50e0-a216-d2afe4e20f75', '3c36c00a-75a8-5a2b-aee5-0daf7018b4c9', 12, 12, 'ፍርድን ወደ ቍጣ፥ የእውነትንም ፍሬ ወደ እሬት ለውጣችኋልና፥ በውኑ ፈረሶች በጭንጫ ላይ ይሮጣሉን? ወይስ በሬዎች በዚያ ላይ ያርሳሉን?'),
  ('2dd08802-3372-5481-aa65-58a98c916533', '28c73b93-1793-50e0-a216-d2afe4e20f75', '3c36c00a-75a8-5a2b-aee5-0daf7018b4c9', 13, 13, 'በከንቱ ነገር ደስ የሚላችሁ በኀይላችን ቀንዶችን አበቀልን የምትሉ አይደለምን?'),
  ('90c817f3-73d4-5455-a80c-1e15968f3c88', '28c73b93-1793-50e0-a216-d2afe4e20f75', '3c36c00a-75a8-5a2b-aee5-0daf7018b4c9', 14, 14, '“የእስራኤል ቤት ሆይ እነሆ እኔ የሚያስጨንቋችሁን ሕዝብ አስነሣባችኋለሁ፥” ይላል የሠራዊት አምላክ እግዚአብሔር፤ እነርሱም ከሐማት መግቢያ ጀምረው እስከ ዐረባ ወንዝ ድረስ ትገቡ ዘንድ አይፈቅዱላችሁም።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('c8d0ae00-d7e4-5314-a2c8-b25739eafec5', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', 'caa50a03-6b47-5b58-a91c-f3b7e7d76cbb', 1, 1, 'ጌታ እግዚአብሔር እንዲህ አሳየኝ፤ እነሆም ከምሥራቅ አንበጣ ይመጣል፤ አንዱም ኵብኵባ ንጉሡ ጎግ ነበረ።'),
  ('c62b1579-9f6e-5ce5-a453-7c421cc27a0c', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', 'caa50a03-6b47-5b58-a91c-f3b7e7d76cbb', 2, 2, 'የምድሩንም ሣር በልቶ ይጨርሳል፤ እኔም፥ “ጌታ እግዚአብሔር ሆይ! ይቅር እንድትል እለምንሃለሁ፤ ያዕቆብን ማን ያነሣዋል? ጥቂት ነውና” አልሁ።'),
  ('cc119b9b-2f3b-5cb3-ac22-e3bc2ed00b2a', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', 'caa50a03-6b47-5b58-a91c-f3b7e7d76cbb', 3, 3, 'እግዚአብሔርም ስለዚህ ነገር ራራ፤ “ይህ አይሆንም፤” ይላል እግዚአብሔር።'),
  ('726513c6-d2d1-528b-aa86-e79dfd8978d9', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', '95cd62ca-9599-5efa-a251-9913a3d1d853', 1, 4, 'ጌታ እግዚአብሔርም እንዲህ አሳየኝ፤ እነሆም ጌታ እግዚአብሔር ለመፍረድ በቃሉ እሳትን ጠራ፤ እርስዋም ታላቁን ቀላይና ምድርን በላች።'),
  ('05d3efd9-cd27-5845-ad99-539e15f6b680', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', '95cd62ca-9599-5efa-a251-9913a3d1d853', 2, 5, 'እኔም፥ “ጌታ እግዚአብሔር ሆይ! እንድትተው እለምንሃለሁ፤ ያዕቆብን ማን ያነሣዋል? ጥቂት ነውና” አልሁ።'),
  ('d65e8be5-cd0e-5b6c-a136-40a6306a01f1', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', '95cd62ca-9599-5efa-a251-9913a3d1d853', 3, 6, 'እግዚአብሔርም ስለዚህ ነገር ራራ፤ “ይህ ደግሞ አይሆንም፥” ይላል ጌታ እግዚአብሔር።'),
  ('c66b5e7b-6f54-55c0-ad3a-30bc0f1c3267', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', '2dbb56ba-ee52-57c6-acc0-5d510af43b99', 1, 7, 'ጌታ እግዚአብሔር እንዲህ አሳየኝ፤ እነሆም አንድ ሰው በቱንቢ በተሠራ ቅጥር ላይ ቆሞ ነበር፤ በእጁም ቱንቢ ነበር።'),
  ('f21e8f28-4159-5f11-a013-6d7442cbc505', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', '2dbb56ba-ee52-57c6-acc0-5d510af43b99', 2, 8, 'እግዚአብሔርም፥ “አሞጽ ሆይ! የምታየው ምንድን ነው?” አለኝ። እኔም፥ “ቱንቢ ነው” አልሁ። ጌታም፥ “እነሆ! በሕዝቤ በእስራኤል መካከል ቱንቢ አደርጋለሁ፤ ከእንግዲህም ወዲህ ደግሞ ይቅር አልላቸውም።'),
  ('c85f79ca-fe3f-5b00-a033-984e882f81a5', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', '2dbb56ba-ee52-57c6-acc0-5d510af43b99', 3, 9, 'መሳቂያ የሆኑ የኮረብታው መስገጃዎች ይፈርሳሉ፤ የእስራኤልም መቅደሶች ባድማ ይሆናሉ፤ በኢዮርብዓምም ቤት ላይ በሰይፍ እነሣለሁ” አለ።'),
  ('8ca5abb8-6f39-5f5b-a120-04ec947d03a4', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', '8027ba20-56c0-5247-a89f-aa1d74df6d9f', 1, 10, 'የቤቴልም ካህን አሜስያስ ወደ እስራኤል ንጉሥ ወደ ኢዮርብዓም ልኮ፥ “አሞጽ በእስራኤል ቤት መካከል ዐምፆብሃል፤ ምድሪቱም ቃሉን ሁሉ ልትሸከም አትችልም” አለ።'),
  ('fdb3e4e5-2895-58ee-a21e-034f3f25d951', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', '8027ba20-56c0-5247-a89f-aa1d74df6d9f', 2, 11, 'አሞጽ፥ “ኢዮርብዓም በሰይፍ ይሞታል፤ እስራኤልም ከሀገሩ ተማርኮ ይሄዳል” ብሎአልና።'),
  ('5ee5d222-a887-509d-a5ab-e9375337a2c2', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', '8027ba20-56c0-5247-a89f-aa1d74df6d9f', 3, 12, 'አሜስያስም አሞጽን፥ “ባለ ራእዩ ሆይ! ሂድ፤ ወደ ይሁዳ ምድር ሽሽ፤ በዚያም ተቀመጥ፥ በዚያም ትንቢትን ተናገር፤'),
  ('45a73f6e-560a-5006-a7c2-72eca0ec9c57', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', '8027ba20-56c0-5247-a89f-aa1d74df6d9f', 4, 13, 'ነገር ግን ቤቴል የንጉሥ መቅደስና የመንግሥት ቤት ናትና ከእንግዲህ ወዲህ በዚህ ደግሞ ትንቢት አትናገር” አለው።'),
  ('441070a5-9894-5d1c-ae71-97b0e01ed95f', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', '8027ba20-56c0-5247-a89f-aa1d74df6d9f', 5, 14, 'አሞጽም መልሶ አሜስያስን አለው፥ “እኔ ላም ጠባቂና በለስ ለቃሚ ነኝ እንጂ ነቢይ ወይም የነቢይ ልጅ አይደለሁም፤'),
  ('444f6834-cf7b-5368-aa13-fa69d8d2fb21', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', '8027ba20-56c0-5247-a89f-aa1d74df6d9f', 6, 15, 'እግዚአብሔርም በጎቹን ከመከተል ወሰደኝ፤ እግዚአብሔርም፦ ሂድ፥ ለሕዝቤ ለእስራኤል ትንቢት ተናገር አለኝ።'),
  ('d9ddfe2e-b3fd-5570-afc8-60e9731bd4e1', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', '8027ba20-56c0-5247-a89f-aa1d74df6d9f', 7, 16, 'አሁንም የእግዚአብሔርን ቃል ስማ፤ አንተ፦ በእስራኤል ላይ ትንቢት አትናገር፥ የያዕቆብንም ቤት አትዘብዝባቸው ብለሃል።'),
  ('88437635-8b5d-5b76-a0d1-c2b549aa8edd', 'a2b74acf-4c94-5eb3-a544-9585caaebbac', '8027ba20-56c0-5247-a89f-aa1d74df6d9f', 8, 17, 'ስለዚህ እግዚአብሔር እንዲህ ይላል፦ ሚስትህ በከተማይቱ ውስጥ አመንዝራ ትሆናለች፤ ወንዶችና ሴቶች ልጆችህም በሰይፍ ይወድቃሉ፤ ምድርህም በገመድ ትከፈላለች፤ አንተም በረከሰች ምድር ትሞታለህ፤ እስራኤልም ከምድሩ ተማርኮ ይሄዳል።”'),
  ('9279fb0b-c54b-5d4b-a057-cbe174c96c13', '42b4c332-fa63-57b5-abde-92f0bd725467', '2ce65033-841d-5b65-af64-f63325cd16cf', 1, 1, 'ጌታ እግዚአብሔር እንዲህ አሳየኝ፤ እነሆም የቃርሚያ ፍሬ የሞላበት ዕንቅብ ነበረ።'),
  ('d34755b4-2a94-5c73-ad72-99693a8efd8c', '42b4c332-fa63-57b5-abde-92f0bd725467', '2ce65033-841d-5b65-af64-f63325cd16cf', 2, 2, 'እርሱም፥ “አሞጽ ሆይ! የምታየው ምንድን ነው?” አለኝ። እኔም፥ “የቃርሚያ ፍሬ የሞላበት ዕንቅብ ነው” አልሁት። እግዚአብሔርም አለኝ፥ “ፍጻሜ በሕዝቤ በእስራኤል ላይ መጥቶአል፤ ከእንግዲህ ወዲህ ደግሞ ይቅር አልላቸውም።'),
  ('7348f95e-d891-5edb-a421-2d19f849a6dd', '42b4c332-fa63-57b5-abde-92f0bd725467', '2ce65033-841d-5b65-af64-f63325cd16cf', 3, 3, 'ያንጊዜም በመቅደሶቻቸው ዋይ ዋይ ይላሉ” ይላል ጌታ እግዚአብሔር፤ በየስፍራው የሚወድቀው ሬሳ ይበዛልና፤ እነርሱም ይጠፋሉና።'),
  ('dbf2a995-9679-5594-a830-a0094e2ffde2', '42b4c332-fa63-57b5-abde-92f0bd725467', 'aaff71e4-c880-5a65-a52d-f16c49a46d42', 1, 4, 'ችግረኛውን በጥዋት የምታስጨንቁ፥ የሀገሩንም ድሃ የምትቀሙ እናንተ ሆይ!'),
  ('2e94fa78-fa3a-575b-ad1f-3ccccfd7c63e', '42b4c332-fa63-57b5-abde-92f0bd725467', 'aaff71e4-c880-5a65-a52d-f16c49a46d42', 2, 5, '“እህልን እንሸጥ ዘንድ መባቻው መቼ ያልፋል? የኢፍ መስፈሪያውንም እያሳነስን፥ ሰቅሉንም እያበዛን፥ በሐሰተኛም ሚዛን እያታለልን፥'),
  ('fa352982-622a-5c09-a3b6-89bc2bba0d82', '42b4c332-fa63-57b5-abde-92f0bd725467', 'aaff71e4-c880-5a65-a52d-f16c49a46d42', 3, 6, 'ድሃውን በብር፥ ችግረኛውንም በአንድ ጥንድ ጫማ እንገዛ ዘንድ፥ በእህላችንም ንግድ እንድንጠቀም ሰንበት መቼ ያልፋል? የምትሉ እናንተ ሆይ! ይህን ስሙ።”'),
  ('15cd2e34-773f-5932-ad4c-dc58a4506a62', '42b4c332-fa63-57b5-abde-92f0bd725467', 'aaff71e4-c880-5a65-a52d-f16c49a46d42', 4, 7, 'እግዚአብሔር በያዕቆብ ትዕቢት እንዲህ ብሎ ምሎአል፥ “ሥራችሁን ሁሉ ለዘለዓለም ምንም አልረሳም።'),
  ('3aab45b0-94c0-5744-ac24-d96a67a5aee1', '42b4c332-fa63-57b5-abde-92f0bd725467', 'aaff71e4-c880-5a65-a52d-f16c49a46d42', 5, 8, 'በውኑ ምድሪቱ ስለዚህ ነገር አትናወጥምን? በእርስዋም የሚኖር ሁሉ አያለቅስምን? ጦርነት እንደ ወንዝ ይፈስሳል፤ እንደ ግብፅም ወንዝ ይሞላል፤ ደግሞም ይወርዳል።'),
  ('fb5caf9b-17ab-5b41-a777-548e5627781c', '42b4c332-fa63-57b5-abde-92f0bd725467', 'aaff71e4-c880-5a65-a52d-f16c49a46d42', 6, 9, 'በዚያም ቀን ፀሐይ በቀትር ይገባል፥ ይላል ጌታ እግዚአብሔር፤ ብርሃንም በምድር ላይ በቀን ይጨልማል።'),
  ('2ff1452e-d220-522e-a6d2-af42a985efec', '42b4c332-fa63-57b5-abde-92f0bd725467', 'aaff71e4-c880-5a65-a52d-f16c49a46d42', 7, 10, 'ዓመት በዓላችሁንም ወደ ልቅሶ፥ ዝማሬያችሁንም ወደ ዋይታ እለውጣለሁ፤ ማቅንም በወገብ ሁሉ ላይ፥ ቡሃነትንም በራስ ሁሉ ላይ ላይ አመጣለሁ፤ እንደ ወዳጅ ልቅሶ አደርጋችኋለሁ፤ ከእርሱም ጋር ያሉት እንደ መከራ ቀን ይሆናሉ።'),
  ('dd8c558f-ec03-5537-a4cf-2a063aecb953', '42b4c332-fa63-57b5-abde-92f0bd725467', 'aaff71e4-c880-5a65-a52d-f16c49a46d42', 8, 11, '“እነሆ በምድር ላይ ራብን የምሰድድበት ዘመን ይመጣል፥ ይላል ጌታ እግዚአብሔር፤ እርሱም የእግዚአብሔርን ቃል ከመስማት እንጂ እንጀራን ከመራብና ውኃን ከመጠማት አይደለም።'),
  ('d22cdc54-8638-5e1d-aece-f5268d5a2541', '42b4c332-fa63-57b5-abde-92f0bd725467', 'aaff71e4-c880-5a65-a52d-f16c49a46d42', 9, 12, 'ከባሕርም እስከ ባሕር ድረስ፥ ከሰሜንም እስከ ምሥራቅ ድረስ ይቅበዘበዛሉ፤ የእግዚአብሔርንም ቃል ለመሻት ይርዋርዋጣሉ፤ አያገኙትምም።'),
  ('b7488862-6e84-5063-abb0-c3e2dfa5dc9b', '42b4c332-fa63-57b5-abde-92f0bd725467', 'aaff71e4-c880-5a65-a52d-f16c49a46d42', 10, 13, 'በዚያ ቀን መልከ መልካሞቹ ደናግልና ጐበዛዝቱ በጥም ይዝላሉ።'),
  ('7b180be8-2518-5e95-ad68-ec874be3989e', '42b4c332-fa63-57b5-abde-92f0bd725467', 'aaff71e4-c880-5a65-a52d-f16c49a46d42', 11, 14, 'ዳን ሆይ፥ ሕያው አምላክህን! ደግሞም፦ ሕያው የቤርሳቤህን አምላክ ብለው በሰማርያ መማፀኛ የሚምሉ፥ እነርሱ ይወድቃሉ፥ ደግሞም አይነሡም።”'),
  ('da888c47-872e-5486-a255-173a3fb3b90d', 'a1d76cb1-ac62-55ec-a833-ea0d3134c759', 'f8e06e05-4a0f-5f94-a0b0-2b7d9876ae94', 1, 1, 'እግዚአብሔርን በመሠውያው ላይ ቆሞ አየሁት፤ እርሱም እንዲህ አለኝ፥ “አበቦች የተሳሉባቸውን ምሰሶዎችን ምታ፤ መድረኮቹም ይናወጣሉ፤ ራሳቸውንም ቍረጥ፤ እኔም ከእነርሱ የቀሩትን በሰይፍ እገድላለሁ፤ ከሚሸሹትም የሚያመልጥ የለም፤ ከሚያመልጡትም የሚድን የለም።'),
  ('173f5ae3-2d4c-5616-ae17-b6b5cec0dcd4', 'a1d76cb1-ac62-55ec-a833-ea0d3134c759', 'f8e06e05-4a0f-5f94-a0b0-2b7d9876ae94', 2, 2, 'ወደ ሲኦል ቢወርዱ እጄ ከዚያ ታወጣቸዋለች፤ ወደ ሰማይም ቢወጡ ከዚያ አወርዳቸዋለሁ፤'),
  ('7091741f-3fa0-58b3-a386-134024f03e5b', 'a1d76cb1-ac62-55ec-a833-ea0d3134c759', 'f8e06e05-4a0f-5f94-a0b0-2b7d9876ae94', 3, 3, 'በቀርሜሎስ ራስ ውስጥ ቢሸሸጉ ፈልጌ ከዚያ አወጣቸዋለሁ፤ በባሕሩም ጥልቅ ውስጥ ከዐይኔ ቢደበቁ በዚያ እባቡን አዝዛለሁ፤ እርሱም ይነድፋቸዋል፤'),
  ('f98fb0cf-94e5-5556-a70f-e4d739de5ad4', 'a1d76cb1-ac62-55ec-a833-ea0d3134c759', 'f8e06e05-4a0f-5f94-a0b0-2b7d9876ae94', 4, 4, 'በጠላቶቻቸውም ፊት ተማርከው ቢሄዱ በዚያ ሰይፍን አዝዛታለሁ፤ እርስዋም ትገድላቸዋለች፤ ዐይኔንም ለመልካም ሳይሆን ለክፋት በእነርሱ ላይ እጥላለሁ።”'),
  ('5a59caeb-c3e4-55c7-a852-6aaab2e9ec93', 'a1d76cb1-ac62-55ec-a833-ea0d3134c759', 'f8e06e05-4a0f-5f94-a0b0-2b7d9876ae94', 5, 5, 'ሁሉን የሚችል ጌታ እግዚአብሔር ምድርን ሁሉ ይዳስሳል፤ ያነዋውጣታልም፤ የሚኖሩባትም ሁሉ ያለቅሳሉ፤ ግድያ እንደ ወንዝ ይፈስሳል፤ ደግሞም እንደ ግብፅ ወንዝ ይወርዳል።'),
  ('569a6d96-c7cd-5c2c-a4f3-4ac1b4fd6260', 'a1d76cb1-ac62-55ec-a833-ea0d3134c759', 'f8e06e05-4a0f-5f94-a0b0-2b7d9876ae94', 6, 6, 'አዳራሹን በሰማይ የሠራ፥ ትእዛዙንም በምድር ላይ የመሠረተ፥ የባሕርንም ውኃ ጠርቶ በምድር ፊት የሚያፈስሰው እርሱ ነው፤ ስሙም ሁሉን የሚገዛ እግዚአብሔር ነው።'),
  ('9ebe176b-bfa7-5639-a3c0-2e4bb77978fc', 'a1d76cb1-ac62-55ec-a833-ea0d3134c759', 'f8e06e05-4a0f-5f94-a0b0-2b7d9876ae94', 7, 7, '“የእስራኤል ልጆች ሆይ! እናንተ ለእኔ እንደ ኢትዮጵያ ልጆች አይደላችሁምን? ይላል እግዚአብሔር። እስራኤልን ከግብፅ ምድር፥ ፍልስጥኤማውያንንም ከቀጰዶቅያ፥ ሶርያውያንንም ከጕድጓድ ያወጣሁ አይደለምን?'),
  ('349eb7ac-3aca-5e9c-a4b1-8b07faf78547', 'a1d76cb1-ac62-55ec-a833-ea0d3134c759', 'f8e06e05-4a0f-5f94-a0b0-2b7d9876ae94', 8, 8, 'እነሆ የጌታ የእግዚአብሔር ዐይኖች በኀጢአተኛ መንግሥት ላይ ናቸው፤ ከምድርም ፊት አጠፋታለሁ፤ ነገር ግን የያዕቆብን ቤት ፈጽሜ አላጠፋም፤ ይላል እግዚአብሔር።'),
  ('445ed2af-cbcf-50ec-a5f0-346dd85dddb1', 'a1d76cb1-ac62-55ec-a833-ea0d3134c759', 'f8e06e05-4a0f-5f94-a0b0-2b7d9876ae94', 9, 9, 'እነሆ አዝዛለሁ፤ እህልም በመንሽ እንደሚዘራ የእስራኤልን ቤት በአሕዛብ ሁሉ መካከል እዘራለሁ፤ ነገር ግን አንዲት ቅንጣት በምድር ላይ አትወድቅም።'),
  ('e12413d1-39a7-5fc0-a61b-d63a3bbdb7fa', 'a1d76cb1-ac62-55ec-a833-ea0d3134c759', 'f8e06e05-4a0f-5f94-a0b0-2b7d9876ae94', 10, 10, 'ክፉው ነገር አይደርስብንም፤ አያገኘንምም የሚሉ የሕዝቤ ኀጢአተኞች ሁሉ በሰይፍ ይሞታሉ።'),
  ('c797bc4a-e422-54f4-a56f-ae7f5bc7d60e', 'a1d76cb1-ac62-55ec-a833-ea0d3134c759', '1da492db-a173-5b1f-a9a7-7c5c849de6f8', 1, 11, '“በዚያ ቀን የወደቀችውን የዳዊትን ቤት አነሣለሁ፤ የተናደውንም ቅጥርዋን እጠግናለሁ፤ የፈረሰውንም አድሳለሁ፤ እንደ ቀደመውም ዘመን እሠራታለሁ፤'),
  ('10dc1432-43fb-555e-a622-fec4ccae3c83', 'a1d76cb1-ac62-55ec-a833-ea0d3134c759', '1da492db-a173-5b1f-a9a7-7c5c849de6f8', 2, 12, 'ይኸውም የቀሩ ሰዎችንና ስሜም የተጠራባቸውን አሕዛብን ሁሉ ይፈልጉ ዘንድ ነው” ይላል ይህን የሚያደርግ እግዚአብሔር።'),
  ('2f88d894-03c4-500f-a7f6-a8b97e511755', 'a1d76cb1-ac62-55ec-a833-ea0d3134c759', '1da492db-a173-5b1f-a9a7-7c5c849de6f8', 3, 13, '“እነሆ፥ እንዲህ ያለ ወራት ይመጣልን? ይላል እግዚአብሔር፤ እርሻ ከአጨዳ ጋር፥ ዘርም ከእሸት ጋር አንድ ይሆናል፤ ከተራሮችም ማር ይፈስሳል፤ ኮረብታውም ይለመልማል።'),
  ('3e0edeed-504b-542d-a77e-0f7691555595', 'a1d76cb1-ac62-55ec-a833-ea0d3134c759', '1da492db-a173-5b1f-a9a7-7c5c849de6f8', 4, 14, 'የሕዝቤን የእስራኤልን ምርኮ እመልሳለሁ፤ የፈረሱትንም ከተሞች ሠርተው ይቀመጡባቸዋል፤ ወይንንም ይተክላሉ፤ የወይን ጠጃቸውንም ይጠጣሉ፤ ተክልን ይተክላሉ፤ ፍሬውንም ይበላሉ።'),
  ('c94257d3-e6c9-5c55-a6ca-c7618023535a', 'a1d76cb1-ac62-55ec-a833-ea0d3134c759', '1da492db-a173-5b1f-a9a7-7c5c849de6f8', 5, 15, 'በምድራቸውም እተክላቸዋለሁ፤ ከእንግዲህም ወዲህ ከሰጠኋቸው ከምድራቸው አይነቀሉም” ይላል ሁሉን የሚችል እግዚአብሔር አምላክ።'),
  ('492e7e4b-2c8c-5c7b-aa78-76d134b158ab', '693a3d97-11f0-57cc-a903-37df59dfdc95', 'c7433d48-bd48-5f82-ab7c-191590a453c0', 1, 1, 'በይሁዳ ነገሥታት በኢዮአታምና በአካዝ በሕዝቅያስም ዘመን ወደ ሞሬታዊው ወደ ሚክያስ የመጣው፥ ስለ ሰማርያና ስለ ኢየሩሳሌም ያየው፥ የእግዚአብሔር ቃል ይህ ነው።'),
  ('e1b140d8-cdac-5cda-a413-6cd6afc7f7f8', '693a3d97-11f0-57cc-a903-37df59dfdc95', 'c7433d48-bd48-5f82-ab7c-191590a453c0', 2, 2, 'እናንተ አሕዛብ ሁሉ፥ ስሙ፥ ምድርም ሙላዋም ታድምጥ፥ ጌታ እግዚአብሔርም፥ እርሱም በቅዱስ መቅደሱ የሆነ ጌታ፥ ይመስክርባችሁ።'),
  ('1f7209b1-d8c3-5857-a6bc-fcba86601ed9', '693a3d97-11f0-57cc-a903-37df59dfdc95', 'c7433d48-bd48-5f82-ab7c-191590a453c0', 3, 3, 'እነሆ፥ እግዚአብሔር ከስፍራው ይወጣል፥ ወርዶም በምድር ከፍታዎች ላይ ይረግጣል።'),
  ('68b34c68-5570-5471-ab7f-dee46a2eebd8', '693a3d97-11f0-57cc-a903-37df59dfdc95', 'c7433d48-bd48-5f82-ab7c-191590a453c0', 4, 4, 'ተራሮችም በእሳት ፊት እንዳለ ሰም፥ በገደልም ወርዶ እንደሚፈስስ ውኃ፥ በበታቹ ይቀልጣሉ፥ ሸለቆችም ይሰነጠቃሉ።'),
  ('10fa32fc-aa3e-563d-af70-7f26da82b0c2', '693a3d97-11f0-57cc-a903-37df59dfdc95', 'c7433d48-bd48-5f82-ab7c-191590a453c0', 5, 5, 'ይህ ሁሉ ስለ ያዕቆብ በደልና ስለ እስራኤል ቤት ኃጢአት ነው። የያዕቆብም በደል ምንድር ነው? ሰማርያ አይደለችምን? የይሁዳስ የኮረብታው መስገጃ ምንድር ነው? ኢየሩሳሌም አይደለችምን?'),
  ('4a82f2ea-3572-5f8e-a68d-24a86a6625f1', '693a3d97-11f0-57cc-a903-37df59dfdc95', 'c7433d48-bd48-5f82-ab7c-191590a453c0', 6, 6, 'ስለዚህ ሰማርያን በሜዳ እንደሚገኝ የድንጋይ ክምር፥ ወይን እንደሚተከልበትም ስፍራ አደርጋታለሁ፥ ድንጋዮችዋንም ወደ ሸለቆ እወረውራለሁ፥ መሠረቶችዋንም እገልጣለሁ።'),
  ('7054077d-13a3-562c-ad5d-a552fbcd1fcd', '693a3d97-11f0-57cc-a903-37df59dfdc95', 'c7433d48-bd48-5f82-ab7c-191590a453c0', 7, 7, 'የተቀረጹትም ምስሎችዋ ይደቅቃሉ፥ በግልሙትና ያገኘችው ዋጋ ሁሉ በእሳት ይቃጠላል፥ ጣዖታትዋንም ሁሉ አጠፋለሁ፥ በግልሙትና ዋጋ ሰበሰባቻቸው፥ ወደ ግልሙትናም ዋጋ ይመለሳሉና።'),
  ('ce7c80db-2011-5fbe-afb9-4fd463703657', '693a3d97-11f0-57cc-a903-37df59dfdc95', 'c7433d48-bd48-5f82-ab7c-191590a453c0', 8, 8, 'ስለዚህ ነገር ዋይ ብላ ታለቅሳለች፥ ባዶ እግርዋንና ዕራቁትዋን ሆና ትሄዳለች፥ እንደ ቀበሮ ታለቅሳለች፥ እንደ ሰጐንም ዋይ ትላለች፥'),
  ('a7d80dfb-8b16-5641-a8f7-cb5a29241ee9', '693a3d97-11f0-57cc-a903-37df59dfdc95', 'c7433d48-bd48-5f82-ab7c-191590a453c0', 9, 9, 'ቁስልዋ የማይፈወስ ነውና፥ እስከ ይሁዳም ደርሶአልና፥ ወደ ሕዝቤም በር ወደ ኢየሩሳሌም ቀርቦአልና።'),
  ('ef00d977-f1fc-5227-aafa-5e733c737710', '693a3d97-11f0-57cc-a903-37df59dfdc95', 'c7433d48-bd48-5f82-ab7c-191590a453c0', 10, 10, 'በጌት ላይ አታውሩ፥ በአኮ ላይ እንባን አታድርጉ፥ በቤትዓፍራ በትቢያ ላይ ተንከባለሉ።'),
  ('e33f7321-b4cd-50df-a489-f2ffdfb05602', '693a3d97-11f0-57cc-a903-37df59dfdc95', 'c7433d48-bd48-5f82-ab7c-191590a453c0', 11, 11, 'በሻፊር የምትቀመጪ ሆይ፥ በዕራቁትነትሽና በእፍረት እለፊ፥ በጸዓናን የምትቀመጠው አልወጣችም፥ የቤትኤጼል ልቅሶ ከእናንተ ዘንድ መኖሪያውን ይወስዳል።'),
  ('f51f048e-f58f-5772-af60-c879b333ea1d', '693a3d97-11f0-57cc-a903-37df59dfdc95', 'c7433d48-bd48-5f82-ab7c-191590a453c0', 12, 12, 'ክፉ ነገር ከእግዚአብሔር ዘንድ እስከ ኢየሩሳሌም በር ድረስ ወርዶአልና በማሮት የምትቀመጠው በጎነትን ትጠባበቃለች።'),
  ('73e1dca6-d24f-5ac8-a3c7-043a343fb883', '693a3d97-11f0-57cc-a903-37df59dfdc95', 'c7433d48-bd48-5f82-ab7c-191590a453c0', 13, 13, 'በለኪሶ የምትቀመጪ ሆይ፥ ሰረገላውን ለፈረስ እሰሪ፥ እርስዋ ለጽዮን ሴት ልጆች የኃጢአት መጀመሪያ ነበረች፥ የእስራኤል በደል በአንቺ ዘንድ ተገኝቶአልና።'),
  ('a62fa290-8909-5b37-a66d-b60b7906ec26', '693a3d97-11f0-57cc-a903-37df59dfdc95', 'c7433d48-bd48-5f82-ab7c-191590a453c0', 14, 14, 'ስለዚህ ትሎት ለሞሬሼትጌት ትሰጪአለሽ፥ የአክዚብ ቤቶች ለእስራኤል ነገሥታት አታላይ ይሆናሉ።'),
  ('81b8383c-0d18-5afc-a10b-8038895b4548', '693a3d97-11f0-57cc-a903-37df59dfdc95', 'c7433d48-bd48-5f82-ab7c-191590a453c0', 15, 15, 'በመሪሳ የምትቀመጪ ሆይ፥ ወራሽ አመጣብሻለሁ፥ የእስራኤል ክብር ወደ ዓዶላም ይመጣል።'),
  ('2470293a-9eb7-5438-af11-424a8da5a939', '693a3d97-11f0-57cc-a903-37df59dfdc95', 'c7433d48-bd48-5f82-ab7c-191590a453c0', 16, 16, 'ተማርከው ከአንቺ ዘንድ ወጥተዋልና ስለ ተድላሽ ልጆች ራስሽን ንጪ፥ ጠጕርሽንም ተቈረጪ፥ ቡሃነትሽንም እንደ ንስር አስፊ።'),
  ('bba0064d-a529-5c47-a532-aba81c0ea67a', 'fb10ce94-f154-5246-a10f-ba6e46f38bf0', 'c8dbd54f-c7f5-5303-a26d-2cac98bf1b12', 1, 1, 'በመኝታቸው ላይ በደልን ለሚያስቡ ክፋትንም ለሚያደርጉ ወዮላቸው! ኃይል በእጃቸው ነውና ሲነጋ ይፈጽሙታል።'),
  ('b2d22e9d-85af-5d33-aab2-197646a76094', 'fb10ce94-f154-5246-a10f-ba6e46f38bf0', 'c8dbd54f-c7f5-5303-a26d-2cac98bf1b12', 2, 2, 'በእርሻው ላይ ይመኛሉ፥ በግዴታም ይይዙታል፥ በቤቶችም ላይ ይመኛሉ፥ ይወስዱአቸውማል፥ ሰውንና ቤቱን፥ ሰውንና ርስቱንም ይነጥቃሉ።'),
  ('4e97336e-1d1a-5d52-a2a2-6cff157d66b6', 'fb10ce94-f154-5246-a10f-ba6e46f38bf0', 'c8dbd54f-c7f5-5303-a26d-2cac98bf1b12', 3, 3, 'ስለዚህ እግዚአብሔር እንዲህ ይላል፦ እነሆ፥ በዚህ ወገን ላይ በክፉ አስባለሁ፥ ከዚያም አንገታችሁን አታነሡም፥ ዘመኑም ክፉ ነውና ቀጥ ብላችሁ አትሄዱም።'),
  ('2c18aa53-ffa7-5315-ae71-dd3c0e19e769', 'fb10ce94-f154-5246-a10f-ba6e46f38bf0', 'c8dbd54f-c7f5-5303-a26d-2cac98bf1b12', 4, 4, 'በዚያ ቀን በምሳሌ ይመስሉባችኋል፥ በጽኑ ልቅሶም ያለቅሱላችኋል፥ እነርሱም፦ ፈጽመን ጠፍተናል፥ የሕዝቤን እድል ፈንታ ይሰፍራል፥ እርሱንም የሚከለክል የለም፥ እርሻችንን ለዓመፀኞች ይከፍላል ይላሉ።'),
  ('8fdefb3c-3499-56ca-a8d2-e24680d06af2', 'fb10ce94-f154-5246-a10f-ba6e46f38bf0', 'c8dbd54f-c7f5-5303-a26d-2cac98bf1b12', 5, 5, 'ስለዚህ በእግዚአብሔር ጉባኤ መካከል በዕጣ ገመድ የሚጥል አይኖርህም።'),
  ('fd084625-e274-5f57-ac12-de2860b7626c', 'fb10ce94-f154-5246-a10f-ba6e46f38bf0', 'c8dbd54f-c7f5-5303-a26d-2cac98bf1b12', 6, 6, 'ትንቢት አትናገሩ ብለው ይናገራሉ፥ በእነዚህ ላይ ትንቢት አይናገሩም፥ ስድብም አይርቅም።'),
  ('288fc302-360b-58a2-af65-8ad2bb6ba020', 'fb10ce94-f154-5246-a10f-ba6e46f38bf0', 'c8dbd54f-c7f5-5303-a26d-2cac98bf1b12', 7, 7, 'የያዕቆብ ቤት የተባልህ ሆይ፥ በውኑ የእግዚአብሔር መንፈስ የማይታገሥ ነውን? ወይስ ሥራው እንደዚያች ናትን? ቃሌስ በቅን ለሚሄድ በጎነት አያደርግምን?'),
  ('9591ce55-35d9-560f-acd2-e3725b362420', 'fb10ce94-f154-5246-a10f-ba6e46f38bf0', 'c8dbd54f-c7f5-5303-a26d-2cac98bf1b12', 8, 8, 'ነገር ግን ከቅርብ ጊዜ ጀምሮ ሕዝቤ እንደ ጠላት ሆኖ ተነሥቶአል፥ ቀሚስንና መጐናጸፊያን ገፈፋችሁ፥ ሳይፈሩም፥ የሚያልፉትን ከሰልፍ እንደሚመለሱ አደረጋችኋቸው።'),
  ('6d33c6d2-425b-530c-a74f-541d5ddcb361', 'fb10ce94-f154-5246-a10f-ba6e46f38bf0', 'c8dbd54f-c7f5-5303-a26d-2cac98bf1b12', 9, 9, 'የሕዝቤንም ሴቶች ከተሸለሙ ቤቶቻቸው አሳደዳችኋቸው፥ ከሕፃናቶቻቸውም ክብሬን ለዘላለም ወሰዳችሁ።'),
  ('7c830721-a388-5f5a-ab51-8bb2904470e1', 'fb10ce94-f154-5246-a10f-ba6e46f38bf0', 'c8dbd54f-c7f5-5303-a26d-2cac98bf1b12', 10, 10, 'በዚህ ዕረፍት የላችሁምና ተነሥታችሁ ሂዱ፥ በርኵሰት ምክንያት ክፉ ጥፋት ታጠፋችኋለች።'),
  ('e68b01bb-569d-56e1-a543-fc7ec0146d14', 'fb10ce94-f154-5246-a10f-ba6e46f38bf0', 'c8dbd54f-c7f5-5303-a26d-2cac98bf1b12', 11, 11, 'ነፋስንም ተከትሎ፦ ስለ ወይን ጠጅና ስለ ስካር ትንቢት እናገርልሃለሁ ብሎ ሐሰትን የሚናገር ሰው ቢኖር እርሱ ለዚህ ሕዝብ ነቢይ ይሆናል።'),
  ('dc5da61d-3e26-59f8-a33a-2d2e885f62af', 'fb10ce94-f154-5246-a10f-ba6e46f38bf0', 'c8dbd54f-c7f5-5303-a26d-2cac98bf1b12', 12, 12, 'ያዕቆብ ሆይ፥ ሁልንተናህን ፈጽሞ እሰበስባለሁ፥ የእስራኤልንም ቅሬታ ፈጽሞ አከማቻለሁ፥ እንደ ባሶራ በጎችና እንደ መንጋ በማሰማርያቸው ውስጥ በአንድነት አኖራቸዋለሁ፥ ከሰው ብዛት የተነሣ ድምፃቸውን ያሰማሉ።'),
  ('2d884b6c-f47c-5cd0-ac73-73fa5b1c2201', 'fb10ce94-f154-5246-a10f-ba6e46f38bf0', 'c8dbd54f-c7f5-5303-a26d-2cac98bf1b12', 13, 13, 'ሰባሪው በፊታቸው ወጥቶአል፥ እነርሱም ሰብረው ወደ በሩ አልፈዋል፥ በእርሱም በኩል ወጥተዋል፥ ንጉሣቸውም በፊታቸው አልፎአል፥ እግዚአብሔርም በራሳቸው ላይ ነው።'),
  ('b3de093e-c04a-5382-a031-5c7ad69143a7', '97d3b956-5889-50e2-a60e-2695a1a29171', '9cd5a126-0ba5-5a0b-ae5c-f9ed56d2eec1', 1, 1, 'እንዲህም አልሁ፦ የያዕቆብ አለቆችና የእስራኤል ቤት ገዦች ሆይ፥ እባካችሁ ስሙኝ፥ ፍርድን ታውቁ ዘንድ አይገባችሁምን?'),
  ('78e12a08-3a95-522b-a1eb-c5a75143b215', '97d3b956-5889-50e2-a60e-2695a1a29171', '9cd5a126-0ba5-5a0b-ae5c-f9ed56d2eec1', 2, 2, 'መልካሙን ጠልታችኋል፥ ክፉውንም ወድዳችኋል፥ ቁርበታቸውን ገፍፋችኋቸዋል፥ ሥጋቸውንም ከአጥንታቸው ለያይታችኋል፥'),
  ('b264cc31-3388-5126-a8ab-4479dab615fc', '97d3b956-5889-50e2-a60e-2695a1a29171', '9cd5a126-0ba5-5a0b-ae5c-f9ed56d2eec1', 3, 3, 'የሕዝቤን ሥጋ በልታችኋል፥ ቁርበታቸውንም ገፍፋችኋቸዋል፥ አጥንታቸውንም ሰብራችኋል፥ ለአፍላል እንደሚሆን ሥጋ ለድስትም እንደሚሆን ሙዳ ቈራረጣችኋቸው።'),
  ('e178aacd-01d0-51d0-ad3c-3a118b3f0a87', '97d3b956-5889-50e2-a60e-2695a1a29171', '9cd5a126-0ba5-5a0b-ae5c-f9ed56d2eec1', 4, 4, 'የዚያን ጊዜ ወደ እግዚአብሔር ይጮኻሉ፥ እርሱም አይሰማቸውም፥ ሥራቸውንም ክፉ አድርገዋልና በዚያን ጊዜ ፊቱን ከእነርሱ ይሰውራል።'),
  ('5e04f348-2851-5770-a092-62caeffbf47b', '97d3b956-5889-50e2-a60e-2695a1a29171', '9cd5a126-0ba5-5a0b-ae5c-f9ed56d2eec1', 5, 5, 'እግዚአብሔር ሕዝቤን ስለሚያስቱ ነቢያት እንዲህ ይላል፥ በጥርሳቸው ሲነክሱ በሰላም ይሰብካሉ፥ በአፋቸው ግን አንዳች በማይሰጥ ሰው ላይ ሰልፍን ያስቡበታል።'),
  ('d0d943a8-9296-5df1-a723-4edaae870942', '97d3b956-5889-50e2-a60e-2695a1a29171', '9cd5a126-0ba5-5a0b-ae5c-f9ed56d2eec1', 6, 6, 'ስለዚህ ሌሊት ይሆንባችኋል እንጂ ራእይ አይሆንላችሁም፥ ጨለማም ይሆንባችኋል እንጂ አታምዋርቱም፥ ፀሐይም በነቢያት ላይ ትገባለች፥ ቀኑም ይጠቁርባቸዋል።'),
  ('6059faa4-9423-5e57-aea7-88fa8324433a', '97d3b956-5889-50e2-a60e-2695a1a29171', '9cd5a126-0ba5-5a0b-ae5c-f9ed56d2eec1', 7, 7, 'ከእግዚአብሔርም ዘንድ መልስ የለምና ባለ ራእዩቹ ያፍራሉ፥ ምዋርተኞችም ይዋረዳሉ፥ ሁሉም ከንፈራቸውን ይሸፍናሉ።'),
  ('f8bd8eb1-8f38-5ba5-a3cc-2b5bf7cab75f', '97d3b956-5889-50e2-a60e-2695a1a29171', '9cd5a126-0ba5-5a0b-ae5c-f9ed56d2eec1', 8, 8, 'እኔ ግን በደሉን ለያዕቆብ፥ ኃጢአቱንም ለእስራኤል እነግር ዘንድ በእግዚአብሔር መንፈስ ኃይልንና ፍርድን ብርታትንም ተሞልቻለሁ።'),
  ('eeb0d8c6-265a-5279-a9dd-263d28d6c233', '97d3b956-5889-50e2-a60e-2695a1a29171', '9cd5a126-0ba5-5a0b-ae5c-f9ed56d2eec1', 9, 9, 'ፍርድን የምትጠሉ ቅን ነገርንም ሁሉ የምታጣምሙ እናንተ የያዕቆብ ቤት አለቆችና የእስራኤል ቤት ገዦች ሆይ፥ እባካችሁ ይህን ስሙ።'),
  ('11bd116f-511c-505f-a5bc-dadae8e30712', '97d3b956-5889-50e2-a60e-2695a1a29171', '9cd5a126-0ba5-5a0b-ae5c-f9ed56d2eec1', 10, 10, 'ጽዮንን በደም፥ ኢየሩሳሌምንም በኃጢአት ይሠራሉ።'),
  ('fa681317-0b3b-5b8f-a03a-2190ba7344f0', '97d3b956-5889-50e2-a60e-2695a1a29171', '9cd5a126-0ba5-5a0b-ae5c-f9ed56d2eec1', 11, 11, 'አለቆችዋ በጉቦ ይፈርዳሉ፥ ካህናቶችዋም በዋጋ ያስተምራሉ፥ ነቢያቶችዋም በገንዘብ ያምዋርታሉ፥ ከዚህም ጋር፦ እግዚአብሔር በመካከላችን አይደለምን? ክፉ ነገር ምንም አይመጣብንም እያሉ በእግዚአብሔር ይታመናሉ።'),
  ('de3110c7-65ca-5d8a-ae6b-77e4a4f83add', '97d3b956-5889-50e2-a60e-2695a1a29171', '9cd5a126-0ba5-5a0b-ae5c-f9ed56d2eec1', 12, 12, 'ስለዚህ በእናንተ ምክንያት ጽዮን እንደ እርሻ ትታረሳለች፥ ኢየሩሳሌም የድንጋይ ክምር ትሆናለች፥ የቤቱም ተራራ እንደ ዱር ከፍታ ይሆናል።'),
  ('4e49c114-3d8c-5caa-a322-3581349797cd', '16ff6209-5256-578b-a87c-d485a91b7096', '7423c17b-1b4d-5eaf-a514-a05f2ffb0ff9', 1, 1, 'በመጨረሻውም ዘመን የእግዚአብሔር ቤት ተራራ በተራሮች ራስ ላይ ጸንቶ ይቆማል፥ ከኮረብቶችም በላይ ከፍ ከፍ ይላል፥ አሕዛብም ወደ እርሱ ይጐርፋሉ።'),
  ('8c5327fc-97e8-5d5a-a9d0-702c833ec1ab', '16ff6209-5256-578b-a87c-d485a91b7096', '7423c17b-1b4d-5eaf-a514-a05f2ffb0ff9', 2, 2, 'ከጽዮን ሕግ፥ ከኢየሩሳሌምም የእግዚአብሔር ቃል ይወጣልና ብዙዎች አሕዛብ ሄደው፦ ኑ፥ ወደ እግዚአብሔር ተራራ፥ ወደ ያዕቆብ አምላክ ቤት እንውጣ፥ እርሱም መንገዱን ያስተምረናል፥ በፍለጋውም እንሄዳለን ይላሉ።'),
  ('fa356969-5911-52de-a588-cbd4867445ec', '16ff6209-5256-578b-a87c-d485a91b7096', '7423c17b-1b4d-5eaf-a514-a05f2ffb0ff9', 3, 3, 'በብዙዎችም አሕዛብ መካከል ይፈርዳል፥ በሩቅም ባሉ በብርቱዎች አሕዛብ ላይ ይበይናል፥ ሰይፋቸውንም ማረሻ፥ ጦራቸውንም ማጭድ ለማድረግ ይቀጠቅጣሉ፥ ሕዝብም በሕዝብ ላይ ሰይፍ አያነሣም ከእንግዲህም ወዲህ ሰልፍ አይማሩም።'),
  ('c7277f73-24ea-590d-a2c0-69728ee1e269', '16ff6209-5256-578b-a87c-d485a91b7096', '7423c17b-1b4d-5eaf-a514-a05f2ffb0ff9', 4, 4, 'የሠራዊት ጌታ የእግዚአብሔር አፍም ተናግሮአልና ሰው እያንዳንዱ ከወይኑና ከበለሱ በታች ይቀመጣል፥ የሚያስፈራውም የለም።'),
  ('9b473a2c-60b3-59ef-ae93-32575f03a99a', '16ff6209-5256-578b-a87c-d485a91b7096', '7423c17b-1b4d-5eaf-a514-a05f2ffb0ff9', 5, 5, 'ሕዝብም ሁሉ እያንዳንዱ በየአምላኩ ስም ይሄዳል፥ እኛም በአምላካችን በእግዚአብሔር ስም ለዘላለም እንሄዳለን።'),
  ('defe78a7-8947-580b-a41c-824e79047ce9', '16ff6209-5256-578b-a87c-d485a91b7096', '7423c17b-1b4d-5eaf-a514-a05f2ffb0ff9', 6, 6, 'በዚያ ቀን አንካሳይቱን እሰበስባለሁ፥ ይላል እግዚአብሔር፥ የባከነችውንና ያስጨነቅኋትንም አከማቻለሁ፥'),
  ('2ca22a8e-8599-52b2-a1dc-d763d1cff36e', '16ff6209-5256-578b-a87c-d485a91b7096', '7423c17b-1b4d-5eaf-a514-a05f2ffb0ff9', 7, 7, 'አንካሳይቱንም ለቅሬታ፥ ወደ ሩቅም የተጣለችውን ለብርቱ ሕዝብ አደርጋታለሁ፥ ከዚያም ወዲያ እስከ ዘላለም ድረስ እግዚአብሔር በጽዮን ተራራ በእነርሱ ላይ ይነግሣል።'),
  ('333836dc-c116-5e33-a4f7-e8aa5a05e2a1', '16ff6209-5256-578b-a87c-d485a91b7096', '7423c17b-1b4d-5eaf-a514-a05f2ffb0ff9', 8, 8, 'አንተም የመንጋ ግንብ ሆይ፥ የጽዮን ሴት ልጅ አምባ፥ ወደ አንተ ትመጣለች፥ የቀደመችው ግዛት፥ የኢየሩሳሌም ሴት ልጅ መንግሥት ትደርሳለች።'),
  ('0d60e013-af37-52ad-a25d-5026c166d16a', '16ff6209-5256-578b-a87c-d485a91b7096', '7423c17b-1b4d-5eaf-a514-a05f2ffb0ff9', 9, 9, 'አሁንስ ለምን ትጮኺአለሽ? እንደምትወልድ ሴት ምጥ የደረሰብሽ፥ ንጉሥ ስለሌለሽ ነውን? ወይስ መካሪ ስለ ጠፋብሽ ነውን?'),
  ('51f3a82f-61fd-5f92-a2c4-c6c432bcfd14', '16ff6209-5256-578b-a87c-d485a91b7096', '7423c17b-1b4d-5eaf-a514-a05f2ffb0ff9', 10, 10, 'የጽዮን ልጅ ሆይ፥ እንደምትወልድ ሴት አምጠሽ ውለጂ፥ አሁን ከከተማ ትወጫለሽና፥ በሜዳም ትቀመጫለሽ፥ ወደ ባቢሎንም ትደርሻለሽ፥ በዚያም ያድንሻል፥ በዚያም እግዚአብሔር ከጠላቶችሽ እጅ ይቤዥሻል።'),
  ('9eaedfbc-c795-5d62-acd0-0e34126c1e89', '16ff6209-5256-578b-a87c-d485a91b7096', '7423c17b-1b4d-5eaf-a514-a05f2ffb0ff9', 11, 11, 'አሁንም፦ ርኩስ ትሁን፥ ዓይናችንም በጽዮን ላይ ይይ የሚሉ ብዙ አሕዛብ በአንቺ ላይ ተሰብስበዋል።'),
  ('888cbfb7-7bc8-58fc-ab23-4dc711b2ad32', '16ff6209-5256-578b-a87c-d485a91b7096', '7423c17b-1b4d-5eaf-a514-a05f2ffb0ff9', 12, 12, 'ነገር ግን የእግዚአብሔርን አሳብ አያውቁም፥ ምክሩንም አያስተውሉም፥ እንደ ነዶ ወደ አውድማ አከማችቶአቸዋልና።'),
  ('47f7d4b2-8a1b-54f1-adcb-7e9f9d9f6a31', '16ff6209-5256-578b-a87c-d485a91b7096', '7423c17b-1b4d-5eaf-a514-a05f2ffb0ff9', 13, 13, 'የጽዮን ልጅ ሆይ፥ ቀንድሽን ብረት፥ ጥፍርሽንም ናስ አደርጋለሁና ተነሺ አሂጂ፥ ብዙ አሕዛብንም ታደቅቂአለሽ፥ ትርፋቸውንም ለእግዚአብሔር፥ ሀብታቸውንም ለምድር ሁሉ ጌታ ትቀድሻለሽ።'),
  ('65213222-eb6d-5775-a384-d41ca4e7dbb9', '826560c9-7a12-518d-ae84-f5151eea7989', 'b0a5f72f-0fa1-5585-a754-0709519373e6', 1, 1, 'የጭፍሮች ሴት ልጅ ሆይ፥ ጭፍሮችሽን አሁን ሰብስቢ፥ ከብቦ አስጨንቆናል፥ የእስራኤልን ፈራጅ ጕንጩን በበትር ይመታሉ።'),
  ('4486fc63-63f5-568a-aa62-e1bc68c76a69', '826560c9-7a12-518d-ae84-f5151eea7989', 'b0a5f72f-0fa1-5585-a754-0709519373e6', 2, 2, 'አንቺም ቤተ ልሔም ኤፍራታ ሆይ፥ አንቺ በይሁዳ አእላፋት መካከል ትሆኚ ዘንድ ታናሽ ነሽ፥ ከአንቺ ግን አወጣጡ ከቀድሞ ጀምሮ ከዘላለም የሆነ፥ በእስራኤልም ላይ ገዥ የሚሆን ይወጣልኛል።'),
  ('703fd38c-3436-5c77-a13c-8a20455378a6', '826560c9-7a12-518d-ae84-f5151eea7989', 'b0a5f72f-0fa1-5585-a754-0709519373e6', 3, 3, 'ስለዚህ ወላጂቱ እስከምትወልድበት ጊዜ ድረስ አሳልፎ ይሰጣቸዋል፥ የቀሩትም ወንድሞቹ ወደ እስራኤል ልጆች ይመለሳሉ።'),
  ('14727c36-adbc-5e95-aae6-1f1beeaf2df3', '826560c9-7a12-518d-ae84-f5151eea7989', 'b0a5f72f-0fa1-5585-a754-0709519373e6', 4, 4, 'እርሱም ይቆማል፥ በእግዚአብሔርም ኃይል በአምላኩ በእግዚአብሔር ስም ግርማ መንጋውን ይጠብቃል፥ እነርሱም ይኖራሉ፥ እርሱ አሁን እስከ ምድር ዳርቻ ድረስ ታላቅ ይሆናልና።'),
  ('ed5e1fc2-deb7-59cb-ab41-27b4b0e99b40', '826560c9-7a12-518d-ae84-f5151eea7989', 'b0a5f72f-0fa1-5585-a754-0709519373e6', 5, 5, 'ይህም ለሰላም ይሆናል፥ አሦራዊውም ወደ አገራችን በገባ ጊዜ፥ ምድራችንንም በረገጠ ጊዜ ሰባት እረኞችና ስምንት አለቆች እናስነሣበታለን።'),
  ('cc83ff2a-18f3-580c-a102-ed2a2e639ca3', '826560c9-7a12-518d-ae84-f5151eea7989', 'b0a5f72f-0fa1-5585-a754-0709519373e6', 6, 6, 'የአሦርንም አገር በሰይፍ፥ የናምሩድንም አገር በመግቢያው ውስጥ ያፈርሳሉ፥ አሦራዊውም ወደ አገራችን በገባ ጊዜ፥ ዳርቾቻችንንም በረገጠ ጊዜ እርሱ ይታደገናል።'),
  ('909faa04-6536-599b-a2e3-03cfff271108', '826560c9-7a12-518d-ae84-f5151eea7989', 'b0a5f72f-0fa1-5585-a754-0709519373e6', 7, 7, 'የያዕቆብም ቅሬታ በብዙ አሕዛብ መካከል ከእግዚአብሔር ዘንድ እንደሚወርድ ጠል፥ በሣር ላይ እንደሚወርድ ካፊያ፥ ሰውንም እንደማይጠብቅ፥ የሰውንም ልጆች ተስፋ እንደማያደርግ ይሆናል።'),
  ('a5a93025-2715-58a8-a9df-bd2f096807f1', '826560c9-7a12-518d-ae84-f5151eea7989', 'b0a5f72f-0fa1-5585-a754-0709519373e6', 8, 8, 'በዱር አራዊትም መካከል እንዳለ አንበሳ፥ በበጎች መንጋም መካከል አልፎ እንደሚረግጥ፥ የሚታደግም ሳይኖር እንደሚነጥቅ እንደ አንበሳ ደቦል፥ እንዲሁ የያዕቆብ ቅሬታ በአሕዛብና በብዙ ወገኖች መካከል ይሆናል።'),
  ('140a506c-bfd5-5d2e-a5e1-3c44879c4c94', '826560c9-7a12-518d-ae84-f5151eea7989', 'b0a5f72f-0fa1-5585-a754-0709519373e6', 9, 9, 'እጅህ በጠላቶችህ ላይ ከፍ ከፍ ትበል፥ ጠላቶችህም ሁሉ ይጥፉ።'),
  ('1ce9c62b-c893-5035-a980-2bc6f68b18bd', '826560c9-7a12-518d-ae84-f5151eea7989', 'b0a5f72f-0fa1-5585-a754-0709519373e6', 10, 10, 'በዚያም ቀን ፈረሶችህን ከመካከልህ አጠፋለሁ፥ ሰረገሎችህንም እሰብራለሁ፥ ይላል እግዚአብሔር፥'),
  ('3a181e04-b4c5-5e94-a1b3-bd8bf2a86dc7', '826560c9-7a12-518d-ae84-f5151eea7989', 'b0a5f72f-0fa1-5585-a754-0709519373e6', 11, 11, 'የምድርህንም ከተሞች አጠፋለሁ፥ ምሽጎችህንም ሁሉ አፈርሳለሁ፥'),
  ('da1f2349-e810-5fc0-af07-d4bb717f21b6', '826560c9-7a12-518d-ae84-f5151eea7989', 'b0a5f72f-0fa1-5585-a754-0709519373e6', 12, 12, 'መተትንም ከእጅህ አጠፋለሁ፥ ምዋርተኞችም ከእንግዲህ ወዲህ አይሆኑልህም፥'),
  ('89924b27-6822-5aa0-a867-0c1c044d2ea8', '826560c9-7a12-518d-ae84-f5151eea7989', 'b0a5f72f-0fa1-5585-a754-0709519373e6', 13, 13, 'የተቀረጹትን ምስሎችህንና ሐውልቶችህን ከመካከልህ አጠፋለሁ፥ ለእጅህም ሥራ ከእንግዲህ ወዲህ አትሰግድም፥'),
  ('5fa3f960-ae78-5f48-a565-f785a79ac3c1', '826560c9-7a12-518d-ae84-f5151eea7989', 'b0a5f72f-0fa1-5585-a754-0709519373e6', 14, 14, 'የማምለኪያ ዐፀዶችህንም ከመካከልህ እነቅላለሁ፥ ከተሞችህንም አፈርሳለሁ።'),
  ('0b115785-b53e-58b7-ac2c-903238ffba7a', '826560c9-7a12-518d-ae84-f5151eea7989', 'b0a5f72f-0fa1-5585-a754-0709519373e6', 15, 15, 'ባልሰሙም አሕዛብ ላይ በቍጣና በመዓት እበቀላለሁ።'),
  ('17b3d89a-f965-5e52-aed6-ceeea4432668', 'dc4df8b8-9e61-5b56-a04a-01551d04b74e', 'c0bdc04f-c489-5ed5-a8e3-3c58724115ed', 1, 1, 'አሁን፦ ተነሣ፥ በተራሮችም ፊት ተፋረድ፥ ኮረብቶችም ቃልህን ይስሙ ብሎ እግዚአብሔር የሚለውን ስሙ።'),
  ('99f091f5-ceab-54ba-a0f2-c2ddd447ca0b', 'dc4df8b8-9e61-5b56-a04a-01551d04b74e', 'c0bdc04f-c489-5ed5-a8e3-3c58724115ed', 2, 2, 'ተራሮች ሆይ፥ ጠንካሮች የምድር መሠረቶችም ሆይ፥ እግዚአብሔር ከሕዝቡ ጋር ክርክር አለውና፥ ከእስራኤልም ጋር ይፋረዳልና የእግዚአብሔርን ክርክር ስሙ።'),
  ('0c320b9e-1d3d-541e-a12f-e70e20df44f8', 'dc4df8b8-9e61-5b56-a04a-01551d04b74e', 'c0bdc04f-c489-5ed5-a8e3-3c58724115ed', 3, 3, 'ሕዝቤ ሆይ፥ ምን አድርጌለሁ? በምንስ አድክሜሃለሁ? መስክርብኝ።'),
  ('e7cc61aa-f3eb-5fff-a363-62236c0c07b5', 'dc4df8b8-9e61-5b56-a04a-01551d04b74e', 'c0bdc04f-c489-5ed5-a8e3-3c58724115ed', 4, 4, 'ከግብጽ ምድር አውጥቼሃለሁ፥ ከባርነት ቤትም ተቤዥቼሃለሁ፥ በፊትህም ሙሴንና አሮንን ማርያምንም ልኬልህ ነበር።'),
  ('505fb7be-073c-55e4-aea2-b1818c0d58c0', 'dc4df8b8-9e61-5b56-a04a-01551d04b74e', 'c0bdc04f-c489-5ed5-a8e3-3c58724115ed', 5, 5, 'ሕዝቤ ሆይ፥ የሞዓብ ንጉሥ ባላቅ የመከረውን፥ የቢዖርም ልጅ በለዓም የመለሰለትን አሁን አስብ፥ የእግዚአብሔርንም የጽድቅ ሥራ ታውቅ ዘንድ ከሰጢም ጀምሮ እስከ ጌልገላ ድረስ አስብ።'),
  ('26159ef9-ddc8-5e90-a35f-6336b1264217', 'dc4df8b8-9e61-5b56-a04a-01551d04b74e', 'c0bdc04f-c489-5ed5-a8e3-3c58724115ed', 6, 6, 'ምን ይዤ ወደ እግዚአብሔር ፊት ልምጣና በልዑል አምላክ ፊት ልስገድ? የሚቃጠለውን መሥዋዕትና የአንዱን ዓመት ጥጃ ይዤ በፊቱ ልምጣን?'),
  ('2ccc333c-bcd1-52a3-a8e0-814f806c61b8', 'dc4df8b8-9e61-5b56-a04a-01551d04b74e', 'c0bdc04f-c489-5ed5-a8e3-3c58724115ed', 7, 7, 'እግዚአብሔርስ በሺህ አውራ በጎች ወይስ በእልፍ የዘይት ፈሳሾች ደስ ይለዋልን? ወይስ የበኵር ልጄን ስለ በደሌ፥ የሆዴንም ፍሬ ስለ ነፍሴ ኃጢአት እሰጣለሁን?'),
  ('859a400f-ef93-5bb4-ac78-9a189bd30f4a', 'dc4df8b8-9e61-5b56-a04a-01551d04b74e', 'c0bdc04f-c489-5ed5-a8e3-3c58724115ed', 8, 8, 'ሰው ሆይ፥ መልካሙን ነግሮሃል፥ እግዚአብሔርም ከአንተ ዘንድ የሚሻው ምንድር ነው? ፍርድን ታደርግ ዘንድ፥ ምሕረትንም ትወድድ ዘንድ፥ ከአምላክህም ጋር በትሕትና ትሄድ ዘንድ አይደለምን?'),
  ('630813ad-9fd6-5975-aa3c-da1bf03ae9dd', 'dc4df8b8-9e61-5b56-a04a-01551d04b74e', 'c0bdc04f-c489-5ed5-a8e3-3c58724115ed', 9, 9, 'የእግዚአብሔር ድምፅ ከተማይቱን ይጠራታል፥ ስምህን መፍራት ጥበብ ነው፥ የመቅሠፍትን በትር፥ እርሱንም ያዘጋጀ ማን እንደ ሆነ ስሙ።'),
  ('bbbf0d93-b420-576b-aaa1-7ea521735bd3', 'dc4df8b8-9e61-5b56-a04a-01551d04b74e', 'c0bdc04f-c489-5ed5-a8e3-3c58724115ed', 10, 10, 'በውኑ በኃጢአተኛ ቤት የኃጢአት መዝገብ፥ የተጸየፈውም ውሸተኛ መስፈሪያ ገና አለ ይሆን?'),
  ('652c481e-f096-5085-a4cf-64f62fdf1972', 'dc4df8b8-9e61-5b56-a04a-01551d04b74e', 'c0bdc04f-c489-5ed5-a8e3-3c58724115ed', 11, 11, 'በአባይ ሚዛንና በከረጢት ባለ በተንኰል መመዘኛ ንጹሕ እሆናለሁን?'),
  ('753ee989-6ddd-55f2-acb5-9f68a100744e', 'dc4df8b8-9e61-5b56-a04a-01551d04b74e', 'c0bdc04f-c489-5ed5-a8e3-3c58724115ed', 12, 12, 'ባለ ጠጎችዋን ግፍ ሞልቶባቸዋል፥ በእርስዋም የሚኖሩ በሐሰት ተናግረዋል፥ ምላሳቸውም በአፋቸው ውስጥ ተንኰለኛ ነው።'),
  ('fc935d42-22c8-553d-a97d-4b3385ef4305', 'dc4df8b8-9e61-5b56-a04a-01551d04b74e', 'c0bdc04f-c489-5ed5-a8e3-3c58724115ed', 13, 13, 'ስለዚህ እኔ ደግሞ በክፉ ቍስል መታሁህ፥ ስለ ኃጢአትህም አፈረስሁህ።'),
  ('86637a2b-fe0e-5368-ae48-13cc2282ca45', 'dc4df8b8-9e61-5b56-a04a-01551d04b74e', 'c0bdc04f-c489-5ed5-a8e3-3c58724115ed', 14, 14, 'ትበላለህ፥ ነገር ግን አትጠግብም፥ ችጋርህም በመካከልህ ይሆናል፥ ትወስዳለህ፥ ነገር ግን አታድንም፥ የምታድነውንም ለሰይፍ እሰጣለሁ።'),
  ('6cc85873-53ef-5276-a0fe-dd0c4c841fb0', 'dc4df8b8-9e61-5b56-a04a-01551d04b74e', 'c0bdc04f-c489-5ed5-a8e3-3c58724115ed', 15, 15, 'ትዘራለህ፥ ነገር ግን አታጭድም፥ ወይራውንም ትጨምቃለህ፥ ነገር ግን ዘይቱን አትቀባም፥ ወይኑንም ትጨምቃለህ፥ ነገር ግን የወይን ጠጁን አትጠጣም።'),
  ('7ba81c53-6fc7-5408-a57c-36c6090b3168', 'dc4df8b8-9e61-5b56-a04a-01551d04b74e', 'c0bdc04f-c489-5ed5-a8e3-3c58724115ed', 16, 16, 'አንተን ለጥፋት፥ በእርስዋም የሚኖሩትን ለማፍዋጫ እሰጥ ዘንድ የዘንበሪን ሥርዓትና የአክዓብን ቤት ሥራ ሁሉ ጠብቃችኋል፥ በምክራቸውም ሄዳችኋል፥ የሕዝቤንም ስድብ ትሸከማላችሁ።'),
  ('ae4ccea6-34fd-581b-a5c0-f5cc38e86116', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 1, 1, 'የዛፍ ፍሬና የወይን ፍሬ ከተለቀሙ በኋላ እንደ ቀረው ቃርሚያ ሆኛለሁና ወዮልኝ! መብል የሚሆን ዘለላ፥ ነፍሴም የተመኘችው በመጀመሪያ የበሰለው በለስ የለም።'),
  ('6b52fcf4-1d49-579e-a7f3-d3e4c74cac2e', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 2, 2, 'ደግ ሰው ከምድር ጠፍቶአል፥ በሰውም መካከል ቅን የለም፥ ሁሉ ደምን ለማፍሰስ ያደባሉ፥ ሰውም ሁሉ ወንድሙን በመረብ ለመያዝ ይከታተለዋል።'),
  ('e4f87f3c-3e53-5101-a09e-bd461a83a3e1', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 3, 3, 'እጆቻቸውን ለክፋት ያነሣሉ፥ አለቃውና ፈራጁ ጉቦን ይፈልጋሉ፥ ትልቁም ሰው እንደ ነፍሱ ምኞት ይናገራል፥ እንዲሁም ክፋትን ይጐነጕናሉ።'),
  ('63c1e9a3-bbd4-5e56-ae82-588b544f50c8', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 4, 4, 'ከእነርሱም ሁሉ የተሻለው እርሱ እንደ አሜከላ ነው፥ ከሁሉም ቅን የሆነው እንደ ኵርንችት ነው፥ ጠባቆችህ የሚጐበኙበት ቀን መጥቶአል፥ አሁን ይሸበራሉ።'),
  ('8a6f5dfa-907a-5e17-ac5b-6a4ff7a3c0d9', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 5, 5, 'ባልንጀራን አትመኑ፥ በወዳጅም አትታመኑ፥ የአፍህን ደጅ በብብትህ ከምትተኛው ጠብቅ።'),
  ('1042af7b-5c36-55df-afa9-cd025afb44fa', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 6, 6, 'ወንድ ልጅ አባቱን ይንቃልና፥ ሴት ልጅ በእናትዋ ላይ፥ ምራቲቱም በአማትዋ ላይ ትነሣለችና፥ የሰው ጠላቶች የቤቱ ሰዎች ናቸውና።'),
  ('384f926a-c874-51fa-a010-13c271d13ad2', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 7, 7, 'እኔ ግን ወደ እግዚአብሔር እመለከታለሁ፥ የመድኃኒቴንም አምላክ ተስፋ አደርጋለሁ፥ አምላኬም ይሰማኛል።'),
  ('5a79cffe-2ed4-5869-afa2-0efbf75c119f', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 8, 8, 'ጠላቴ ሆይ፥ ብወድቅ እነሣለሁና፥ በጨለማም ብቀመጥ እግዚአብሔር ብርሃን ይሆንልኛልና በእኔ ላይ ደስ አይበልሽ።'),
  ('9de2f416-2429-505d-ab42-da0590790aa6', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 9, 9, 'በእግዚአብሔር ላይ ኃጢአት ሠርቻለሁና እስኪምዋገትልኝ ድረስ፥ ፍርድን ለእኔ እስኪያደርግ ድረስ ቍጣውን እታገሣለሁ። ወደ ብርሃን ያወጣኛል፥ ጽድቅንም አያለሁ።'),
  ('7555e278-33b1-579a-adfc-d34f97b40d2f', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 10, 10, 'ጠላቴም ታያለች፥ እኔንም፦ አምላክህ እግዚአብሔር ወዴት ነው? ያለች በእፍረት ትከደናለች።'),
  ('16f28173-8aa3-57d1-aae6-987389d37879', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 11, 11, 'ዓይኖቼ ይመለከቱአታል፥ አሁን እንደ መንገድ ጭቃ ትረገጣለች። ቅጥርሽ በሚሠራበት በዚያ ቀን ድንበርሽ ትስፋፋለች።'),
  ('59791fea-df16-58a5-af9c-1edf60c2bd54', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 12, 12, 'በዚያ ቀን ከአሦርና ከግብጽ ከተሞች፥ ከግብጽ እስከ ወንዙ፥ ከባሕርም እስከ ባሕር፥ ከተራራም እስከ ተራራ ድረስ ወደ አንቺ ይመጣሉ።'),
  ('8b5cd582-7b52-59e1-afaf-afd1ad64754a', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 13, 13, 'ምድሪቱ ግን በሚኖሩባት በሥራቸው ፍሬ ምክንያት ባድማ ትሆናለች።'),
  ('f82de1d3-a95f-5d37-a4ad-81695b478523', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 14, 14, 'በቀርሜሎስ መካከል ባለው ዱር ብቻቸውን የተቀመጡት ሰዎችህ፥ የርስትህን በጎች፥ በበትርህ አግድ፥ እንደ ቀደመውም ዘመን በበሳንና በገለዓድ ይሰማሩ።'),
  ('06712cb6-12af-5c58-a555-4c821fec5d24', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 15, 15, 'ከግብጽ ምድር እንደ ወጣህበት ዘመን ተአምራትን አሳያቸዋለሁ።'),
  ('b2098a37-f375-5d36-a131-ddcc10f64550', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 16, 16, 'አሕዛብ አይተው በጕልበታቸው ሁሉ ያፍራሉ፥ እጃቸውን በአፋቸው ላይ ያኖራሉ፥ ጆሮአቸውም ትደነቍራለች፥ እንደ እባብም መሬት ይልሳሉ፥'),
  ('b075af1f-2b2b-595a-a5b8-3949759188e7', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 17, 17, 'እንደ ምድርም ተንቀሳቃሾች እየተንቀጠቀጡ ከግንባቸው ይመጣሉ፥ ፈርተውም ወደ አምላካችን ወደ እግዚአብሔር ይመጣሉ፥ ስለ አንተም ይፈራሉ።'),
  ('4e3d0ace-324e-5e2b-a955-b89e5db98da8', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 18, 18, 'በደልን ይቅር የሚል፥ የርስቱንም ቅሬታ ዓመፅ የሚያሳልፍ እንደ አንተ ያለ አምላክ ማን ነው? ምሕረትን ይወድዳልና ቍጣውን ለዘላለም አይጠብቅም።'),
  ('21e6ab27-cafb-5720-ae32-c1e621a3e5d1', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 19, 19, 'ተመልሶ ይምረናል፥ ክፋታችንንም ይጠቀጥቃል፥ ኃጢአታችንንም በባሕሩ ጥልቅ ይጥለዋል።'),
  ('e4bf0d6e-ccae-5bc5-a8cb-e4affe886417', 'c956a851-00ab-590f-aa86-76da18795268', 'd0a887a9-ff88-5949-a3ce-8d0197cbf726', 20, 20, 'ከቀድሞ ዘመን ጀምረህ ለአባቶቻችን የማልህላቸውን እውነት ለያዕቆብ፥ ምሕረትንም ለአብርሃም ታደርጋለህ።'),
  ('7b974b4e-9157-5631-a4ee-19db5036fb2e', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 1, 1, 'ወደ ባቱኤል ልጅ ወደ ኢዮኤል የመጣው የእግዚአብሔር ቃል ይህ ነው።'),
  ('fe2a8d6a-2ea1-5417-a252-1e8bdc48423b', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 2, 2, 'እናንተ ሽማግሌዎች! ይህን ስሙ፤ በምድርም የምትኖሩ ሁሉ አድምጡ። ይህ በዘመናችሁ ወይስ በአባቶቻችሁ ዘመን ሆኖ ነበርን?'),
  ('570a0292-9fee-5fa7-ad90-70144dfd9ffc', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 3, 3, 'ይህን ለልጆቻችሁ ንገሩ፤ ልጆቻችሁም ለልጆቻቸው፥ ልጆቻቸውም ለኋለኛው ትውልድ ይንገሩ።'),
  ('5b4a94e7-5308-598a-a5b2-8c708e233f64', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 4, 4, 'ከተምች የቀረውን አንበጣ በላው፤ ከአንበጣም የቀረውን ደጎብያ በላው፤ ከደጎብያም የቀረውን ኩብኩባ በላው።'),
  ('94903e19-a731-5b96-a48b-716d37c7a0dc', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 5, 5, 'እናንተ ሰካራሞች፥ ንቁ፤ ለመስከርም ወይንን የምትጠጡ እናንተ ሁላችሁ! ተድላና ደስታ ከአፋችሁ ጠፍትዋልና አልቅሱ፤ እዘኑም።'),
  ('c64cd65c-5a64-5af2-a444-7818a9ab5232', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 6, 6, 'ቍጥርም የሌለው ብርቱ ሕዝብ በምድሬ ላይ ወጥቶአልና፤ ጥርሳቸው እንደ አንበሳ ጥርስ፥ ክንዳቸውም እንደ አንበሳ ደቦል ክንድ ነው።'),
  ('e320141c-2fa7-5c77-a876-fdd6ccaabb54', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 7, 7, 'ወይኔን ባዶ ምድር አደረገው፤ በለሴንም ሰበረው፤ ተመለከተውም፥ ጣለውም፤ ቅርንጫፎቹም ነጡ።'),
  ('62c28191-93b0-5dde-ab6a-8eba535f5c7f', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 8, 8, 'ስለ ልጅነት ባልዋ ማቅ ለብሳ እንደምታለቅስ ድንግል አልቅሺ።'),
  ('d3bc4e5d-14b8-55e2-ade0-22b01008ce4e', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 9, 9, 'መሥዋዕቱና የመጠጡ ቍርባን ከእግዚአብሔር ቤት ተወግዶአል፤ በእግዚአብሔርም መሠውያ የምታገለግሉ ካህናቱ፥ አልቅሱ።'),
  ('590cb2e4-60fc-5655-a56b-a675b5f4dc85', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 10, 10, 'እርሻው ምድረ በዳ ሆኖአል፤ ምድሪቱም ታልቅስ፤ እህሉ ጠፍቶአልና፥ ወይኑም ደርቆአልና፥ ዘይቱም ጐድሎአልና።'),
  ('c25ece99-ea50-5086-ad28-9e42051e962a', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 11, 11, 'መከሩ ከእርሻቸው ጠፍቶአልና ገበሬዎች ስለ ስንዴውና ስለ ገብሱ ዐፈሩ፤ የወይን አትክልተኞችም ስለ ወይኑ አለቀሱ።'),
  ('648a37fa-955e-5314-a911-3fb402c82efe', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 12, 12, 'ወይኑ ደርቆአል፤ በለሱም ጠፍቶአል፤ ሮማኑና ተምሩ፥ እንኮዩም፥ የምድርም ዛፎች ሁሉ ደርቀዋል፤ ደስታም ከሰው ልጆች ዘንድ ርቆአል።'),
  ('3aae9a0f-df6a-52d9-aeac-59f7a6361f80', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 13, 13, 'መሥዋዕቱና የመጠጡ ቍርባን ከአምላካችሁ ቤት ቀርቶአልና እናንተ ካህናት! ማቅ ታጥቃችሁ አልቅሱ፤ እናንተም የመሠውያ አገልጋዮች! ዋይ በሉ፤ እናንተም የእግዚአብሔር አገልጋዮች ኑና በማቅ ላይ ተኙ።'),
  ('2bb3a86a-49c4-51e5-a719-44c1a1ab0977', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 14, 14, 'ጾምን ቀድሱ፤ ምህላንም ዐውጁ፤ ሽማግሌዎቹንና በምድር የሚኖሩትን ሁሉ ወደ አምላካችን ወደ እግዚአብሔር ቤት ሰብስቡ፤ ወደ እግዚአብሔርም በአንድነት ጩኹ።'),
  ('fd25fbc1-ee1b-5058-adfc-df8715f014e3', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 15, 15, 'የእግዚአብሔር ቀን ቀርቦአልና ለቀኑ ወዮ! ወዮ! እርሱም በጥፋት ላይ እንደ ጥፋት ይመጣል።'),
  ('96d1a69e-ae3a-597c-ac7d-b5330880ded1', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 16, 16, 'ከዐይኖቻችሁ ፊት ምግብ፥ ከአምላካችሁም ቤት ደስታና ሐሤት ጠፍቶአል።'),
  ('02d7e771-5073-527e-aa11-1fd7e54b559f', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 17, 17, 'ጊደሮች ከምሳጋቸው ጠፉ፤ ጎተራዎች ባዶ ሆኑ፤ ዐውድማዎቹም ፈራረሱ፤ እህሉ ደርቆአልና።'),
  ('99166d45-2e87-5b45-a866-d4bf4b695098', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 18, 18, 'እንግዲህ ለራሳችን ምን እንሰብስብ? የእንስሳት ጠባቂዎች አለቀሱ፤ ማሰማሪያ የላቸውምና፥ የበጎች መንጋዎችም ጠፍተዋልና።'),
  ('5fa22e86-c7e3-5c32-a55d-205fd1709297', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 19, 19, 'አቤቱ! እሳት የምድረ በዳውን ውበት አጥፍቶአልና፥ ነበልባሉም የዱሩን ዛፍ ሁሉ አቃጥሎአልና ወደ አንተ እጮኻለሁ።'),
  ('07d14d4b-68f5-50b3-ac88-a754db62b6b8', 'a92870c4-a0eb-585b-adef-6922135e22d3', '0069ef20-75ab-5049-ac0f-c8a8ef559666', 20, 20, 'ፈሳሹ ውኃ ደርቆአልና፥ እሳቱም የምድረ በዳውን ውበት በልቶአልና የምድር አራዊት ወደ አንተ አንጋጠጡ።'),
  ('9b32366d-18cf-5e62-a71f-697539fc4396', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 1, 1, 'በጽዮን መለከትን ንፉ፤ በቅዱሱም ተራራዬ ላይ ዐዋጅ ንገሩ፤ በምድርም የሚኖሩ ሁሉ ይደንግጡ፤ የእግዚአብሔር ቀን መጥቶአልና፥ እርሱም ቀርቦአልና።'),
  ('ed5bdb7b-8df5-5aa1-a4f5-df3a9def8a58', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 2, 2, 'የጨለማና የነፋስ ቀን፥ የደመናና የጉም ቀን ነው፤ ታላቅና ብርቱ ሕዝብ በተራሮች ላይ እንደ ወገግታ ተዘርግቶአል፤ ከዘለዓለምም ጀምሮ እንደ እርሱ ያለ አልነበረም፤ ከእርሱም በኋላ እስከ ልጅ ልጅ ድረስ እንደ እርሱ ያለ አይሆንም።'),
  ('283fb07c-a96b-57b5-a5b0-974ab2becbae', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 3, 3, 'እሳት በፊታቸው ትበላለች፥ በኋላቸውም ነበልባል ታቃጥላለች፤ ምድሪቱ በፊታቸው እንደ ደስታ ገነት፥ በኋላቸውም እንደ ምድረ በዳ በረሃ ናት፤ ከእርሱም የሚያመልጥ የለም።'),
  ('1920584e-6bec-597d-ae6b-553be6f0e1d4', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 4, 4, 'መልካቸው እንደ ፈረስ መልክ ነው፤ እንደ ፈረሶችም ይሮጣሉ።'),
  ('a96bdfbc-bec5-597e-a466-b1a742338dce', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 5, 5, 'ድምፃቸውም በተራራ ላይ እንደ አሉ ሠረገሎች ድምፅ፥ ገለባውንም እንደሚበላ እንደ እሳት ነበልባል ድምፅ ነው፤ ለሰልፍም እንደ ተዘጋጀ እንደ ብዙና ብርቱ ሠራዊት ያኰበኵባሉ።'),
  ('e2ff790d-2133-5ea1-a047-5c216a043e36', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 6, 6, 'ከፊታቸው አሕዛብ ይንቀጠቀጣሉ፤ የሰውም ፊት ሁሉ እንደ ድስት ጥላሸት ይጠቍራል።'),
  ('0f5c0c1b-2ae2-59c8-a960-8b90ac64532a', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 7, 7, 'እንደ ተዋጊዎች ይሮጣሉ፤ እንደ ጦረኞችም በቅጥሩ ላይ ይወጣሉ፤ እያንዳንዱም በመንገዱ ላይ ይራመዳል፤ ከእርምጃቸውም አያፈገፍጉም።'),
  ('6495808a-ab5d-5eff-aaa7-a38676b05e44', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 8, 8, 'አንዱ ከሌላው ርቆ አይቆምም፤ የጦር መሣሪያቸውን ይዘው ይሮጣሉ፤ በመሣሪያቸው ላይ ይወድቃሉ፤ እነርሱም አይጠፉም።'),
  ('88475e0c-09b9-5703-a46f-196f7bf3543d', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 9, 9, 'ከተሞችን ይይዛሉ፤ በቅጥሩም ላይ ይሮጣሉ፤ ወደ ቤቶችም ይወጣሉ፤ እንደ ሌባም በመስኮቶች ይገባሉ።'),
  ('7cf438e7-387b-5da4-a990-fed364050ce6', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 10, 10, 'ምድሪቱም ከፊታቸው ትደነግጣለች፤ ሰማይም ይንቀጠቀጣል፤ ፀሐይና ጨረቃም ይጨልማሉ፤ ከዋክብትም ብርሃናቸውን ይሰውራሉ።'),
  ('4c057dc5-06c3-5f86-a30c-51c1d25235f9', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 11, 11, 'እግዚአብሔርም በሠራዊቱ ፊት ድምፁን ይሰጣል፤ ሰፈሩ እጅግ ብዙ ነውና፥ የቃሉም ሥራ ጽኑዕ ነውና፤ የእግዚአብሔርም ቀን ታላቅና እጅግ የምታስፈራ ናትና፥ ፈጽማ ትገለጣለች፥ መጠኗ ምንድን ነው? ማንስ ይችላታል?'),
  ('d44664bf-b0cd-5894-ac76-0ef9521c944b', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 12, 12, 'አሁንስ ይላል አምላካችሁ እግዚአብሔር፥ “በፍጹም ልባችሁ በጾም፥ በልቅሶና በዋይታ ወደ እኔ ተመለሱ።'),
  ('aaeaa9df-27e8-5c30-ab32-2062b2dc7663', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 13, 13, 'ልባችሁን እንጂ ልብሳችሁን አትቅደዱ፤ አምላካችሁም እግዚአብሔር መሓሪና ይቅር ባይ፥ ቍጣው የዘገየ ምሕረቱም የበዛ፥ ለክፋትም የተጸጸተ ነውና ወደ እርሱ ተመለሱ።”'),
  ('2e4a392e-0994-54b1-a188-d755d8dc26c3', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 14, 14, 'የሚመለስና የሚጸጸት እንደ ሆነ፥ ለአምላካችሁም ለእግዚአብሔር የእህልና የመጠጥ ቍርባን የሚሆን በረከትን በኋላ የሚያተርፍ እንደ ሆነ ማን ያውቃል?'),
  ('59644fab-63bf-5499-a517-09207f4d6077', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 15, 15, 'በጽዮን መለከትን ንፉ፤ ጾምንም ቀድሱ፤ ምህላንም ዐውጁ፤'),
  ('d2fe8440-1b0d-5237-a337-dfc4bb4e91ea', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 16, 16, 'ሕዝቡንም ሰብስቡ፤ ማኅበሩንም ቀድሱ፤ ሽማግሌዎቹንም ጥሩ፤ ጡት የሚጠቡትንና ሕፃናትን ሰብስቡ፤ ሙሽራው ከእልፍኙ፥ ሙሽራዪቱም ከጫጕላዋ ይውጡ።'),
  ('ea0411bb-c8dd-5cfc-a3a9-fa0d4fd5763b', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 17, 17, 'የእግዚአብሔርም አገልጋዮች ካህናት በወለሉና በምሥዋዑ መካከል እያለቀሱ፥ “አቤቱ! ለሕዝብህ ራራ፤ አሕዛብም ይገዙአቸው ዘንድ ርስትህን ለማላገጫ አሳልፈህ አትስጥ፤ ከአሕዛብም መካከል፦ አምላካቸው ወዴት ነው? ስለ ምን ይላሉ?” ይበሉ።'),
  ('c47599ea-65ff-5990-a127-689dbf0ef517', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 18, 18, 'እግዚአብሔርም ስለ ምድሩ ቀና፤ ለሕዝቡም ራራለት።'),
  ('8913c69f-20c3-5633-a242-93472a4cf71d', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 19, 19, 'እግዚአብሔርም መልሶ ሕዝቡን፥ “እነሆ እህልንና ወይንን፥ ዘይትንም እሰድድላችኋለሁ፤ እናንተም በእርሱ ትጠግባላችሁ፤ ከእንግዲህም ወዲያ በአሕዛብ መካከል መሰደቢያ አላደርጋችሁም።'),
  ('a8d91582-a719-571c-a414-4c22b829d754', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 20, 20, 'የሰሜንንም ሠራዊት ከእናንተ ዘንድ አርቃለሁ፤ ወደ በረሃና ወደ ምድረ በዳ እሰደዋለሁ፤ ፊቱን ወደ መጀመሪያው ባሕር፥ ጀርባውንም ወደ ኋለኛው ባሕር አድርጌ አሳድደዋለሁ፤ እርሱም ትዕቢትን አድርጎአልና ግማቱ ይወጣል፤ ክርፋቱም ይነሣል።”'),
  ('35e6d330-69a8-5824-a2dd-8c7e0f577800', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 21, 21, '“ምድር ሆይ! አትፍሪ፤ እግዚአብሔር ታላቅ ነገር አድርጎአልና ፈጽሞ ደስ ይበልሽ፤ ሐሤትም አድርጊ።'),
  ('e16fa810-11c8-52cf-ada7-22922e12d933', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 22, 22, 'እናንተ የምድር እንስሶች ሆይ! የምድረ በዳው ማሰማርያ ለምልሞአልና፥ ዛፉም ፍሬውን አፍርቶአልና፥ በለሱና ወይኑም ኀይላቸውን ሰጥተዋልና አትፍሩ።'),
  ('d8c94075-e509-536c-a013-a29c5491dc85', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 23, 23, 'እናንተ የጽዮን ልጆች ሆይ! በአምላካችሁ በእግዚአብሔር ደስ ይበላችሁ፤ ሐሤትም አድርጉ፤ ምግብን በጽድቅ ሰጥቶአችኋልና፥ እንደ ቀድሞውም የበልጉንና የመከሩን ዝናብ ያዘንብላችኋልና።'),
  ('2648f816-02c2-5207-a3d5-b787b9ce6cc7', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 24, 24, 'ዐውድማዎችም እህልን ይሞላሉ፤ መጭመቂያዎችም የወይን ጠጅንና ዘይትን አትረፍርፈው ያፈስሳሉ።'),
  ('58b68ab4-5b27-518f-a536-50832fa0ef9a', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 25, 25, 'የሰደድሁባችሁ ታላቁ ሠራዊቴ አንበጣና ደጎብያ፥ ኩብኩባና ተምች ስለ በላቸው ዓመታት እመልስላችኋለሁ።'),
  ('c0fb758f-419b-5aa6-a4b1-fe1928189364', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 26, 26, 'ብዙ መብል ትበላላችሁ፤ ትጠግቡማላችሁ፤ ከእናንተም ጋር ተአምራትን የሠራውን የአምላካችሁን የእግዚአብሔርን ስም ታመሰግናላችሁ፤ ሕዝቤም ለዘለዓለም አያፍርም።'),
  ('18719808-41b3-526d-add2-e412fd6b18ee', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 27, 27, 'እኔም በእስራኤል መካከል እንዳለሁ፥ እኔም አምላካችሁ እግዚአብሔር እንደ ሆንሁ፥ ከእኔም በቀር ሌላ አምላክ እንደሌለ ታውቃላችሁ፤ ሕዝቤም ለዘለዓለም አያፍርም።'),
  ('a02cfd79-9990-5701-ae26-6f72c81786fe', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 28, 28, '“ከዚህም በኋላ እንዲህ ይሆናል፤ መንፈሴን በሥጋ ለባሽ ሁሉ ላይ አፈስሳለሁ፤ ወንዶችና ሴቶች ልጆቻችሁም ትንቢትን ይናገራሉ፤ ሽማግሌዎቻችሁም ሕልምን ያልማሉ፤ ጐልማሶቻችሁም ራእይን ያያሉ፤'),
  ('68e8e104-3f71-55a0-ad26-c36943d0ae0d', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 29, 29, 'ደግሞም በዚያ ወራት በወንዶችና በሴቶች ባሪያዎች ላይ መንፈሴን አፈስሳለሁ።'),
  ('342e5785-cdd5-594a-a637-513a80ca4a9c', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 30, 30, 'በላይ በሰማይ ድንቆችን አሳያለሁ፤ በታች በምድርም ደምና እሳት የጢስም ጭጋግ።'),
  ('ef8f0d26-c174-52cd-a6a0-aafb87d6ef05', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 31, 31, 'ታላቋና ግልጥ የሆነችው የእግዚአብሔር ቀን ሳትመጣ ፀሐይ ወደ ጨለማ፥ ጨረቃም ወደ ደም ይለወጣል።'),
  ('5b68566c-9634-5075-ada3-f7788bfea182', 'c588909a-e8f9-52ae-a688-0e97ea5191a2', 'd1e99f98-db00-52f5-ad65-182d56576ae5', 32, 32, 'እንዲህም ይሆናል፤ የእግዚአብሔርን ስም የሚጠራ ሁሉ ይድናል፤ እግዚአብሔርም እንደ ተናገረ፥ በጽዮን ተራራና በኢየሩሳሌም ይድናሉ። ደግሞም እግዚአብሔር የጠራቸው፥ የምሥራች የሚሰበክላቸው ይገኛሉ።'),
  ('257c0dd4-174d-5a84-a535-d5e1ad706852', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 1, 1, '“እነሆም በዚያ ወራትና በዚያ ዘመን፥ የይሁዳንና የኢየሩሳሌምን ምርኮ እመልሳለሁ።'),
  ('7976f103-0d97-5ab8-af80-cdab81e03c43', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 2, 2, 'አሕዛብን ሁሉ እሰበስባቸዋለሁ፤ ወደ ኢዮሳፍጥም ሸለቆ አወርዳቸዋለሁ፤ በአሕዛብም መካከል በተበተኑበትና ምድሬን በተካፈሉበት በዚያ ስለ ወገኖች ስለ ርስቴ ስለ እስራኤል እወቅሳቸዋለሁ።'),
  ('f06f8c56-4851-5fc1-a647-8fa25daccebe', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 3, 3, 'በሕዝቤም ላይ ዕጣ ተጣጣሉ፤ ወንድ ልጅን ለአመንዝሮች ዋጋ ሰጡ፤ ሴት ልጅንም ለወይን ጠጅ ሸጡ፤ ጠጡም።'),
  ('0899f6e1-bdb6-51bc-aac9-52e9081989d6', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 4, 4, '“ጢሮስና ሲዶና የፍልስጥኤም አውራጃ ገሊላም ሁሉ ሆይ! ከእናንተ ጋራ ምን አለኝ? እናንተ በቀልን ትበቀሉኛላችሁን? ቂምንስ ትቀየሙኛላችሁን? ፈጥኜ በችኰላ ፍዳን በራሳችሁ ላይ እመልሳለሁ።'),
  ('aa53d0d3-d1bf-5a79-a2dc-3997d28bb99d', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 5, 5, 'ብሬንና ወርቄን ወስዳችኋልና፥ የተወደደውንም መልካሙን ዕቃዬን ወደ ቤተ መቅደሳችሁ አግብታችኋልና፥'),
  ('fc2eaa76-c2c2-58f1-a791-c6bd80cd97ed', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 6, 6, 'ከዳርቻቸውም ታርቁአቸው ዘንድ የይሁዳን ልጆችና የኢየሩሳሌምን ልጆች ለግሪክ ልጆች ሸጣችኋልና፥'),
  ('a562171b-2d13-5308-a06b-7313ca8bd824', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 7, 7, 'እነሆ እነርሱን ከሸጣችሁበት ስፍራ አስነሣቸዋለሁ፤ ብድራታችሁንም በራሳችሁ ላይ እመልሳለሁ።'),
  ('019d2c66-3a5b-5b9c-a95d-ba172377bed8', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 8, 8, 'ወንዶችና ሴቶች ልጆቻችሁን በይሁዳ ልጆች እጅ እሸጣለሁ፤ እነርሱም ለሩቆቹ ሕዝብ በምርኮ ይሸጡአችኋል። እግዚአብሔር ተናግሮአልና።'),
  ('74a3c200-55ab-551d-addd-ff1b0b223a9d', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 9, 9, '“ይህን በአሕዛብ መካከል ዐውጁ፤ ለሰልፍ ተዘጋጁ፤ ኀያላንን አስነሡ፤ ሰልፈኞች ሁሉ ይቅረቡ፤ ይውጡም።'),
  ('0a880077-7d92-5df8-a128-00ca387bbbc1', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 10, 10, 'ማረሻችሁን ሰይፍ፥ ማጭዳችሁንም ጦር ለማድረግ ቀጥቅጡ፤ ደካማውም፦ እኔ ብርቱ ነኝ ይበል።'),
  ('e32c09fc-5c94-5760-a771-7ee8daeb352b', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 11, 11, 'እናንተ በዙሪያ ያላችሁ አሕዛብ ሁሉ፥ ፈጥናችሁ ኑ፥ ተሰብሰቡ፤ የዋሃንም ሰልፈኞች ይሁኑ።'),
  ('b0a00d91-0c32-5f72-abad-855ffe1a3d1e', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 12, 12, '“አሕዛብ ሁሉ ይነሡ፤ ወደ ኢዮሣፍጥ ሸለቆም ይውጡ፤ በዙሪያ ባሉ አሕዛብ ሁሉ ላይ እፈርድ ዘንድ በዚያ እቀመጣለሁና።'),
  ('d41ae70d-1284-5bb6-ae87-cf7fb915d412', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 13, 13, 'መከሩ ደርሶአልና ማጭድ ስደዱ፤ መጭመቂያውም ሞልቶአልና ኑ ርገጡ፤ ክፋታቸውም በዝቶአልና መጭመቂያ ሁሉ ፈስሶአል።”'),
  ('e77e73cc-82c9-53e3-ac0a-4fd10f3ccc1c', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 14, 14, 'የእግዚአብሔር ቀን በፍርድ ሸለቆ ቀርቦአልና ውካታዎች በፍርድ ሸለቆ ተሰሙ።'),
  ('fcd497cd-98e5-5adf-a049-934297380d33', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 15, 15, 'ፀሐይና ጨረቃ ይጨልማሉ፤ ከዋክብትም ብርሃናቸውን ይሰውራሉ።'),
  ('3493bc22-1fd2-5767-a1ab-b01ada5b3560', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 16, 16, 'እግዚአብሔርም በጽዮን ሆኖ ድምፁን ከፍ አድርጎ ይጮኻል፤ በኢየሩሳሌምም ሆኖ ቃሉን ይሰጣል፤ ሰማይና ምድርም ይናወጣሉ፤ እግዚአብሔር ግን ለሕዝቡ ይራራል፤ የእስራኤልንም ልጆች ያጸናል።'),
  ('3a5f4021-62b0-5628-aedf-1c01d1a7400b', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 17, 17, '“እኔም በተቀደሰ ተራራዬ በጽዮን የምቀመጥ አምላካችሁ እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ፤ ያን ጊዜም ኢየሩሳሌም የተቀደሰች ከተማ ትሆናለች፥ እንግዶችም ከእንግዲህ ወዲህ አያልፉባትም።'),
  ('f8673490-5e92-5612-aa6c-e09a3b75c427', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 18, 18, '“በዚያም ቀን እንዲህ ይሆናል፤ ተራሮች ማርን ያንጠባጥባሉ፤ ኮረብቶችም ወተትን ያፈስሳሉ፤ በይሁዳም ያሉት ፈፋዎች ሁሉ ውኃን ያጐርፋሉ፤ ከእግዚአብሔርም ቤት ምንጭ ትፈልቃለች፤ የሰኪኖንንም ሸለቆ ታጠጣለች።'),
  ('2426a3fb-667e-532e-aff1-c247ea170d73', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 19, 19, 'በሀገራቸው ንጹሑን ደም አፍስሰዋልና በይሁዳ ልጆች ላይ ስለ አደረጉት ግፍ ግብፅ ምድረ በዳ፥ ኤዶምያስም በረሃ ይሆናል።'),
  ('aab4051b-c2be-5f23-abc4-05d68ad6c1b1', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 20, 20, 'ነገር ግን ይሁዳ ለዘለዓለም፥ ኢየሩሳሌምም ለልጅ ልጅ መኖሪያ ትሆናለች።'),
  ('3b5a13b4-69ee-5d1a-a74f-7440c2cbf411', '1f31d369-6efb-588c-a8c7-0f34b11d75eb', '0a32298f-bf2c-5b21-aec3-0bbed435a4cb', 21, 21, 'እኔም ደማቸውን እበቀላለሁ፤ አላነጻቸውምም፤ እግዚአብሔርም በጽዮን ያድራል።”'),
  ('22747866-2d19-5f91-a6ec-6a184a1bdc73', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b4a9e67c-9da8-58da-a282-47a57fbea9ca', 1, 1, 'የአብድዩ ራእይ።'),
  ('ccdf8e8b-5249-56fe-a080-c809c1f7bc8c', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b4a9e67c-9da8-58da-a282-47a57fbea9ca', 2, 2, 'እነሆ በአሕዛብ ዘንድ ታናሽ አድርጌሃለሁ፤ አንተ እጅግ ተንቀሃል።'),
  ('dfec6a84-be0a-5d53-abd6-ecef6cb4196b', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b4a9e67c-9da8-58da-a282-47a57fbea9ca', 3, 3, 'በተሰነጠቀም ዓለት ውስጥ እንደሚኖር- ማደሪያውንም ከፍ ከፍ እንደሚያደርግ፥ በልቡም፦ ወደ ምድር የሚያወርደኝ ማን ነው? እንደሚል፥ የልብህ ትዕቢት እጅግ አኵርቶሃል።'),
  ('523e3db9-e389-57ac-a0c9-cba8a14f04af', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b4a9e67c-9da8-58da-a282-47a57fbea9ca', 4, 4, 'እንደ ንስር መጥቀህ ብትወጣ፥ ቤትህም በከዋክብት መካከል ቢሆን፥ ከዚያ አወርድሃለሁ፥” ይላል እግዚአብሔር።'),
  ('6a712b76-0e91-5882-a08c-fb11793a6aa0', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b4a9e67c-9da8-58da-a282-47a57fbea9ca', 5, 5, '“ሌቦች ቢመጡብህ፥ ወይም ወንበዴዎች በሌሊት ቢመጡ፥ የሚበቃቸውን የሚሰርቁ አይደሉምን? ወይንም የሚቈርጡ ወደ አንተ ቢመጡ ቃርሚያ አያስቀሩምን?'),
  ('437fff09-9c97-57d4-af6e-f7030988cb30', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b4a9e67c-9da8-58da-a282-47a57fbea9ca', 6, 6, 'ዔሳውን እንዴት መረመሩት! የሸሸገውንም እንዴት ወሰዱበት!'),
  ('ca91d588-e0a9-5707-a899-5f20e003520f', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b4a9e67c-9da8-58da-a282-47a57fbea9ca', 7, 7, 'የተማማልሃቸው ሰዎች ሁሉ ወደ ዳርቻህ ሰደዱህ፤ የተስማሙህም ሰዎች ተነሡብህ፤ አሸነፉህም፤ በበታችህም አሽክላ ዘረጉብህ፤ እነርሱም ማስተዋል የላቸውም።'),
  ('89db8b5f-4850-5504-acf5-a935fab29fbb', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b4a9e67c-9da8-58da-a282-47a57fbea9ca', 8, 8, 'በዚያ ቀን ከኤዶምያስ ጥበበኞችን፥ ከዔሳው ተራራም ማስተዋልን አጠፋለሁ ይላል እግዚአብሔር።'),
  ('90333e2f-21d0-5d45-ae2b-22e318020bb6', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b4a9e67c-9da8-58da-a282-47a57fbea9ca', 9, 9, 'ከዔሳው ተራራ ሰዎች ሁሉ ይጠፉ ዘንድ የቴማን ሰልፈኞችህ ይደነግጣሉ።'),
  ('4d24b9f1-fc5c-5113-a44c-c07317851075', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b4a9e67c-9da8-58da-a282-47a57fbea9ca', 10, 10, '“በወንድምህ በያዕቆብ ላይ ስለ ተደረገ ኀጢአትና ግድያ ኀፍረት ይከድንሃል፤ ለዘለዓለምም ትጠፋለህ።'),
  ('f093b9cb-342d-542b-a8bf-bfe5a763d691', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b4a9e67c-9da8-58da-a282-47a57fbea9ca', 11, 11, 'በፊቱ አንጻር በቆምህ ቀን፥ አሕዛብ ጭፍራውን በማረኩበት፥ እንግዶችም በበሩ በገቡበት፥ በኢየሩሳሌምም ዕጣ በተጣጣሉበት ቀን አንተ ደግሞ ከእነርሱ እንደ አንዱ ነበርህ።'),
  ('63892ffc-d2a9-5952-a7b2-5b5158ccdf8c', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b4a9e67c-9da8-58da-a282-47a57fbea9ca', 12, 12, 'በጠላት ቀን ወንድምህን ዝቅ አድርገህ ትመለከተው ዘንድ፥ በጥፋታቸውም ቀን በይሁዳ ልጆች ላይ ደስ ይልህ ዘንድ፥ በጭንቀታቸውም ቀን በትዕቢት ትናገር ዘንድ ባልተገባህ ነበር።'),
  ('a64168cb-943a-5a2a-ade0-324990595bde', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b4a9e67c-9da8-58da-a282-47a57fbea9ca', 13, 13, 'በችግራቸውም ቀን በሕዝቤ በር ትገባ ዘንድ፥ በጥፋታቸውም ቀን ጉባኤያቸውን ትመለከት ዘንድ፥ በእልቂታቸውም ቀን በሠራዊታቸው ላይ አደጋ ትጥል ዘንድ አይገባህም ነበር።'),
  ('46d20f8f-6713-5ac3-a5d7-263502bbe217', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b4a9e67c-9da8-58da-a282-47a57fbea9ca', 14, 14, 'የሸሹትንም ለማጥፋት በመተላለፊያ መንገዳቸው ትቆም ዘንድ፥ ድል በተነሡበትም ቀን ከእርሱ ያመለጡትን ለማስጨነቅ ትከብባቸው ዘንድ ባልተገባህ ነበር።'),
  ('1e0dc010-1d55-5451-a827-04a11560869c', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'd08dd5c4-d086-5216-a210-7ab03cc86258', 1, 15, '“የእግዚአብሔር ቀን በአሕዛብ ሁሉ ላይ ቀርቦአልና፥ አንተ እንደ አደረግኸው እንዲሁ ይደረግብሃል፤ ፍዳህም በራስህ ላይ ይመለሳል።'),
  ('e9a5917b-05db-5085-a611-0303af47c3f8', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'd08dd5c4-d086-5216-a210-7ab03cc86258', 2, 16, 'በቅዱሱ ተራራዬ ላይ እንደ ጠጣህ እንዲሁ አሕዛብ ሁሉ ወይንን ይጠጣሉ፤ አዎን፥ ይጠጣሉ፥ ይጨልጡማል፤ እንዳልነበሩም ይሆናሉ።'),
  ('88e15839-827f-5b97-aea1-105a1bbf7c2e', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b3b8d0fc-b6ed-5cbc-abd2-0fd1b3ef3be7', 1, 17, '“ነገር ግን በጽዮን ተራራ ላይ መድኀኒት ይሆናል፤ እርሱም ቅዱስ ይሆናል፤ የያዕቆብም ቤት ሰዎች የወረሱአቸውን ይወርሳሉ።'),
  ('079d913e-546a-5b6e-a273-b5aad720e82f', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b3b8d0fc-b6ed-5cbc-abd2-0fd1b3ef3be7', 2, 18, 'እግዚአብሔርም ተናግሮአልና የያዕቆብ ቤት እሳት፥ የዮሴፍም ቤት ነበልባል፥ የዔሳውም ቤት ገለባ ይሆናሉ፤ እነርሱንም ያቃጥሉአቸዋል፤ ይበሉአቸውማል፤ ከዔሳውም ቤት ቅሬታ አይኖርም።'),
  ('7aa00e35-e0cb-529a-aadf-6f8a380f6d94', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b3b8d0fc-b6ed-5cbc-abd2-0fd1b3ef3be7', 3, 19, 'የደቡብም ሰዎች የዔሳውን ተራራ፥ የቆላውም ሰዎች ፍልስጥኤማውያንን ይወርሳሉ፤ የኤፍሬምንም ተራራ፥ የሰማርያን፥ የብንያምንና የገለዓድን ሀገር ይወርሳሉ።'),
  ('c0de5fc9-f4ab-561c-a018-928a605cfabd', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b3b8d0fc-b6ed-5cbc-abd2-0fd1b3ef3be7', 4, 20, 'ይህም የእስራኤል ልጆች የጭፍራቸው ምርኮ የከነዓንን ስፍራ ሁሉ እስከ ሰራጵታ ድረስ ይወርሳል፤ የኢየሩሳሌም ምርኮኞች እስከ ኤፍራታ ድረስ የደቡብን ከተሞች ይወርሳሉ።'),
  ('e4381ccf-b247-5bea-a107-4ab3b8accb66', '7edd5b45-0788-5f35-a2a9-d19570990c5b', 'b3b8d0fc-b6ed-5cbc-abd2-0fd1b3ef3be7', 5, 21, 'የዳኑትም የዔሳውን ተራራ ይበቀሉት ዘንድ ከጽዮን ተራራ ይዘምታሉ፤ መንግሥትም ለእግዚአብሔር ይሆናል።”'),
  ('7e8f5784-f1c5-5176-a2ed-1ab53c63e681', 'c3425ff5-865e-5de8-a929-ed2a636630dc', 'ba5a2fcf-e777-5b66-a97d-57a102593fcf', 1, 1, 'የእግዚአብሔር ቃል ወደ አማቴ ልጅ ወደ ዮናስ እንዲህ ሲል መጣ፦'),
  ('6c3513a3-1ea5-51d9-aa7f-59251a357438', 'c3425ff5-865e-5de8-a929-ed2a636630dc', 'ba5a2fcf-e777-5b66-a97d-57a102593fcf', 2, 2, '“ተነሥተህ ወደ ታላቂቱ ከተማ ወደ ነነዌ ሂድ፤ የክፋታቸውም ጩኸት ወደ ፊቴ ወጥቶአልና ለእነርሱ ስበክ።”'),
  ('e73b8ad7-7979-5ba0-a908-77f6ef6139b8', 'c3425ff5-865e-5de8-a929-ed2a636630dc', 'ba5a2fcf-e777-5b66-a97d-57a102593fcf', 3, 3, 'ዮናስ ግን ከእግዚአብሔር ፊት ወደ ተርሴስ ይሸሽ ዘንድ ተነሣ፤ ወደ ኢዮጴም ወረደ፤ ወደ ተርሴስም የምታልፍ መርከብ አገኘ፤ ከእግዚአብሔርም ፊት ኰብልሎ ከእነርሱ ጋር ወደ ተርሴስ ይሄድ ዘንድ ዋጋ ሰጥቶ ወደ እርስዋ ገባ።'),
  ('5d327ba9-6c6c-581c-a76f-eeeb415d4b79', 'c3425ff5-865e-5de8-a929-ed2a636630dc', 'ba5a2fcf-e777-5b66-a97d-57a102593fcf', 4, 4, 'እግዚአብሔርም በባሕሩ ላይ ታላቅ ነፋስን አመጣ፤ በባሕሩም ላይ ታላቅ ማዕበል ሆነ፤ መርከቢቱም ልትሰበር ቀረበች።'),
  ('76999dc2-8913-56a8-a3fa-bae267883248', 'c3425ff5-865e-5de8-a929-ed2a636630dc', 'ba5a2fcf-e777-5b66-a97d-57a102593fcf', 5, 5, 'መርከበኞቹም ፈሩ፤ እያንዳንዱም ወደ አምላኩ ጮኸ፤ መርከቢቱም እንድትቀልልላቸው በውስጥዋ የነበረውን ዕቃ ወደ ባሕር ጣሉት፤ ዮናስ ግን ወደ መርከቡ ውስጠኛው ክፍል ወርዶ ነበር፥ ተኝቶም ያንኳርፍ ነበር።')
